Tutor.registerIndex("hist-high", [
{"id":"hist-h-k1-01","kind":"unit","title":"선사 문화와 고대 국가의 발전","text":"유적과 유물로 본 선사 문화에서 출발해 고조선, 여러 나라, 삼국과 가야, 통일 신라와 발해로 이어진 고대 국가의 흐름을 정리합니다. 구석기·신석기·청동기 시대의 유적과 유물을 근거로 생활 모습의 변화를 설명할 수 있다. 고조선의 성립과 발전, 고조선 이후 여러 나라의 특징을 비교할 수 있다. 삼국과 가야가 중앙 집권 체제를 정비하고 경쟁한 과정을 설명할…","keywords":["뗀석기","간석기","고인돌","군장","8조법","사출도","율령","녹읍","해동성국","호족"],"ref":{"tab":"concepts","idx":0},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-01","grade":"h1"},
{"id":"hist-h-k1-01#c0","kind":"concept","title":"구석기와 신석기: 뗀석기에서 간석기로","text":"문자 기록이 없는 시대를 선사 시대라고 하며, 이 시대는 유적과 유물로 알아냅니다. 구분 · 구석기 시대 · 신석기 시대 시작 · 약 70만 년 전 · 기원전 8000년경 도구 · 뗀석기(주먹도끼, 찍개, 슴베찌르개) · 간석기(갈돌과 갈판), 빗살무늬 토기 경제 · 사냥, 채집, 물고","keywords":["뗀석기","간석기"],"ref":{"tab":"concepts","idx":0},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-01","grade":"h1"},
{"id":"hist-h-k1-01#c1","kind":"concept","title":"청동기 시대와 고조선","text":"한반도와 만주에서는 기원전 2000년~기원전 1500년경 청동기 시대가 시작되었습니다. 비파형 동검, 민무늬 토기, 반달 돌칼, 고인돌이 대표 유물·유적입니다. 벼농사가 시작되고 생산이 늘자 사유 재산과 계급이 생겼고, 청동 무기를 가진 군장이 부족을 이끌었습니다. 거대한 고인돌은 많은","keywords":["고인돌","군장"],"ref":{"tab":"concepts","idx":1},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-01","grade":"h1"},
{"id":"hist-h-k1-01#c2","kind":"concept","title":"고조선 이후 여러 나라의 성장","text":"철기 문화가 널리 퍼지면서 만주와 한반도 곳곳에 여러 나라가 성장하였습니다. 각 나라는 정치 형태와 풍습이 달랐습니다. 나라 · 정치 · 제천 행사·풍습 부여 · 왕 아래 마가·우가·저가·구가가 사출도를 따로 다스림 · 12월 영고, 순장 고구려 · 5부족 연맹, 대가들이 모인 제가 회","keywords":["군장","사출도"],"ref":{"tab":"concepts","idx":2},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-01","grade":"h1"},
{"id":"hist-h-k1-01#c3","kind":"concept","title":"삼국과 가야: 중앙 집권 체제의 정비와 경쟁","text":"삼국은 연맹 왕국에서 출발해 왕권을 강화하고 중앙 집권 국가로 발전하였습니다. 그 지표는 왕위의 부자 세습, 율령 반포(법으로 나라 조직을 정비), 불교 수용·공인(백성의 생각을 하나로 모으고 왕권을 뒷받침), 영토 확장입니다. 나라 · 체제 정비 · 전성기 고구려 · 소수림왕: 불교 ","keywords":["율령"],"ref":{"tab":"concepts","idx":3},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-01","grade":"h1"},
{"id":"hist-h-k1-01#c4","kind":"concept","title":"신라의 삼국 통일과 발해의 건국","text":"7세기에 고구려는 수·당의 침략을 막아 냈습니다(살수 대첩 612, 안시성 전투 645). 백제의 공격에 시달리던 신라는 김춘추가 당과 나당 동맹(648)을 맺었습니다. 백제 멸망(660): 나당 연합군이 사비성을 함락하였습니다. 고구려 멸망(668): 오랜 전쟁과 지배층의 내분으로 약","keywords":[],"ref":{"tab":"concepts","idx":4},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-01","grade":"h1"},
{"id":"hist-h-k1-01#c5","kind":"concept","title":"통일 신라와 발해의 통치 체제, 신라 말의 변동","text":"통일 신라는 신문왕 때 왕권을 크게 강화하였습니다. 김흠돌의 난을 진압하며 진골 귀족 세력을 숙청하였습니다. 귀족에게 관료전을 주고 녹읍을 폐지하였습니다. 녹읍은 땅에서 세금뿐 아니라 노동력까지 거둘 수 있어 귀족 세력의 바탕이었습니다. 국학을 세워 유학을 가르쳤습니다. 지방을 9주 5","keywords":["녹읍"],"ref":{"tab":"concepts","idx":5},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-01","grade":"h1"},
{"id":"hist-h-k1-01#t0","kind":"term","title":"뗀석기","text":"돌을 깨뜨리거나 떼어 내어 만든 구석기 시대의 도구입니다. 예: 주먹도끼, 찍개","keywords":["뗀석기"],"ref":{"tab":"terms","idx":0},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-01","grade":"h1"},
{"id":"hist-h-k1-01#t1","kind":"term","title":"간석기","text":"돌을 갈아서 다듬어 만든 신석기 시대의 도구입니다. 예: 갈돌과 갈판","keywords":["간석기"],"ref":{"tab":"terms","idx":1},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-01","grade":"h1"},
{"id":"hist-h-k1-01#t2","kind":"term","title":"고인돌","text":"청동기 시대 지배층(군장)의 무덤입니다. 큰 돌을 옮기려면 많은 사람을 동원해야 했으므로 강한 지배층이 있었음을 보여 줍니다.","keywords":["고인돌"],"ref":{"tab":"terms","idx":2},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-01","grade":"h1"},
{"id":"hist-h-k1-01#t3","kind":"term","title":"군장","text":"청동기 시대 이후 부족을 다스린 지배자입니다. 청동 무기와 제사 도구로 권위를 드러냈습니다.","keywords":["군장"],"ref":{"tab":"terms","idx":3},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-01","grade":"h1"},
{"id":"hist-h-k1-01#t4","kind":"term","title":"8조법","text":"고조선의 법으로, 3개 조항만 전합니다. 생명·노동력 중시, 사유 재산, 노비 신분이 있었음을 보여 줍니다.","keywords":["8조법"],"ref":{"tab":"terms","idx":4},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-01","grade":"h1"},
{"id":"hist-h-k1-01#t5","kind":"term","title":"사출도","text":"부여에서 왕 아래의 마가·우가·저가·구가가 각각 다스린 지역입니다. 왕권이 아직 약했음을 보여 줍니다.","keywords":["사출도"],"ref":{"tab":"terms","idx":5},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-01","grade":"h1"},
{"id":"hist-h-k1-01#t6","kind":"term","title":"율령","text":"나라를 다스리는 법입니다. 율은 형벌에 관한 법, 영은 행정 제도에 관한 법으로, 율령 반포는 중앙 집권 체제 정비의 지표입니다.","keywords":["율령"],"ref":{"tab":"terms","idx":6},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-01","grade":"h1"},
{"id":"hist-h-k1-01#t7","kind":"term","title":"녹읍","text":"신라에서 귀족 관리에게 준 땅으로, 세금과 함께 그 지역 백성의 노동력까지 거둘 수 있었습니다. 신문왕이 폐지하였습니다.","keywords":["녹읍"],"ref":{"tab":"terms","idx":7},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-01","grade":"h1"},
{"id":"hist-h-k1-01#t8","kind":"term","title":"해동성국","text":"\"바다 동쪽의 번성한 나라\"라는 뜻으로, 9세기 선왕 때 전성기를 맞은 발해를 부른 이름입니다.","keywords":["해동성국"],"ref":{"tab":"terms","idx":8},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-01","grade":"h1"},
{"id":"hist-h-k1-01#t9","kind":"term","title":"호족","text":"신라 말 지방에서 성장한 세력으로, 스스로 성주·장군이라 부르며 그 지역의 군사·행정·경제를 장악하였습니다.","keywords":["호족"],"ref":{"tab":"terms","idx":9},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-01","grade":"h1"},
{"id":"hist-h-k1-01#f0","kind":"faq","title":"단군 이야기는 신화인데 어떻게 역사로 배워요?","text":"단군 이야기는 그대로의 사실이라기보다, 그 안에 당시 사회 모습이 담긴 건국 이야기입니다. 환웅이 바람·비·구름을 다스리는 신하를 거느렸다는 내용에서 농경을 중시했음을, 곰을 숭배하는 부족과 결합했다는 내용에서 부족 간의 연합을 읽어 낼 수 있습니다. 그래서 이야기 자체보다 이야기가 보여 주는 사회의 모습을 역사로 공부합니다.","keywords":[],"ref":{"tab":"faq","idx":0},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-01","grade":"h1"},
{"id":"hist-h-k1-01#f1","kind":"faq","title":"연맹 왕국과 중앙 집권 국가는 무엇이 달라요?","text":"연맹 왕국은 왕이 있지만 여러 부족장이 자기 지역을 따로 다스리는 나라입니다(부여의 사출도, 고구려의 제가 회의). 중앙 집권 국가는 왕이 율령과 관리를 통해 나라 전체를 직접 다스리는 나라입니다. 왕위의 부자 세습, 율령 반포, 불교 공인이 중앙 집권 국가로 가는 대표적인 지표입니다.","keywords":[],"ref":{"tab":"faq","idx":1},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-01","grade":"h1"},
{"id":"hist-h-k1-01#f2","kind":"faq","title":"녹읍과 관료전은 무엇이 달라요?","text":"둘 다 관리에게 준 땅이지만, 녹읍은 그 땅의 세금과 함께 백성의 노동력까지 거둘 수 있었고, 관료전은 세금(곡식)만 거둘 수 있었습니다. 그래서 신문왕이 녹읍을 폐지하고 관료전을 준 것은 귀족의 힘을 줄이고 왕권을 강화한 조치로 평가합니다.","keywords":["녹읍"],"ref":{"tab":"faq","idx":2},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-01","grade":"h1"},
{"id":"hist-h-k1-01#m0","kind":"mistake","title":"자주 하는 실수","text":"빗살무늬 토기를 청동기 시대 유물로 혼동하는 실수 — 빗살무늬 토기는 신석기, 민무늬 토기는 청동기 시대의 대표 토기입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-01","grade":"h1"},
{"id":"hist-h-k1-01#m1","kind":"mistake","title":"자주 하는 실수","text":"제천 행사를 헷갈리는 실수 — 부여는 영고(12월), 고구려는 동맹(10월), 동예는 무천(10월)입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-01","grade":"h1"},
{"id":"hist-h-k1-01#m2","kind":"mistake","title":"자주 하는 실수","text":"불교 공인과 영토 확장을 같은 왕으로 기억하는 실수 — 신라에서 율령 반포·불교 공인은 법흥왕, 한강 유역 차지·대가야 정복은 진흥왕입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-01","grade":"h1"},
{"id":"hist-h-k1-02","kind":"unit","title":"고려의 통치 체제와 지배 세력","text":"고려가 후삼국을 통일하고 통치 체제를 갖춘 과정과, 호족에서 문벌 귀족·무신·권문세족·신진 사대부로 바뀐 지배 세력을 따라 고려 정치의 흐름을 이해합니다. 고려의 후삼국 통일 과정과 그 역사적 의미를 설명할 수 있다. 2성 6부와 도병마사 등 중앙 통치 조직과 본관제·향리 중심의 지방 제도를 설명할 수 있다. 호족에서 문벌 귀족, 무신, 권문세족, 신진 …","keywords":["노비안검법","2성 6부","도병마사","대간","본관제","향리","음서","교정도감","권문세족","신진 사대부"],"ref":{"tab":"concepts","idx":0},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-02","grade":"h1"},
{"id":"hist-h-k1-02#c0","kind":"concept","title":"후삼국 통일과 고려의 성립","text":"궁예의 신하였던 왕건은 918년 궁예를 몰아내고 고려를 세운 뒤 이듬해 송악(개경)으로 도읍을 옮겼습니다. 왕건은 신라에 우호적이고 후백제와는 맞서는 정책을 폈습니다. 935년: 신라의 경순왕이 고려에 항복하였습니다. 936년: 후백제를 멸망시켜 후삼국을 통일하였습니다. 고려의 통일은 ","keywords":[],"ref":{"tab":"concepts","idx":0},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-02","grade":"h1"},
{"id":"hist-h-k1-02#c1","kind":"concept","title":"중앙 통치 조직: 2성 6부와 도병마사","text":"고려는 당의 3성 6부를 받아들이되 고려 실정에 맞게 고쳐 2성 6부를 두었습니다. 기구 · 하는 일 중서문하성 · 최고 관서. 장관 문하시중이 국정 총괄. 재신은 정책 심의, 낭사는 정책 비판 상서성 · 6부(이·병·호·형·예·공)를 두고 정책을 집행 중추원 · 군사 기밀과 왕명 출납","keywords":["2성 6부","도병마사","대간"],"ref":{"tab":"concepts","idx":1},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-02","grade":"h1"},
{"id":"hist-h-k1-02#c2","kind":"concept","title":"지방 제도: 본관제와 향리","text":"고려의 지방 제도는 중앙이 모든 곳을 직접 다스리지 못하고 지방 세력의 자율성을 살린 것이 특징입니다. 전국을 일반 행정 구역인 5도와 국경 지대의 군사 구역인 양계(북계·동계)로 나누었습니다. 수도 주변은 경기라 하였습니다. 지방관이 파견된 주현보다 지방관이 없는 속현이 더 많았습니다","keywords":["본관제","향리"],"ref":{"tab":"concepts","idx":2},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-02","grade":"h1"},
{"id":"hist-h-k1-02#c3","kind":"concept","title":"문벌 귀족 사회와 그 동요","text":"고려 초의 지배 세력은 호족이었습니다. 시간이 흐르면서 호족과 신라 6두품 출신 가운데 대대로 높은 관직에 오른 가문들이 문벌 귀족을 이루었습니다. 음서: 5품 이상 고위 관리의 자손은 과거를 보지 않고도 관직에 오를 수 있었습니다. 공음전: 5품 이상 관리에게 주어 자손에게 물려줄 수","keywords":["음서"],"ref":{"tab":"concepts","idx":3},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-02","grade":"h1"},
{"id":"hist-h-k1-02#c4","kind":"concept","title":"무신 정권의 성립과 전개","text":"고려는 문신을 우대하고 무신을 차별하였습니다. 무신은 최고 관직에 오를 수 없었고, 군대를 지휘하는 일조차 문신이 맡는 경우가 많았습니다. 하급 군인들도 받아야 할 토지를 제대로 받지 못해 불만이 컸습니다. 1170년 정중부 등이 무신 정변을 일으켜 문신을 몰아내고 권력을 잡았습니다. ","keywords":["교정도감"],"ref":{"tab":"concepts","idx":4},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-02","grade":"h1"},
{"id":"hist-h-k1-02#c5","kind":"concept","title":"원 간섭기와 공민왕의 개혁","text":"몽골(원)과 강화한 뒤 80여 년 동안 고려는 원의 정치적 간섭을 받았습니다(원 간섭기). 고려 왕이 원의 공주와 혼인하여 원의 부마국이 되었고, 왕실 호칭과 관제가 격하되었습니다(중서문하성과 상서성 → 첨의부, 6부 → 4사). 원은 정동행성을 통해 내정에 간섭하고, 화주에 쌍성총관부","keywords":["도병마사","음서","권문세족"],"ref":{"tab":"concepts","idx":5},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-02","grade":"h1"},
{"id":"hist-h-k1-02#t0","kind":"term","title":"노비안검법","text":"광종이 시행한 법으로, 억울하게 노비가 된 사람을 조사하여 양인으로 되돌렸습니다. 호족의 경제·군사 기반을 약화하였습니다.","keywords":["노비안검법"],"ref":{"tab":"terms","idx":0},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-02","grade":"h1"},
{"id":"hist-h-k1-02#t1","kind":"term","title":"2성 6부","text":"고려의 중앙 통치 조직입니다. 2성은 중서문하성과 상서성, 6부는 상서성 아래의 이·병·호·형·예·공부입니다.","keywords":["2성 6부"],"ref":{"tab":"terms","idx":1},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-02","grade":"h1"},
{"id":"hist-h-k1-02#t2","kind":"term","title":"도병마사","text":"중서문하성의 재신과 중추원의 추밀이 모여 국방·군사 문제를 논의한 고려의 독자적 회의 기구입니다. 원 간섭기에 도평의사사로 바뀌었습니다.","keywords":["도병마사"],"ref":{"tab":"terms","idx":2},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-02","grade":"h1"},
{"id":"hist-h-k1-02#t3","kind":"term","title":"대간","text":"어사대의 관원과 중서문하성의 낭사를 함께 이르는 말로, 간쟁·봉박·서경으로 왕권과 관리를 견제하였습니다.","keywords":["대간"],"ref":{"tab":"terms","idx":3},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-02","grade":"h1"},
{"id":"hist-h-k1-02#t4","kind":"term","title":"본관제","text":"사람마다 출신 지역(본관)을 정하고 그 지역에 소속시켜 세금과 역을 지게 하며 거주 이전을 제한한 고려의 제도입니다.","keywords":["본관제"],"ref":{"tab":"terms","idx":4},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-02","grade":"h1"},
{"id":"hist-h-k1-02#t5","kind":"term","title":"향리","text":"고려에서 지방 행정의 실무를 맡은 그 지역 출신의 세력입니다. 속현에서는 사실상 지방을 이끌었습니다.","keywords":["향리"],"ref":{"tab":"terms","idx":5},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-02","grade":"h1"},
{"id":"hist-h-k1-02#t6","kind":"term","title":"음서","text":"5품 이상 고위 관리의 자손이 과거를 거치지 않고 관직에 오르는 제도로, 문벌 귀족의 특권이었습니다.","keywords":["음서"],"ref":{"tab":"terms","idx":6},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-02","grade":"h1"},
{"id":"hist-h-k1-02#t7","kind":"term","title":"교정도감","text":"최충헌이 설치한 최씨 무신 정권의 최고 권력 기구입니다.","keywords":["교정도감"],"ref":{"tab":"terms","idx":7},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-02","grade":"h1"},
{"id":"hist-h-k1-02#t8","kind":"term","title":"권문세족","text":"원 간섭기에 친원 세력을 중심으로 형성된 지배층입니다. 도평의사사를 장악하고 대농장을 소유하였습니다.","keywords":["권문세족"],"ref":{"tab":"terms","idx":8},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-02","grade":"h1"},
{"id":"hist-h-k1-02#t9","kind":"term","title":"신진 사대부","text":"고려 말 성리학을 공부하고 과거를 통해 관직에 진출한 새로운 세력입니다. 권문세족을 비판하며 개혁을 주장하였습니다.","keywords":["신진 사대부"],"ref":{"tab":"terms","idx":9},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-02","grade":"h1"},
{"id":"hist-h-k1-02#f0","kind":"faq","title":"고려 삼사랑 조선 삼사는 같은 거예요?","text":"이름만 같고 하는 일은 전혀 다릅니다. 고려의 삼사는 화폐와 곡식의 출납·회계를 맡은 기구이고, 조선의 삼사는 사헌부·사간원·홍문관으로 이루어진 언론 기관입니다. 고려에서 언론과 견제 역할을 한 것은 대간(어사대와 중서문하성의 낭사)입니다.","keywords":[],"ref":{"tab":"faq","idx":0},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-02","grade":"h1"},
{"id":"hist-h-k1-02#f1","kind":"faq","title":"문벌 귀족이랑 권문세족은 뭐가 달라요?","text":"문벌 귀족은 고려 전기에 음서와 공음전, 왕실과의 혼인으로 성장한 세력이고, 권문세족은 원 간섭기에 원과의 관계를 바탕으로 성장한 세력입니다. 권문세족은 도평의사사를 장악하고 대농장을 소유하며 백성을 수탈하여, 고려 말 신진 사대부의 비판을 받았습니다.","keywords":["권문세족"],"ref":{"tab":"faq","idx":1},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-02","grade":"h1"},
{"id":"hist-h-k1-02#f2","kind":"faq","title":"공민왕의 개혁은 왜 실패했어요?","text":"개혁으로 손해를 보는 권문세족의 반발이 컸고, 홍건적과 왜구가 잇따라 침입하여 나라가 어려웠습니다. 개혁을 뒷받침할 신진 사대부의 힘도 아직 충분히 크지 못하였습니다. 결국 공민왕이 시해되면서 개혁은 중단되었지만, 이 과정에서 성장한 신진 사대부와 신흥 무인 세력이 고려 말 정치를 이끌게 됩니다.","keywords":[],"ref":{"tab":"faq","idx":2},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-02","grade":"h1"},
{"id":"hist-h-k1-02#m0","kind":"mistake","title":"자주 하는 실수","text":"고려의 삼사를 조선의 삼사(언론 기관)로 착각하는 실수 — 고려의 삼사는 화폐와 곡식의 출납·회계 기구입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-02","grade":"h1"},
{"id":"hist-h-k1-02#m1","kind":"mistake","title":"자주 하는 실수","text":"노비안검법(광종)과 전민변정도감(공민왕)을 바꾸어 기억하는 실수 — 고려 초 호족 견제는 노비안검법, 고려 말 권문세족 견제는 전민변정도감입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-02","grade":"h1"},
{"id":"hist-h-k1-02#m2","kind":"mistake","title":"자주 하는 실수","text":"중방·교정도감·도방을 섞어 쓰는 실수 — 중방은 무신 정권 초기의 회의 기구, 교정도감은 최씨 정권의 최고 권력 기구, 도방은 최씨 정권의 사병 집단입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-02","grade":"h1"},
{"id":"hist-h-k1-03","kind":"unit","title":"조선의 성립과 정치 운영","text":"조선이 유교 이념으로 통치 체제를 세운 과정과 사림·붕당이 이끈 정치 운영의 변화, 왜란과 호란의 전개와 영향을 배웁니다. 조선의 건국 과정과 『경국대전』, 의정부·6조, 삼사 등 유교적 통치 체제를 설명할 수 있다. 훈구와 사림의 갈등, 사화의 전개를 정리할 수 있다. 사림의 집권과 붕당 정치의 전개 과정을 설명할 수 있다. 왜란과 호란의 전개와 영향,…","keywords":["과전법","『경국대전』","의정부","6조 직계제","삼사","사림","사화","붕당","중립 외교","주화론과 주전론"],"ref":{"tab":"concepts","idx":0},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-03","grade":"h1"},
{"id":"hist-h-k1-03#c0","kind":"concept","title":"조선의 건국과 체제 정비","text":"고려 말 신진 사대부는 개혁의 방향을 두고 나뉘었습니다. 고려 왕조 안에서 점진적으로 개혁하자는 온건파(정몽주 등)와, 새 왕조를 세우자는 혁명파(정도전 등)입니다. 위화도 회군(1388): 요동 정벌에 나섰던 이성계가 군대를 돌려 최영을 몰아내고 정치·군사 실권을 잡았습니다. 과전법(","keywords":["과전법","6조 직계제"],"ref":{"tab":"concepts","idx":0},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-03","grade":"h1"},
{"id":"hist-h-k1-03#c1","kind":"concept","title":"유교적 통치 체제: 의정부·6조와 삼사","text":"조선의 중앙 정치 기구는 왕권과 신권이 조화를 이루면서도 권력이 한곳에 쏠리지 않도록 짜여 있었습니다. 기구 · 하는 일 의정부 · 최고 정무 기구. 영의정·좌의정·우의정 세 정승이 합의하여 국정 총괄 6조 · 이조·호조·예조·병조·형조·공조가 실제 행정 집행 승정원 · 왕명 출납(왕의","keywords":["의정부","삼사"],"ref":{"tab":"concepts","idx":1},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-03","grade":"h1"},
{"id":"hist-h-k1-03#c2","kind":"concept","title":"훈구와 사림, 그리고 사화","text":"15세기 후반 조선 정치에는 두 세력이 있었습니다. 구분 · 훈구 · 사림 뿌리 · 세조 즉위 등에 공을 세운 공신 세력 · 고려 말 온건파 사대부의 학통을 이은 세력 기반 · 중앙의 고위 관직, 대농장 · 지방의 중소 지주, 향촌 사회 지향 · 중앙 집권, 부국강병 · 도덕과 의리 중","keywords":["삼사","사림","사화"],"ref":{"tab":"concepts","idx":2},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-03","grade":"h1"},
{"id":"hist-h-k1-03#c3","kind":"concept","title":"사림의 집권과 붕당 정치","text":"선조 때 사림이 정치의 주도권을 잡았습니다. 그런데 사림 안에서 정치 운영과 학문적 입장의 차이로 갈등이 생겼습니다. 동인과 서인(1575): 인사권을 가진 요직인 이조 전랑 자리를 둘러싸고 김효원을 지지하는 동인과 심의겸을 지지하는 서인으로 나뉘었습니다. 동인은 주로 이황·조식의 학문","keywords":["삼사","사림","붕당"],"ref":{"tab":"concepts","idx":3},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-03","grade":"h1"},
{"id":"hist-h-k1-03#c4","kind":"concept","title":"왜란의 전개와 영향","text":"1592년 일본(도요토미 히데요시)이 조선을 침략하여 임진왜란이 일어났습니다. 부산진과 동래성이 함락되고 일본군이 빠르게 북상하여 한양이 점령되었으며, 선조는 의주로 피란하였습니다. 그러나 조선은 점차 반격하였습니다. 수군: 이순신이 옥포·한산도 등에서 승리하여 남해의 제해권을 지켰습니","keywords":[],"ref":{"tab":"concepts","idx":4},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-03","grade":"h1"},
{"id":"hist-h-k1-03#c5","kind":"concept","title":"광해군의 외교와 호란","text":"왜란 뒤 즉위한 광해군은 전쟁의 상처를 회복하는 데 힘썼습니다. 토지 대장과 호적을 정비하고, 경기도에 대동법을 시행하였으며, 허준의 『동의보감』이 완성되었습니다. 이 무렵 만주에서 후금이 성장하여 명과 대립하였습니다. 광해군은 명의 요청으로 군대를 보내면서도 후금과 적대하지 않도록 하","keywords":["중립 외교"],"ref":{"tab":"concepts","idx":5},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-03","grade":"h1"},
{"id":"hist-h-k1-03#t0","kind":"term","title":"과전법","text":"1391년 신진 사대부가 시행한 토지 제도로, 관리에게 경기 지역 토지의 수조권을 주었습니다. 조선 건국 세력의 경제 기반이 되었습니다.","keywords":["과전법"],"ref":{"tab":"terms","idx":0},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-03","grade":"h1"},
{"id":"hist-h-k1-03#t1","kind":"term","title":"『경국대전』","text":"세조 때 편찬을 시작해 성종 때 완성·반포한 조선의 기본 법전입니다.","keywords":["『경국대전』"],"ref":{"tab":"terms","idx":1},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-03","grade":"h1"},
{"id":"hist-h-k1-03#t2","kind":"term","title":"의정부","text":"영의정·좌의정·우의정이 합의하여 국정을 총괄한 조선의 최고 정무 기구입니다.","keywords":["의정부"],"ref":{"tab":"terms","idx":2},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-03","grade":"h1"},
{"id":"hist-h-k1-03#t3","kind":"term","title":"6조 직계제","text":"6조가 의정부를 거치지 않고 왕에게 직접 보고하고 명령을 받는 방식으로, 태종과 세조가 왕권 강화를 위해 시행하였습니다.","keywords":["6조 직계제"],"ref":{"tab":"terms","idx":3},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-03","grade":"h1"},
{"id":"hist-h-k1-03#t4","kind":"term","title":"삼사","text":"조선의 사헌부·사간원·홍문관으로, 언론을 맡아 왕과 고위 관리의 권력 남용을 견제하였습니다.","keywords":["삼사"],"ref":{"tab":"terms","idx":4},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-03","grade":"h1"},
{"id":"hist-h-k1-03#t5","kind":"term","title":"사림","text":"고려 말 온건파 사대부의 학통을 이어 지방에서 성장한 세력으로, 성종 때 중앙에 진출하여 선조 때 정치를 주도하였습니다.","keywords":["사림"],"ref":{"tab":"terms","idx":5},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-03","grade":"h1"},
{"id":"hist-h-k1-03#t6","kind":"term","title":"사화","text":"훈구와 사림의 갈등 등으로 사림이 큰 화를 입은 사건입니다. 무오·갑자·기묘·을사사화가 있습니다.","keywords":["사화"],"ref":{"tab":"terms","idx":6},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-03","grade":"h1"},
{"id":"hist-h-k1-03#t7","kind":"term","title":"붕당","text":"학문과 정치적 입장을 같이하는 사람들의 정치 집단입니다. 선조 때 동인과 서인으로 처음 나뉘었습니다.","keywords":["붕당"],"ref":{"tab":"terms","idx":7},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-03","grade":"h1"},
{"id":"hist-h-k1-03#t8","kind":"term","title":"중립 외교","text":"광해군이 명과 후금 사이에서 어느 한쪽에 치우치지 않고 실리를 꾀한 외교 정책입니다.","keywords":["중립 외교"],"ref":{"tab":"terms","idx":8},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-03","grade":"h1"},
{"id":"hist-h-k1-03#t9","kind":"term","title":"주화론과 주전론","text":"병자호란 때 화의를 맺어 나라를 보존하자는 주장(주화론)과 끝까지 싸우자는 주장(주전론)입니다.","keywords":["주화론과 주전론"],"ref":{"tab":"terms","idx":9},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-03","grade":"h1"},
{"id":"hist-h-k1-03#f0","kind":"faq","title":"훈구와 사림은 둘 다 성리학을 공부했는데 뭐가 달라요?","text":"둘 다 성리학을 공부했지만 기반과 지향이 달랐습니다. 훈구는 세조 즉위 등에 공을 세운 공신 세력으로 중앙의 고위 관직과 대농장을 기반으로 부국강병을 중시하였습니다. 사림은 지방의 중소 지주로 도덕과 의리, 향촌 자치를 강조하며 훈구의 권력 독점과 비리를 비판하였습니다.","keywords":["사림"],"ref":{"tab":"faq","idx":0},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-03","grade":"h1"},
{"id":"hist-h-k1-03#f1","kind":"faq","title":"사화와 붕당은 뭐가 달라요?","text":"사화는 주로 훈구가 사림을 공격하여 사림이 큰 화를 입은 사건이고, 붕당은 사림이 정치를 주도하게 된 뒤 사림 내부에서 생긴 정치 집단입니다. 순서로 보면 사화를 이겨 낸 사림이 집권한 뒤에 붕당이 나타났습니다.","keywords":["사화","붕당"],"ref":{"tab":"faq","idx":1},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-03","grade":"h1"},
{"id":"hist-h-k1-03#f2","kind":"faq","title":"정묘호란이랑 병자호란은 어떻게 구별해요?","text":"상대 나라 이름과 결과로 구별합니다. 정묘호란(1627)은 후금이 쳐들어와 형제 관계를 맺었고, 병자호란(1636)은 국호를 청으로 바꾼 뒤 쳐들어와 군신 관계를 맺었습니다. 인조가 강화도로 피란한 것은 정묘호란, 남한산성에서 항전한 것은 병자호란입니다.","keywords":[],"ref":{"tab":"faq","idx":2},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-03","grade":"h1"},
{"id":"hist-h-k1-03#m0","kind":"mistake","title":"자주 하는 실수","text":"『조선경국전』(정도전)과 『경국대전』(성종 때 완성)을 같은 책으로 혼동하는 실수 — 앞은 통치 이념을 담은 책, 뒤는 국가의 기본 법전입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-03","grade":"h1"},
{"id":"hist-h-k1-03#m1","kind":"mistake","title":"자주 하는 실수","text":"동인과 서인 중 누가 다시 나뉘었는지 헷갈리는 실수 — 남인과 북인으로 나뉜 것은 동인입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-03","grade":"h1"},
{"id":"hist-h-k1-03#m2","kind":"mistake","title":"자주 하는 실수","text":"정묘호란과 병자호란의 결과를 바꾸어 쓰는 실수 — 정묘호란은 형제 관계, 병자호란은 군신 관계입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-03","grade":"h1"},
{"id":"hist-h-k1-04","kind":"unit","title":"조선 후기의 새로운 흐름","text":"왜란과 호란 이후 달라진 정치 운영과 붕당 정치의 변질, 탕평 정치, 세도 정치, 흥선 대원군의 개혁까지 조선 후기 정치의 흐름과 경제·사회·문화의 새로운 변화를 살펴봅니다. 양 난 이후 비변사의 강화와 5군영 성립 등 정치·군사 운영의 변화를 설명할 수 있다. 예송과 환국을 통해 붕당 정치가 변질된 과정을 설명할 수 있다. 영조·정조의 탕평 정치와 개혁…","keywords":["비변사","5군영","예송","환국","탕평 정치","균역법","규장각","세도 정치","삼정","호포제"],"ref":{"tab":"concepts","idx":0},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-04","grade":"h1"},
{"id":"hist-h-k1-04#c0","kind":"concept","title":"양 난 이후 정치·군사 운영의 변화: 비변사와 5군영","text":"비변사는 원래 16세기 초 왜구와 여진의 침입에 대비해 국방 문제를 논의하던 임시 회의 기구였습니다. 을묘왜변(1555)을 계기로 상설 기구가 되었고, 임진왜란을 거치며 3정승을 비롯한 고위 관리들이 모여 군사뿐 아니라 외교·재정·인사 등 국정 전반을 다루는 최고 기구가 되었습니다. 그","keywords":["비변사","5군영"],"ref":{"tab":"concepts","idx":0},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-04","grade":"h1"},
{"id":"hist-h-k1-04#c1","kind":"concept","title":"붕당 정치의 변질: 예송과 환국","text":"17세기 후반 붕당 정치는 서로 견제하며 공존하던 원칙에서 점점 멀어졌습니다. 예송은 현종 때 왕실 의례를 둘러싸고 서인과 남인이 벌인 논쟁입니다. 둘째 아들로 왕위에 오른 효종과 그 왕비가 세상을 떠났을 때, 효종의 계모인 자의 대비가 상복을 얼마 동안 입어야 하는지가 쟁점이었습니다.","keywords":["예송","환국"],"ref":{"tab":"concepts","idx":1},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-04","grade":"h1"},
{"id":"hist-h-k1-04#c2","kind":"concept","title":"영조와 정조의 탕평 정치","text":"붕당 사이의 대립이 극심해지자, 붕당을 고루 등용해 대립을 누그러뜨리고 왕권을 강화하려는 탕평 정치가 나타났습니다. 영조 탕평 의지를 알리기 위해 성균관 앞에 탕평비를 세웠습니다. 붕당의 근거지인 서원을 크게 정리하고, 이조 전랑의 권한을 줄였습니다. 균역법(1750): 군역을 지는 농","keywords":["탕평 정치","균역법","규장각"],"ref":{"tab":"concepts","idx":2},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-04","grade":"h1"},
{"id":"hist-h-k1-04#c3","kind":"concept","title":"세도 정치와 삼정의 문란, 농민 봉기","text":"정조가 세상을 떠난 뒤 순조·헌종·철종의 3대 60여 년 동안, 왕의 외척인 몇몇 가문(안동 김씨, 풍양 조씨 등)이 권력을 독점하였습니다. 이를 세도 정치라 합니다. 세도 가문은 비변사를 장악하고 주요 관직을 차지하였습니다. 과거 시험에서 부정이 잦았고, 돈을 받고 관직을 파는 매관매","keywords":["비변사","세도 정치","삼정"],"ref":{"tab":"concepts","idx":3},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-04","grade":"h1"},
{"id":"hist-h-k1-04#c4","kind":"concept","title":"흥선 대원군의 통치 체제 정비","text":"1863년 고종이 어린 나이에 왕위에 오르자, 아버지인 흥선 대원군이 실권을 잡았습니다. 대원군은 세도 정치로 흔들린 왕권을 강화하고 민생을 안정시키는 개혁을 추진하였습니다. 왕권 강화 세도 가문을 몰아내고 붕당과 지역을 가리지 않고 인재를 고루 등용하였습니다. 세도 정치의 중심이던 비","keywords":["비변사","세도 정치"],"ref":{"tab":"concepts","idx":4},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-04","grade":"h1"},
{"id":"hist-h-k1-04#c5","kind":"concept","title":"경제·사회·문화의 새로운 변화 (개관)","text":"조선 후기에는 정치 변화와 함께 경제·사회·문화 전반에 새로운 흐름이 나타났습니다. 자세한 내용은 뒤 단원에서 다시 배우므로 여기서는 큰 줄기를 잡습니다. 경제: 상품 화폐 경제의 발달 모내기법(이앙법)이 널리 퍼져 노동력이 줄고 생산이 늘었으며, 한 사람이 더 넓은 땅을 경작하는 광작","keywords":[],"ref":{"tab":"concepts","idx":5},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-04","grade":"h1"},
{"id":"hist-h-k1-04#t0","kind":"term","title":"비변사","text":"국방 문제를 논의하던 임시 기구에서 시작해, 임진왜란 이후 국정 전반을 다루는 최고 기구가 된 조선 후기의 기구입니다. 흥선 대원군이 축소·폐지하였습니다.","keywords":["비변사"],"ref":{"tab":"terms","idx":0},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-04","grade":"h1"},
{"id":"hist-h-k1-04#t1","kind":"term","title":"5군영","text":"조선 후기 중앙군으로, 훈련도감·어영청·총융청·수어청·금위영을 말합니다. 숙종 때 금위영 설치로 완성되었습니다.","keywords":["5군영"],"ref":{"tab":"terms","idx":1},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-04","grade":"h1"},
{"id":"hist-h-k1-04#t2","kind":"term","title":"예송","text":"현종 때 효종과 효종 왕비가 세상을 떠났을 때 자의 대비의 상복 기간을 두고 서인과 남인이 벌인 논쟁입니다.","keywords":["예송"],"ref":{"tab":"terms","idx":2},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-04","grade":"h1"},
{"id":"hist-h-k1-04#t3","kind":"term","title":"환국","text":"숙종 때 왕이 집권 붕당을 한꺼번에 바꾸어 정국을 급격히 전환한 일입니다. 경신·기사·갑술환국이 있습니다.","keywords":["환국"],"ref":{"tab":"terms","idx":3},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-04","grade":"h1"},
{"id":"hist-h-k1-04#t4","kind":"term","title":"탕평 정치","text":"붕당 사이의 대립을 누그러뜨리기 위해 여러 붕당의 인재를 고루 등용한 영조·정조의 정치입니다.","keywords":["탕평 정치"],"ref":{"tab":"terms","idx":4},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-04","grade":"h1"},
{"id":"hist-h-k1-04#t5","kind":"term","title":"균역법","text":"영조가 1750년에 시행한 법으로, 농민이 내던 군포를 2필에서 1필로 줄였습니다.","keywords":["균역법"],"ref":{"tab":"terms","idx":5},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-04","grade":"h1"},
{"id":"hist-h-k1-04#t6","kind":"term","title":"규장각","text":"정조가 키운 왕실 도서관이자 정책 연구 기관입니다. 서얼 출신 학자도 검서관으로 일하였습니다.","keywords":["규장각"],"ref":{"tab":"terms","idx":6},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-04","grade":"h1"},
{"id":"hist-h-k1-04#t7","kind":"term","title":"세도 정치","text":"순조·헌종·철종 때 소수의 외척 가문이 권력을 독점한 정치입니다.","keywords":["세도 정치"],"ref":{"tab":"terms","idx":7},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-04","grade":"h1"},
{"id":"hist-h-k1-04#t8","kind":"term","title":"삼정","text":"조선 후기 나라 재정의 바탕이 된 전정(토지세)·군정(군포)·환곡(곡식 대여)을 말합니다.","keywords":["삼정"],"ref":{"tab":"terms","idx":8},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-04","grade":"h1"},
{"id":"hist-h-k1-04#t9","kind":"term","title":"호포제","text":"흥선 대원군이 군포를 집 단위로 매겨 양반에게도 군포를 거둔 제도입니다.","keywords":["호포제"],"ref":{"tab":"terms","idx":9},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-04","grade":"h1"},
{"id":"hist-h-k1-04#f0","kind":"faq","title":"균역법이랑 대동법은 뭐가 달라요?","text":"대동법은 집집마다 특산물을 바치던 공납을 토지 결수에 따라 쌀 등으로 내게 한 제도이고(광해군 때 경기도에서 시작), 균역법은 군역을 지는 농민이 내던 군포를 2필에서 1필로 줄인 제도입니다(영조). 고친 세금의 종류가 다릅니다.","keywords":["균역법"],"ref":{"tab":"faq","idx":0},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-04","grade":"h1"},
{"id":"hist-h-k1-04#f1","kind":"faq","title":"예송이 상복 입는 기간 문제였다면 왜 그렇게 크게 싸웠어요?","text":"성리학을 따르던 조선에서 예법은 나라 질서의 바탕이었습니다. 상복 기간을 어떻게 정하느냐는 효종의 왕위 계승을 어떻게 보느냐, 곧 왕실을 사대부와 같게 볼지 다르게 볼지의 문제였습니다. 그래서 단순한 의례 논쟁을 넘어 왕권과 신권, 그리고 어느 붕당이 정국을 이끌지를 가르는 정치 싸움이 되었습니다.","keywords":["예송"],"ref":{"tab":"faq","idx":1},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-04","grade":"h1"},
{"id":"hist-h-k1-04#f2","kind":"faq","title":"흥선 대원군의 개혁은 잘한 거예요, 못한 거예요?","text":"두 면을 함께 봅니다. 세도 정치를 끝내고 서원 정리와 호포제로 백성의 부담을 덜고 왕권을 회복한 점은 긍정적으로 평가합니다. 반면 경복궁 중건 과정에서 원납전·당백전으로 백성의 생활을 어렵게 하였고, 기존 통치 체제를 다시 세우는 데 그쳤다는 한계가 있습니다.","keywords":[],"ref":{"tab":"faq","idx":2},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-04","grade":"h1"},
{"id":"hist-h-k1-04#m0","kind":"mistake","title":"자주 하는 실수","text":"예송과 환국을 같은 시기로 기억하는 실수 — 예송은 현종, 환국은 숙종 때의 일입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-04","grade":"h1"},
{"id":"hist-h-k1-04#m1","kind":"mistake","title":"자주 하는 실수","text":"균역법(영조)과 호포제(흥선 대원군)를 섞는 실수 — 균역법은 군포를 1필로 줄인 것이고, 호포제는 양반에게도 군포를 거둔 것입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-04","grade":"h1"},
{"id":"hist-h-k1-04#m2","kind":"mistake","title":"자주 하는 실수","text":"장용영을 5군영에 넣는 실수 — 장용영은 정조가 만든 국왕 친위 부대이고, 5군영은 훈련도감·어영청·총융청·수어청·금위영입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-04","grade":"h1"},
{"id":"hist-h-k1-05","kind":"unit","title":"전근대의 국제 관계와 교류","text":"고대부터 조선까지 우리 역사의 나라들이 주변 나라와 맺은 외교 관계와 교류의 모습을 시대별로 비교합니다. 조공·책봉 관계가 서로의 필요에 따른 외교 형식이었음을 설명할 수 있다. 고대 국가의 전쟁·동맹과 교류(일본과의 교류, 장보고의 해상 무역)를 정리할 수 있다. 고려의 다원적 국제 관계와 조선의 사대교린 정책을 비교할 수 있다. 시대에 따라 달라진 세…","keywords":["책봉","조공","나당 동맹","청해진","벽란도","다원적 국제 관계","사대교린","연행사","통신사","소중화 의식"],"ref":{"tab":"concepts","idx":0},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-05","grade":"h1"},
{"id":"hist-h-k1-05#c0","kind":"concept","title":"조공·책봉 관계의 성격","text":"전근대 동아시아에서는 중국 왕조를 중심으로 조공·책봉 관계라는 외교 형식이 널리 쓰였습니다. 책봉: 중국 황제가 주변 나라의 군주를 그 나라의 왕으로 인정하는 것 조공: 주변 나라가 사신을 보내 예물을 바치는 것. 중국은 답례품(회사품)을 내려 주었습니다. 겉으로는 위아래가 있는 관계처","keywords":["책봉","조공"],"ref":{"tab":"concepts","idx":0},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-05","grade":"h1"},
{"id":"hist-h-k1-05#c1","kind":"concept","title":"고대 국가의 전쟁과 동맹","text":"6세기 말 중국을 다시 통일한 수는 고구려를 여러 차례 침략했습니다. 고구려는 을지문덕이 이끈 살수 대첩(612년) 으로 수의 대군을 물리쳤고, 무리한 전쟁은 수가 멸망하는 원인이 되었습니다. 뒤를 이은 당도 고구려를 공격했지만, 고구려는 안시성 전투(645년) 에서 당 태종의 군대를 ","keywords":["나당 동맹"],"ref":{"tab":"concepts","idx":1},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-05","grade":"h1"},
{"id":"hist-h-k1-05#c2","kind":"concept","title":"고대의 교류: 일본과 장보고의 해상 무역","text":"고대 국가들은 전쟁만 한 것이 아니라 활발히 교류했습니다. 일본과의 교류: 삼국의 문화는 바다 건너 일본 고대 문화에 큰 영향을 주었습니다. 백제의 왕인은 일본에 한학(유학 경전과 한자)을 전했다고 알려져 있고, 고구려의 담징은 종이와 먹 만드는 법을 전했다고 합니다. 통일 이후 신라와","keywords":["청해진"],"ref":{"tab":"concepts","idx":2},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-05","grade":"h1"},
{"id":"hist-h-k1-05#c3","kind":"concept","title":"고려의 다원적 국제 관계와 벽란도","text":"고려 시대 동아시아에는 송, 거란(요), 여진(금), 몽골(원) 등 여러 세력이 함께 있었습니다. 고려는 어느 한 나라만 따르지 않고 상황에 맞게 관계를 맺었는데, 이를 다원적 국제 관계라고 합니다. 송: 친선 관계. 문화와 경제 교류가 활발했습니다. 거란: 세 차례 침입. 서희의 외교","keywords":["벽란도","다원적 국제 관계"],"ref":{"tab":"concepts","idx":3},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-05","grade":"h1"},
{"id":"hist-h-k1-05#c4","kind":"concept","title":"조선의 사대교린 정책과 사신 왕래","text":"조선의 기본 외교 방침은 사대교린이었습니다. 사대: 큰 나라인 명(뒤에는 청)과 조공·책봉 관계를 맺어 나라의 안정과 왕권의 정통성을 얻었습니다. 교린: 이웃인 일본·여진과 대등하게 사귀되, 회유와 강경책을 함께 썼습니다. 여진에게는 무역소를 열어 주면서도 세종 때 4군 6진을 개척했고","keywords":["책봉","조공","사대교린","연행사","통신사"],"ref":{"tab":"concepts","idx":4},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-05","grade":"h1"},
{"id":"hist-h-k1-05#c5","kind":"concept","title":"세계관과 대외 인식의 변화","text":"사람들이 세상을 바라보는 틀, 곧 세계관도 시대마다 달라졌습니다. 독자적 천하관: 고구려는 광개토 대왕 때 '영락'이라는 독자 연호를 쓰고 자기 나라를 천하의 중심으로 여겼습니다. 고려도 안으로는 황제국의 격식을 쓰기도 했습니다. 화이관과 소중화 의식: 조선은 명을 문명의 중심(중화)으","keywords":["연행사","소중화 의식"],"ref":{"tab":"concepts","idx":5},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-05","grade":"h1"},
{"id":"hist-h-k1-05#t0","kind":"term","title":"책봉","text":"중국 황제가 주변 나라의 군주를 그 나라의 왕으로 인정하는 일입니다.","keywords":["책봉"],"ref":{"tab":"terms","idx":0},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-05","grade":"h1"},
{"id":"hist-h-k1-05#t1","kind":"term","title":"조공","text":"주변 나라가 중국 왕조에 사신을 보내 예물을 바치는 일입니다. 중국은 답례품을 내려 주어 사실상 교역의 기능도 했습니다.","keywords":["조공"],"ref":{"tab":"terms","idx":1},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-05","grade":"h1"},
{"id":"hist-h-k1-05#t2","kind":"term","title":"나당 동맹","text":"648년 신라가 김춘추를 보내 당과 맺은 군사 동맹입니다. 백제·고구려 멸망으로 이어졌습니다.","keywords":["나당 동맹"],"ref":{"tab":"terms","idx":2},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-05","grade":"h1"},
{"id":"hist-h-k1-05#t3","kind":"term","title":"청해진","text":"9세기 전반 장보고가 완도에 세운 군사·무역 기지입니다(828년). 신라·당·일본을 잇는 해상 무역의 중심이었습니다.","keywords":["청해진"],"ref":{"tab":"terms","idx":3},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-05","grade":"h1"},
{"id":"hist-h-k1-05#t4","kind":"term","title":"벽란도","text":"개경 가까운 예성강 하구에 있던 고려의 국제 무역항입니다. 송·일본·아라비아 상인이 드나들었습니다.","keywords":["벽란도"],"ref":{"tab":"terms","idx":4},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-05","grade":"h1"},
{"id":"hist-h-k1-05#t5","kind":"term","title":"다원적 국제 관계","text":"여러 세력이 함께 있던 시기에 한 나라만 따르지 않고 상대에 따라 다른 관계를 맺은 고려의 외교 방식입니다.","keywords":["다원적 국제 관계"],"ref":{"tab":"terms","idx":5},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-05","grade":"h1"},
{"id":"hist-h-k1-05#t6","kind":"term","title":"사대교린","text":"큰 나라(명·청)는 섬기고(사대), 이웃(일본·여진)과는 사귀는(교린) 조선의 외교 방침입니다.","keywords":["사대교린"],"ref":{"tab":"terms","idx":6},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-05","grade":"h1"},
{"id":"hist-h-k1-05#t7","kind":"term","title":"연행사","text":"조선이 청의 수도 연경(베이징)에 보낸 사신입니다. 청과 서양의 문물을 들여오는 통로가 되었습니다.","keywords":["연행사"],"ref":{"tab":"terms","idx":7},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-05","grade":"h1"},
{"id":"hist-h-k1-05#t8","kind":"term","title":"통신사","text":"조선이 일본에 보낸 외교 사절입니다. 임진왜란 뒤 국교가 다시 열리면서 19세기 초까지 12차례 파견되었습니다.","keywords":["통신사"],"ref":{"tab":"terms","idx":8},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-05","grade":"h1"},
{"id":"hist-h-k1-05#t9","kind":"term","title":"소중화 의식","text":"명이 멸망한 뒤 조선이 중화 문화를 이은 유일한 나라라고 여긴 생각입니다.","keywords":["소중화 의식"],"ref":{"tab":"terms","idx":9},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-05","grade":"h1"},
{"id":"hist-h-k1-05#f0","kind":"faq","title":"조공을 바쳤다면 중국의 속국이었던 거 아니에요?","text":"조공·책봉은 동아시아에서 널리 쓰인 외교 형식이었습니다. 대개 중국은 주변 나라의 왕위 계승·관리 임명·세금 같은 내정에 직접 간섭하지 않았고, 주변 나라는 스스로 나라를 다스렸습니다. 다만 원 간섭기처럼 실제 간섭이 심했던 시기는 따로 구분해서 보아야 합니다.","keywords":["조공"],"ref":{"tab":"faq","idx":0},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-05","grade":"h1"},
{"id":"hist-h-k1-05#f1","kind":"faq","title":"고려는 왜 송을 좋아하면서 거란이나 금에는 사대했어요?","text":"고려는 감정보다 나라의 안전과 실리를 기준으로 외교를 했습니다. 문화·경제 교류는 송과 활발히 하면서도, 군사적으로 강한 거란·금과는 전쟁과 외교를 함께 써서 나라를 지켰습니다. 이것을 다원적 국제 관계라고 합니다.","keywords":[],"ref":{"tab":"faq","idx":1},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-05","grade":"h1"},
{"id":"hist-h-k1-05#f2","kind":"faq","title":"연행사와 통신사는 어떻게 구분해요?","text":"어디로 갔는지로 구분합니다. 연행사는 청의 수도 \"연경\"에 갔기 때문에 붙은 이름이고, 통신사는 일본에 간 사절입니다. 연행사는 청과 서양 문물을 들여오는 통로였고, 통신사는 조선 문화를 일본에 전하는 역할도 했습니다.","keywords":["연행사","통신사"],"ref":{"tab":"faq","idx":2},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-05","grade":"h1"},
{"id":"hist-h-k1-05#m0","kind":"mistake","title":"자주 하는 실수","text":"서희와 윤관을 바꾸어 기억하는 실수 — 서희는 거란과 담판(강동 6주), 윤관은 여진 정벌(별무반, 동북 9성)입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-05","grade":"h1"},
{"id":"hist-h-k1-05#m1","kind":"mistake","title":"자주 하는 실수","text":"연행사와 통신사를 헷갈리는 실수 — 연행사는 청(연경), 통신사는 일본으로 갔습니다.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-05","grade":"h1"},
{"id":"hist-h-k1-05#m2","kind":"mistake","title":"자주 하는 실수","text":"소중화 의식을 \"중국을 따르자는 생각\"으로만 이해하는 실수 — 명이 망한 뒤 청을 오랑캐로 보고 조선이 중화를 이었다고 여긴 생각입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-05","grade":"h1"},
{"id":"hist-h-k1-06","kind":"unit","title":"수취 체제와 경제생활","text":"나라가 백성에게 세금을 거둔 방식이 시대마다 어떻게 바뀌었고, 그것이 농민의 삶과 경제에 어떤 영향을 주었는지 탐구합니다. 전근대 수취 체제의 기본 구조(조세·공납·역)를 설명할 수 있다. 관리에게 준 토지 제도(녹읍·관료전, 전시과, 과전법·직전법)의 변화를 정리할 수 있다. 조선 후기 수취 제도의 개편(영정법·대동법·균역법)이 나온 배경과 결과를 설명…","keywords":["수취 체제","신라 촌락 문서","녹읍","수조권","전시과","과전법","대동법","균역법","모내기법","공인"],"ref":{"tab":"concepts","idx":0},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-06","grade":"h1"},
{"id":"hist-h-k1-06#c0","kind":"concept","title":"수취 체제의 기본 구조와 신라 촌락 문서","text":"전근대 국가가 백성에게서 거두는 것은 크게 세 가지였습니다. 이를 수취 체제라고 합니다. 구분 · 무엇을 · 기준 조세(전세) · 토지에서 거둔 곡물 · 토지 공납 · 지역의 특산물 · 집(호) 역 · 노동력(군대에 가는 군역, 공사에 동원되는 요역) · 사람(정남) 나라가 세금을 고르","keywords":["수취 체제","신라 촌락 문서"],"ref":{"tab":"concepts","idx":0},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-06","grade":"h1"},
{"id":"hist-h-k1-06#c1","kind":"concept","title":"관리에게 준 토지 제도의 변화","text":"나라는 관리에게 월급처럼 토지를 주었습니다. 이때 준 것은 땅 자체가 아니라 그 땅에서 세금을 거둘 수 있는 권리(수조권) 인 경우가 많았습니다. 시대 · 제도 · 특징 신라 · 녹읍 · 조세뿐 아니라 그 지역 백성의 노동력까지 거둠 → 귀족의 힘이 커짐 통일 신라 · 관료전 (신문왕)","keywords":["녹읍","수조권","전시과","과전법"],"ref":{"tab":"concepts","idx":1},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-06","grade":"h1"},
{"id":"hist-h-k1-06#c2","kind":"concept","title":"수취 부담과 백성의 삶","text":"세금 제도가 법에 잘 적혀 있어도, 실제로 거두는 과정에서 백성의 부담은 무거워지곤 했습니다. 조선 시대에 특히 문제가 된 것은 공납과 군역이었습니다. 방납의 폐단(공납): 공물은 그 지역에서 나지 않는 물건이 배정되기도 했습니다. 그러자 관리·상인이 공물을 대신 바치고 백성에게 몇 배","keywords":[],"ref":{"tab":"concepts","idx":2},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-06","grade":"h1"},
{"id":"hist-h-k1-06#c3","kind":"concept","title":"조선 후기 수취 제도의 개편","text":"왜란과 호란으로 농토가 황폐해지고 백성의 부담이 커지자, 조선 정부는 수취 제도를 고쳤습니다. 공통된 방향은 부담을 줄이고, 토지를 기준으로 거두는 것이었습니다. 제도 · 시기 · 무엇을 고쳤나 영정법 · 인조(1635년) · 전세를 풍년·흉년과 상관없이 토지 1결당 쌀 4~6두로 고정","keywords":["대동법","균역법","공인"],"ref":{"tab":"concepts","idx":3},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-06","grade":"h1"},
{"id":"hist-h-k1-06#c4","kind":"concept","title":"농업 기술의 발달과 농민의 경제생활","text":"세금의 바탕은 농업이었고, 농업 기술의 발달은 농민의 삶을 바꾸었습니다. 깊이갈이(심경법): 소에 쟁기를 매어 땅을 깊이 가는 방법입니다. 신라 지증왕 때 소를 이용한 농사(우경)를 장려했다는 기록이 있고, 고려 시대에 널리 퍼졌습니다. 시비법: 거름을 주어 땅의 힘을 되살리는 방법입니","keywords":["모내기법"],"ref":{"tab":"concepts","idx":4},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-06","grade":"h1"},
{"id":"hist-h-k1-06#c5","kind":"concept","title":"조선 후기 상품 화폐 경제의 발달","text":"농업 생산이 늘고 대동법으로 공인이 등장하면서, 조선 후기에는 물건을 사고파는 경제가 크게 발달했습니다. 상품 작물: 내다 팔기 위해 인삼, 담배, 면화, 채소 등을 길렀습니다. 장시: 15세기 후반 남부 지방에서 생긴 장시가 18세기 중엽에는 전국 1,000여 곳으로 늘었습니다. 대개","keywords":["대동법","공인"],"ref":{"tab":"concepts","idx":5},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-06","grade":"h1"},
{"id":"hist-h-k1-06#t0","kind":"term","title":"수취 체제","text":"나라가 백성에게서 세금을 거두는 제도입니다. 조세(토지)·공납(특산물)·역(노동력)으로 이루어졌습니다.","keywords":["수취 체제"],"ref":{"tab":"terms","idx":0},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-06","grade":"h1"},
{"id":"hist-h-k1-06#t1","kind":"term","title":"신라 촌락 문서","text":"서원경 부근 네 마을의 인구·토지·가축·나무 수 등을 3년마다 기록한 통일 신라의 문서입니다. 일본 도다이사 쇼소인에서 발견되었습니다.","keywords":["신라 촌락 문서"],"ref":{"tab":"terms","idx":1},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-06","grade":"h1"},
{"id":"hist-h-k1-06#t2","kind":"term","title":"녹읍","text":"신라에서 귀족 관리에게 준 지역으로, 조세뿐 아니라 그곳 백성의 노동력까지 거둘 수 있었습니다.","keywords":["녹읍"],"ref":{"tab":"terms","idx":2},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-06","grade":"h1"},
{"id":"hist-h-k1-06#t3","kind":"term","title":"수조권","text":"토지에서 세금(조세)을 거둘 수 있는 권리입니다. 땅을 가진 권리(소유권)와는 다릅니다.","keywords":["수조권"],"ref":{"tab":"terms","idx":3},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-06","grade":"h1"},
{"id":"hist-h-k1-06#t4","kind":"term","title":"전시과","text":"고려에서 관리에게 관직에 따라 전지(농사지을 땅)와 시지(땔감 얻을 땅)의 수조권을 나누어 준 제도입니다.","keywords":["전시과"],"ref":{"tab":"terms","idx":4},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-06","grade":"h1"},
{"id":"hist-h-k1-06#t5","kind":"term","title":"과전법","text":"1391년 신진 사대부가 마련한 토지 제도입니다. 경기 지역 토지의 수조권을 전·현직 관리에게 주었습니다.","keywords":["과전법"],"ref":{"tab":"terms","idx":5},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-06","grade":"h1"},
{"id":"hist-h-k1-06#t6","kind":"term","title":"대동법","text":"공납을 집마다 특산물로 내던 것을 토지 결수에 따라 쌀·옷감·동전으로 내게 한 조선 후기의 제도입니다.","keywords":["대동법"],"ref":{"tab":"terms","idx":6},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-06","grade":"h1"},
{"id":"hist-h-k1-06#t7","kind":"term","title":"균역법","text":"1750년 영조가 군포를 1년에 2필에서 1필로 줄인 제도입니다.","keywords":["균역법"],"ref":{"tab":"terms","idx":7},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-06","grade":"h1"},
{"id":"hist-h-k1-06#t8","kind":"term","title":"모내기법","text":"모판에서 기른 모를 논에 옮겨 심는 농사법(이앙법)입니다. 김매기 노동이 줄고 이모작이 쉬워졌습니다.","keywords":["모내기법"],"ref":{"tab":"terms","idx":8},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-06","grade":"h1"},
{"id":"hist-h-k1-06#t9","kind":"term","title":"공인","text":"대동법 시행 뒤 나라에서 값을 받아 필요한 물품을 사서 바친 상인입니다.","keywords":["공인"],"ref":{"tab":"terms","idx":9},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-06","grade":"h1"},
{"id":"hist-h-k1-06#f0","kind":"faq","title":"수조권이랑 소유권은 뭐가 달라요?","text":"소유권은 땅을 가진 권리이고, 수조권은 남의 땅에서 세금(조세)을 거둘 수 있는 권리입니다. 전시과나 과전법에서 관리가 받은 것은 대부분 수조권이었습니다. 그래서 땅을 실제로 가진 농민은 그대로 농사를 짓고, 내는 세금을 관리가 받아 갔습니다.","keywords":["수조권"],"ref":{"tab":"faq","idx":0},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-06","grade":"h1"},
{"id":"hist-h-k1-06#f1","kind":"faq","title":"대동법이랑 균역법이 헷갈려요.","text":"무엇을 고쳤는지로 나누면 쉽습니다. 대동법은 공납(특산물)을 고쳐 토지 결수에 따라 쌀 등으로 내게 했고, 균역법은 군역(군포)을 고쳐 2필을 1필로 줄였습니다. 영정법은 전세를 고정한 제도입니다.","keywords":["대동법","균역법"],"ref":{"tab":"faq","idx":1},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-06","grade":"h1"},
{"id":"hist-h-k1-06#f2","kind":"faq","title":"조선 후기에 장사하는 사람이 왜 그렇게 늘었어요?","text":"농업 생산이 늘어 팔 물건이 생겼고, 대동법으로 공인이 등장해 나라도 물건을 사들이게 되었습니다. 상평통보가 널리 쓰여 거래가 편해졌고, 장시가 전국에 퍼졌습니다. 신해통공으로 시전 상인의 특권도 줄어 사상의 활동이 더 자유로워졌습니다.","keywords":[],"ref":{"tab":"faq","idx":2},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-06","grade":"h1"},
{"id":"hist-h-k1-06#m0","kind":"mistake","title":"자주 하는 실수","text":"세 수취 제도 개편을 헷갈리는 실수 — 영정법은 전세, 대동법은 공납, 균역법은 군역(군포)을 고쳤습니다.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-06","grade":"h1"},
{"id":"hist-h-k1-06#m1","kind":"mistake","title":"자주 하는 실수","text":"고려 숙종의 해동통보와 조선 숙종의 상평통보를 헷갈리는 실수 — 전국에 널리 쓰인 것은 조선 숙종 때의 상평통보입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-06","grade":"h1"},
{"id":"hist-h-k1-06#m2","kind":"mistake","title":"자주 하는 실수","text":"관리가 받은 토지를 \"땅의 주인이 된 것\"으로 생각하는 실수 — 대부분은 세금을 거둘 권리(수조권)였습니다.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-06","grade":"h1"},
{"id":"hist-h-k1-07","kind":"unit","title":"신분제와 사회 구조","text":"골품제부터 조선의 양천제·반상제까지 신분제가 사회를 어떻게 움직였는지, 그리고 가족 제도와 여성의 지위가 어떻게 달라졌는지 분석합니다. 신라 골품제의 특징과 한계를 설명할 수 있다. 고려와 조선의 신분 구조를 비교할 수 있다. 조선 후기 신분제가 흔들린 모습과 그 원인을 설명할 수 있다. 고려에서 조선 후기까지 가족 제도와 여성 지위의 변화를 설명할 수 …","keywords":["골품제","6두품","문벌 귀족","음서","향·부곡·소","양천제","반상제","서얼","공명첩","균분 상속"],"ref":{"tab":"concepts","idx":0},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-07","grade":"h1"},
{"id":"hist-h-k1-07#c0","kind":"concept","title":"신라의 골품제와 그 한계","text":"골품제는 혈통에 따라 사람을 나눈 신라의 신분 제도입니다. 왕족은 성골·진골, 그 아래는 6두품부터 1두품까지 나뉘었습니다(뒤에 3~1두품은 평민과 비슷해졌습니다). 골품은 정치와 생활 전체를 묶었습니다. 관직: 골품에 따라 오를 수 있는 관등의 상한이 정해져 있었습니다. 진골만 높은 ","keywords":["골품제","6두품"],"ref":{"tab":"concepts","idx":0},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-07","grade":"h1"},
{"id":"hist-h-k1-07#c1","kind":"concept","title":"고려의 신분 구조","text":"고려의 신분은 크게 귀족, 중류층, 양민, 천민으로 나뉩니다. 신분 · 누구 · 특징 귀족 · 왕족, 문벌 귀족(5품 이상 고위 관료 가문) · 음서(시험 없이 관직), 공음전(세습 토지) 혜택. 왕실과 혼인 중류층 · 서리, 남반, 향리, 하급 장교 · 행정 실무를 맡음. 직역을 세습","keywords":["문벌 귀족","음서","향·부곡·소"],"ref":{"tab":"concepts","idx":1},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-07","grade":"h1"},
{"id":"hist-h-k1-07#c2","kind":"concept","title":"조선의 양천제와 반상제","text":"조선의 신분 제도는 법과 현실이 조금 달랐습니다. 양천제(법): 법적으로는 사람을 양인과 천인 둘로 나누었습니다. 양인은 과거에 응시하고 관직에 나아갈 자격이 있었고, 조세·국역의 의무를 졌습니다. 천인은 노비가 대부분이었습니다. 반상제(현실): 그러나 실제로는 양반·중인·상민·천민의 ","keywords":["음서","양천제","반상제","서얼"],"ref":{"tab":"concepts","idx":2},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-07","grade":"h1"},
{"id":"hist-h-k1-07#c3","kind":"concept","title":"조선 후기 신분제의 동요","text":"양 난(왜란·호란) 뒤 경제가 바뀌면서 조선 후기 신분제는 크게 흔들렸습니다. 양반은 늘고, 상민·노비는 줄었습니다. 공명첩: 이름 칸을 비워 둔 관직 임명장입니다. 나라가 재정을 마련하려고 곡식이나 돈을 받고 팔았습니다. 족보 매입·위조: 부를 쌓은 농민과 상인이 족보를 사거나 고쳐 ","keywords":["서얼","공명첩"],"ref":{"tab":"concepts","idx":3},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-07","grade":"h1"},
{"id":"hist-h-k1-07#c4","kind":"concept","title":"고려~조선 전기의 가족과 여성의 지위","text":"고려 시대 가족 제도에서 여성의 지위는 조선 후기보다 비교적 높았습니다. 균분 상속: 재산을 아들과 딸에게 고르게 나누어 주었습니다. 호적: 아들딸 구별 없이 태어난 순서대로 적었습니다. 제사: 아들이 없으면 딸이 제사를 지내기도 했습니다. 혼인: 혼인 뒤 남자가 한동안 처가에서 사는 ","keywords":["음서","균분 상속"],"ref":{"tab":"concepts","idx":4},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-07","grade":"h1"},
{"id":"hist-h-k1-07#c5","kind":"concept","title":"조선 후기 부계 중심 가족 제도","text":"17세기 이후 성리학의 예법이 사회 깊숙이 퍼지면서 가족 제도가 아버지 쪽 혈통(부계) 중심으로 바뀌었습니다. 구분 · 고려~조선 전기 · 조선 후기 상속 · 자녀 균분 상속 · 맏아들(장자) 에게 많이 제사 · 자녀가 돌아가며, 딸도 · 맏아들이 맡음 혼인 · 남자가 처가에 머무는 일","keywords":["균분 상속"],"ref":{"tab":"concepts","idx":5},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-07","grade":"h1"},
{"id":"hist-h-k1-07#t0","kind":"term","title":"골품제","text":"혈통에 따라 성골·진골·6두품 등으로 나누어 관직과 생활을 제한한 신라의 신분 제도입니다.","keywords":["골품제"],"ref":{"tab":"terms","idx":0},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-07","grade":"h1"},
{"id":"hist-h-k1-07#t1","kind":"term","title":"6두품","text":"골품제에서 진골 아래 신분입니다. 학식이 뛰어났으나 6관등(아찬)까지만 오를 수 있었습니다.","keywords":["6두품"],"ref":{"tab":"terms","idx":1},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-07","grade":"h1"},
{"id":"hist-h-k1-07#t2","kind":"term","title":"문벌 귀족","text":"고려에서 대대로 고위 관직을 차지한 가문입니다. 음서와 공음전의 혜택을 누렸습니다.","keywords":["문벌 귀족"],"ref":{"tab":"terms","idx":2},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-07","grade":"h1"},
{"id":"hist-h-k1-07#t3","kind":"term","title":"음서","text":"공신이나 고위 관리의 자손을 과거 없이 관리로 뽑던 제도입니다.","keywords":["음서"],"ref":{"tab":"terms","idx":3},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-07","grade":"h1"},
{"id":"hist-h-k1-07#t4","kind":"term","title":"향·부곡·소","text":"고려의 특수 행정 구역입니다. 주민은 양민이었지만 세금 부담이 무겁고 거주 이전이 제한되었습니다.","keywords":["향·부곡·소"],"ref":{"tab":"terms","idx":4},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-07","grade":"h1"},
{"id":"hist-h-k1-07#t5","kind":"term","title":"양천제","text":"사람을 양인과 천인으로 나눈 조선의 법적 신분 제도입니다.","keywords":["양천제"],"ref":{"tab":"terms","idx":5},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-07","grade":"h1"},
{"id":"hist-h-k1-07#t6","kind":"term","title":"반상제","text":"양반·중인·상민·천민으로 나뉜, 조선에서 실제로 자리 잡은 신분 질서입니다.","keywords":["반상제"],"ref":{"tab":"terms","idx":6},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-07","grade":"h1"},
{"id":"hist-h-k1-07#t7","kind":"term","title":"서얼","text":"양반의 자손 가운데 어머니가 첩인 사람입니다. 문과 응시와 관직 진출에 제한을 받았습니다.","keywords":["서얼"],"ref":{"tab":"terms","idx":7},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-07","grade":"h1"},
{"id":"hist-h-k1-07#t8","kind":"term","title":"공명첩","text":"받는 사람의 이름 칸을 비워 둔 관직 임명장입니다. 조선 후기 나라가 재정을 마련하려고 팔았습니다.","keywords":["공명첩"],"ref":{"tab":"terms","idx":8},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-07","grade":"h1"},
{"id":"hist-h-k1-07#t9","kind":"term","title":"균분 상속","text":"재산을 자녀에게 아들딸 구별 없이 고르게 나누어 주는 상속 방식입니다. 고려~조선 전기에 일반적이었습니다.","keywords":["균분 상속"],"ref":{"tab":"terms","idx":9},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-07","grade":"h1"},
{"id":"hist-h-k1-07#f0","kind":"faq","title":"고려 백정이랑 조선 백정은 왜 뜻이 달라요?","text":"같은 이름이 시대에 따라 다른 사람을 가리키게 된 경우입니다. 고려의 백정은 특별한 직역 없이 농사짓는 일반 농민(양민)이었습니다. 조선 시대에는 도살업 등에 종사하던 천민을 백정이라 부르게 되었습니다. 그래서 문제에서 백정이 나오면 시대를 먼저 확인해야 합니다.","keywords":[],"ref":{"tab":"faq","idx":0},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-07","grade":"h1"},
{"id":"hist-h-k1-07#f1","kind":"faq","title":"양천제랑 반상제는 같은 거예요?","text":"아닙니다. 양천제는 법에 정한 구분(양인·천인 둘)이고, 반상제는 실제 사회에서 굳어진 구분(양반·중인·상민·천민 넷)입니다. 법으로는 상민도 과거를 볼 수 있는 양인이었지만, 현실에서는 양반과 상민의 차이가 컸습니다.","keywords":["양천제","반상제"],"ref":{"tab":"faq","idx":1},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-07","grade":"h1"},
{"id":"hist-h-k1-07#f2","kind":"faq","title":"옛날에는 원래 여자가 재산을 못 받았던 거 아니에요?","text":"그렇지 않습니다. 고려와 조선 전기에는 아들딸에게 재산을 고르게 나누는 균분 상속이 일반적이었고, 딸이 제사를 지내기도 했습니다. 맏아들 중심의 상속과 제사는 17세기 이후 성리학적 예법이 퍼지면서 자리 잡은 것입니다.","keywords":[],"ref":{"tab":"faq","idx":2},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-07","grade":"h1"},
{"id":"hist-h-k1-07#m0","kind":"mistake","title":"자주 하는 실수","text":"고려의 백정을 천민으로 아는 실수 — 고려의 백정은 일반 농민(양민)이고, 천민 백정은 조선 시대의 뜻입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-07","grade":"h1"},
{"id":"hist-h-k1-07#m1","kind":"mistake","title":"자주 하는 실수","text":"양천제와 반상제를 같은 것으로 보는 실수 — 양천제는 법적 구분, 반상제는 현실의 구분입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-07","grade":"h1"},
{"id":"hist-h-k1-07#m2","kind":"mistake","title":"자주 하는 실수","text":"맏아들 중심 가족 제도가 고려 때부터 있었다고 생각하는 실수 — 조선 후기(17세기 이후)에 자리 잡았습니다.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-07","grade":"h1"},
{"id":"hist-h-k1-08","kind":"unit","title":"사상과 문화의 교류","text":"불교와 유교를 중심으로 전근대 사상과 문화가 국제 교류 속에서 발전한 모습을 살피고, 스스로 주제를 정해 역사를 탐구하는 방법을 익힙니다. 불교와 유학(성리학)의 수용과 발전 과정을 대표 인물과 함께 설명할 수 있다. 국제 교류 속에서 발달한 문화유산(인쇄술·도자기·건축)의 특징을 설명할 수 있다. 조선 후기의 새로운 사상(실학·서학·동학)과 서민 문화의…","keywords":["불교 대중화","화엄 사상","성리학","풍수지리설","직지심체요절","상감 기법","실학","동학","판소리","1차 사료"],"ref":{"tab":"concepts","idx":0},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-08","grade":"h1"},
{"id":"hist-h-k1-08#c0","kind":"concept","title":"불교의 수용과 발전","text":"수용: 불교는 중국을 거쳐 삼국에 들어왔습니다. 왕실은 \"모든 백성이 하나의 가르침 아래 모인다\"는 불교로 왕권을 강화하고 사상을 통합하려 했습니다. 나라 · 시기 · 전래·공인 고구려 · 소수림왕(372년) · 전진에서 전래 백제 · 침류왕(384년) · 동진에서 전래 신라 · 법흥왕","keywords":["불교 대중화","화엄 사상"],"ref":{"tab":"concepts","idx":0},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-08","grade":"h1"},
{"id":"hist-h-k1-08#c1","kind":"concept","title":"유학과 성리학, 도교와 풍수지리설","text":"유학 교육과 관리 선발 고구려는 태학(372년)을 세웠고, 통일 신라는 국학(신문왕)을 세우고 유교 경전 이해 정도로 관리를 뽑는 독서삼품과(원성왕)를 실시했습니다. 고려 광종은 과거제(958년)를 시행해 학문과 능력으로 관리를 뽑기 시작했고, 성종은 국자감을 세웠습니다. 성리학: 고려","keywords":["성리학","풍수지리설"],"ref":{"tab":"concepts","idx":1},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-08","grade":"h1"},
{"id":"hist-h-k1-08#c2","kind":"concept","title":"국제 교류 속에서 발달한 문화유산","text":"우리 문화유산은 외국의 기술과 문화를 받아들이면서도 독창적으로 발전시킨 결과물입니다. 인쇄술 무구정광대다라니경: 불국사 3층 석탑(석가탑)에서 발견된 통일 신라의 불경으로, 현재 남아 있는 세계에서 가장 오래된 목판 인쇄물의 하나로 평가됩니다. 팔만대장경(재조대장경): 몽골의 침입을 불","keywords":["직지심체요절","상감 기법"],"ref":{"tab":"concepts","idx":2},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-08","grade":"h1"},
{"id":"hist-h-k1-08#c3","kind":"concept","title":"조선 후기의 새로운 사상: 실학, 서학, 동학","text":"양 난 이후 사회가 바뀌자, 성리학만으로는 현실 문제를 풀기 어렵다는 생각이 퍼졌습니다. 실학: 실제 생활에 도움이 되는 학문을 추구했습니다. 농업 중심 개혁론: 토지 제도를 고쳐 자영농을 늘리자고 했습니다. 유형원, 이익, 정약용 등. 상공업 중심 개혁론(북학파): 청의 문물을 배우고","keywords":["성리학","실학","동학"],"ref":{"tab":"concepts","idx":3},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-08","grade":"h1"},
{"id":"hist-h-k1-08#c4","kind":"concept","title":"조선 후기 서민 문화와 예술의 새 경향","text":"조선 후기에는 상공업 발달로 부를 쌓은 서민이 늘고 서당 교육이 퍼지면서, 서민이 즐기고 만드는 문화가 크게 성장했습니다. 한글 소설: 『홍길동전』, 『춘향전』 등. 신분 차별과 탐관오리를 비판하고 서민의 바람을 담았습니다. 판소리: 소리꾼이 북 장단에 맞춰 긴 이야기를 노래와 말로 들","keywords":["판소리"],"ref":{"tab":"concepts","idx":4},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-08","grade":"h1"},
{"id":"hist-h-k1-08#c5","kind":"concept","title":"역사 쟁점을 탐구하는 방법","text":"역사 공부는 외우는 데서 그치지 않고 스스로 묻고, 자료로 확인하고, 근거를 들어 말하는 것까지 이어집니다. 질문 만들기: \"무엇이 일어났나?\"에서 한 걸음 나아가 \"왜 그랬을까?\", \"그 결과 누구의 삶이 어떻게 바뀌었나?\", \"다르게 볼 수는 없을까?\"를 묻습니다. 예: \"대동법이 ","keywords":["1차 사료"],"ref":{"tab":"concepts","idx":5},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-08","grade":"h1"},
{"id":"hist-h-k1-08#t0","kind":"term","title":"불교 대중화","text":"귀족뿐 아니라 일반 백성도 불교를 믿게 된 것입니다. 원효의 아미타 신앙이 대표적입니다.","keywords":["불교 대중화"],"ref":{"tab":"terms","idx":0},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-08","grade":"h1"},
{"id":"hist-h-k1-08#t1","kind":"term","title":"화엄 사상","text":"모든 존재가 서로 연결되어 조화를 이룬다는 불교 사상입니다. 통일 신라의 의상이 펼쳤습니다.","keywords":["화엄 사상"],"ref":{"tab":"terms","idx":1},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-08","grade":"h1"},
{"id":"hist-h-k1-08#t2","kind":"term","title":"성리학","text":"우주의 원리와 사람의 본성을 탐구한 새로운 유학입니다. 고려 말 들어와 조선의 지배 이념이 되었습니다.","keywords":["성리학"],"ref":{"tab":"terms","idx":2},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-08","grade":"h1"},
{"id":"hist-h-k1-08#t3","kind":"term","title":"풍수지리설","text":"땅의 기운이 사람과 나라의 운명에 영향을 준다는 생각입니다. 신라 말 도선이 널리 알렸습니다.","keywords":["풍수지리설"],"ref":{"tab":"terms","idx":3},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-08","grade":"h1"},
{"id":"hist-h-k1-08#t4","kind":"term","title":"직지심체요절","text":"1377년 청주 흥덕사에서 금속 활자로 찍은 책으로, 현존하는 세계에서 가장 오래된 금속 활자본입니다.","keywords":["직지심체요절"],"ref":{"tab":"terms","idx":4},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-08","grade":"h1"},
{"id":"hist-h-k1-08#t5","kind":"term","title":"상감 기법","text":"그릇 표면을 파내고 다른 색 흙을 채워 무늬를 내는 기법입니다. 고려청자에서 독창적으로 발전했습니다.","keywords":["상감 기법"],"ref":{"tab":"terms","idx":5},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-08","grade":"h1"},
{"id":"hist-h-k1-08#t6","kind":"term","title":"실학","text":"조선 후기 실제 생활에 도움이 되는 학문을 추구하며 사회 개혁을 주장한 학문입니다.","keywords":["실학"],"ref":{"tab":"terms","idx":6},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-08","grade":"h1"},
{"id":"hist-h-k1-08#t7","kind":"term","title":"동학","text":"1860년 최제우가 창시한 사상·종교입니다. 시천주를 내세워 인간 평등을 강조했습니다.","keywords":["동학"],"ref":{"tab":"terms","idx":7},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-08","grade":"h1"},
{"id":"hist-h-k1-08#t8","kind":"term","title":"판소리","text":"소리꾼이 북 장단에 맞춰 긴 이야기를 노래와 말로 들려주는 조선 후기의 공연 예술입니다.","keywords":["판소리"],"ref":{"tab":"terms","idx":8},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-08","grade":"h1"},
{"id":"hist-h-k1-08#t9","kind":"term","title":"1차 사료","text":"그 시대 사람이 직접 남긴 기록이나 유물입니다. 예: 실록, 호적, 일기, 비문","keywords":["1차 사료"],"ref":{"tab":"terms","idx":9},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-08","grade":"h1"},
{"id":"hist-h-k1-08#f0","kind":"faq","title":"원효랑 의상은 뭐가 달라요?","text":"원효는 신라에 남아 아미타 신앙으로 불교를 백성에게 널리 퍼뜨렸고(불교 대중화), 여러 종파를 아우르는 화쟁 사상을 내세웠습니다. 의상은 당에서 유학한 뒤 화엄 사상을 펼치고 부석사를 세웠습니다. \"대중화의 원효, 화엄의 의상\"으로 기억하면 좋습니다.","keywords":[],"ref":{"tab":"faq","idx":0},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-08","grade":"h1"},
{"id":"hist-h-k1-08#f1","kind":"faq","title":"실학은 성리학을 버린 학문이에요?","text":"그렇지 않습니다. 실학자들도 대부분 성리학을 공부한 학자였습니다. 다만 성리학이 현실 문제를 푸는 데 부족하다고 보고, 토지·상공업·기술처럼 실제 생활에 도움이 되는 개혁을 연구했습니다.","keywords":["성리학","실학"],"ref":{"tab":"faq","idx":1},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-08","grade":"h1"},
{"id":"hist-h-k1-08#f2","kind":"faq","title":"인터넷에서 찾은 역사 이야기는 믿어도 돼요?","text":"출처를 먼저 확인해야 합니다. 누가, 언제, 어떤 자료를 근거로 썼는지 밝혀져 있는지 살피고, 박물관·연구 기관·교과서 같은 믿을 만한 자료와 맞춰 보십시오. 출처가 없거나 근거가 확인되지 않는 글은 참고만 하고 결론의 근거로 쓰지 않는 것이 좋습니다.","keywords":[],"ref":{"tab":"faq","idx":2},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-08","grade":"h1"},
{"id":"hist-h-k1-08#m0","kind":"mistake","title":"자주 하는 실수","text":"의천과 지눌을 바꾸어 기억하는 실수 — 의천은 교종 중심(해동 천태종), 지눌은 선종 중심(수선사 결사, 정혜쌍수)입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-08","grade":"h1"},
{"id":"hist-h-k1-08#m1","kind":"mistake","title":"자주 하는 실수","text":"팔만대장경을 금속 활자로 찍은 책으로 아는 실수 — 팔만대장경은 나무에 새긴 목판이고, 현존 최고(最古) 금속 활자본은 직지심체요절입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-08","grade":"h1"},
{"id":"hist-h-k1-08#m2","kind":"mistake","title":"자주 하는 실수","text":"1차 사료는 무조건 옳다고 믿는 실수 — 1차 사료도 쓴 사람의 입장이 담겨 있으므로 다른 자료와 맞춰 보아야 합니다.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-08","grade":"h1"},
{"id":"hist-h-k1-09","kind":"unit","title":"국제 질서의 변동과 개항","text":"서양 세력의 침략에 맞선 통상 수교 거부부터 강화도 조약까지, 국제 질서가 바뀌는 흐름 속에서 조선이 개항한 과정을 분석합니다. 조공·책봉 질서와 만국 공법에 바탕을 둔 근대 조약 체제의 차이를 설명할 수 있다. 아편 전쟁과 일본의 개항이 동아시아 질서에 준 변화를 설명할 수 있다. 흥선 대원군의 통상 수교 거부 정책과 병인양요·신미양요의 전개를 정리할 …","keywords":["조공·책봉","만국 공법","통상 수교 거부 정책","병인양요","신미양요","척화비","강화도 조약","영사 재판권","최혜국 대우","거중 조정"],"ref":{"tab":"concepts","idx":0},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-09","grade":"h1"},
{"id":"hist-h-k1-09#c0","kind":"concept","title":"조공·책봉 질서와 근대 조약 체제","text":"19세기 중반까지 동아시아의 국제 관계는 중국을 중심으로 한 조공·책봉 질서였습니다. 주변국 군주가 중국 황제에게 사신을 보내 예물을 바치고(조공), 황제는 그 군주의 지위를 인정해 주었습니다(책봉). 조선은 명·청에 사대하고 일본·여진과는 대등하게 사귀는 사대교린 정책을 폈습니다. 이","keywords":["조공·책봉","만국 공법"],"ref":{"tab":"concepts","idx":0},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-09","grade":"h1"},
{"id":"hist-h-k1-09#c1","kind":"concept","title":"아편 전쟁과 일본의 개항","text":"19세기에 산업 혁명을 이룬 서양 열강은 원료와 시장을 찾아 동아시아로 몰려왔습니다. 청: 영국은 청과의 무역 적자를 메우려고 인도산 아편을 몰래 팔았습니다. 청이 아편을 단속하자 영국이 전쟁을 일으켰습니다(아편 전쟁, 1840~1842년). 청은 패하여 난징 조약(1842년)을 맺고 ","keywords":[],"ref":{"tab":"concepts","idx":1},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-09","grade":"h1"},
{"id":"hist-h-k1-09#c2","kind":"concept","title":"흥선 대원군의 통상 수교 거부 정책","text":"1863년 고종이 어린 나이에 왕위에 오르자 아버지 흥선 대원군이 권력을 잡았습니다. 대원군은 서양과 통상·수교하지 않는 통상 수교 거부 정책을 펼쳤습니다. 병인박해(1866년): 천주교를 탄압하여 프랑스 선교사와 많은 신자가 처형되었습니다. 제너럴셔먼호 사건(1866년): 미국 상선이","keywords":["통상 수교 거부 정책","병인양요","신미양요"],"ref":{"tab":"concepts","idx":2},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-09","grade":"h1"},
{"id":"hist-h-k1-09#c3","kind":"concept","title":"강화도 조약과 불평등 조항","text":"1873년 고종이 직접 나라를 다스리기 시작하고 대원군이 물러나자, 박규수 등 통상을 주장하는 세력의 목소리가 커졌습니다. 이때 일본은 군함 운요호를 강화도 앞바다에 보내 조선 수비대와 충돌을 일으켰습니다(운요호 사건, 1875년). 일본은 이를 구실로 개항을 강요했고, 조선은 1876","keywords":["강화도 조약","영사 재판권"],"ref":{"tab":"concepts","idx":3},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-09","grade":"h1"},
{"id":"hist-h-k1-09#c4","kind":"concept","title":"서양 여러 나라와의 조약과 개항의 의미","text":"강화도 조약 뒤 청은 일본과 러시아를 견제하려고 조선에 미국과 수교하라고 권했습니다. 2차 수신사 김홍집이 일본에서 들여온 『조선책략』도 \"러시아를 막으려면 청과 친하고, 일본과 맺고, 미국과 이어져야 한다\"고 주장했습니다. 이런 배경에서 청의 알선으로 1882년 조미 수호 통상 조약이","keywords":["강화도 조약","영사 재판권","최혜국 대우","거중 조정"],"ref":{"tab":"concepts","idx":4},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-09","grade":"h1"},
{"id":"hist-h-k1-09#t0","kind":"term","title":"조공·책봉","text":"주변국이 중국 황제에게 예물을 바치고(조공), 황제가 그 군주의 지위를 인정하는(책봉) 동아시아의 전통적 국제 관계입니다.","keywords":["조공·책봉"],"ref":{"tab":"terms","idx":0},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-09","grade":"h1"},
{"id":"hist-h-k1-09#t1","kind":"term","title":"만국 공법","text":"서양의 국제법을 동아시아에서 부른 이름입니다. 주권 국가의 평등과 조약에 따른 외교를 내세웠습니다.","keywords":["만국 공법"],"ref":{"tab":"terms","idx":1},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-09","grade":"h1"},
{"id":"hist-h-k1-09#t2","kind":"term","title":"통상 수교 거부 정책","text":"흥선 대원군이 서양 나라와 무역(통상)하거나 외교 관계(수교)를 맺지 않으려 한 정책입니다.","keywords":["통상 수교 거부 정책"],"ref":{"tab":"terms","idx":2},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-09","grade":"h1"},
{"id":"hist-h-k1-09#t3","kind":"term","title":"병인양요","text":"1866년 병인박해를 구실로 프랑스군이 강화도를 침략한 사건입니다. 외규장각 도서를 약탈당했습니다.","keywords":["병인양요"],"ref":{"tab":"terms","idx":3},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-09","grade":"h1"},
{"id":"hist-h-k1-09#t4","kind":"term","title":"신미양요","text":"1871년 제너럴셔먼호 사건을 구실로 미국 함대가 강화도를 침략한 사건입니다. 어재연이 광성보에서 맞서 싸웠습니다.","keywords":["신미양요"],"ref":{"tab":"terms","idx":4},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-09","grade":"h1"},
{"id":"hist-h-k1-09#t5","kind":"term","title":"척화비","text":"신미양요 뒤 흥선 대원군이 서양과 화친하지 않겠다는 뜻을 새겨 서울과 전국에 세운 비석입니다.","keywords":["척화비"],"ref":{"tab":"terms","idx":5},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-09","grade":"h1"},
{"id":"hist-h-k1-09#t6","kind":"term","title":"강화도 조약","text":"1876년 조선이 일본과 맺은 최초의 근대적 조약(조일 수호 조규)입니다. 해안 측량권·영사 재판권을 담은 불평등 조약입니다.","keywords":["강화도 조약"],"ref":{"tab":"terms","idx":6},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-09","grade":"h1"},
{"id":"hist-h-k1-09#t7","kind":"term","title":"영사 재판권","text":"외국인이 죄를 지어도 그 나라 영사가 자기 나라 법으로 재판하는 권리입니다. 치외 법권의 하나로, 조약을 맺은 상대국의 사법권을 침해합니다.","keywords":["영사 재판권"],"ref":{"tab":"terms","idx":7},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-09","grade":"h1"},
{"id":"hist-h-k1-09#t8","kind":"term","title":"최혜국 대우","text":"한 나라에 준 가장 유리한 조건을 조약 상대국에도 자동으로 주는 것입니다. 조미 수호 통상 조약에 처음 들어갔습니다.","keywords":["최혜국 대우"],"ref":{"tab":"terms","idx":8},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-09","grade":"h1"},
{"id":"hist-h-k1-09#t9","kind":"term","title":"거중 조정","text":"다른 나라가 조약 당사국 한쪽을 부당하게 대하면 다른 한쪽이 나서서 돕기로 한 약속입니다. 조미 수호 통상 조약에 들어 있습니다.","keywords":["거중 조정"],"ref":{"tab":"terms","idx":9},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-09","grade":"h1"},
{"id":"hist-h-k1-09#f0","kind":"faq","title":"흥선 대원군의 통상 수교 거부 정책은 잘한 거예요, 잘못한 거예요?","text":"두 면을 함께 보아야 합니다. 프랑스와 미국의 침략을 물리쳐 외세의 침략을 일시적으로 막아 냈다는 의미가 있습니다. 그러나 서양 문물을 받아들이고 세계정세에 대비할 시기를 늦추었다는 한계도 있습니다. 시험에서도 \"의의\"와 \"한계\"를 나누어 정리하는 것이 좋습니다.","keywords":["통상 수교 거부 정책"],"ref":{"tab":"faq","idx":0},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-09","grade":"h1"},
{"id":"hist-h-k1-09#f1","kind":"faq","title":"\"조선은 자주국\"이라는 조항은 조선에 좋은 것 아닌가요?","text":"겉으로는 조선을 독립된 나라로 인정하는 것처럼 보입니다. 하지만 일본의 진짜 목적은 조선과 청의 전통적 관계를 끊어, 청이 간섭하지 못하게 하고 일본이 조선에 쉽게 들어오는 것이었습니다. 조항의 글자보다 그 조항을 넣은 나라의 의도를 함께 읽어야 합니다.","keywords":[],"ref":{"tab":"faq","idx":1},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-09","grade":"h1"},
{"id":"hist-h-k1-09#f2","kind":"faq","title":"영사 재판권이랑 치외 법권은 같은 말이에요?","text":"치외 법권은 외국인이 머무는 나라의 법을 적용받지 않는 권리를 넓게 이르는 말이고, 영사 재판권은 그 가운데 하나로 자기 나라 영사에게 재판받는 권리입니다. 강화도 조약의 영사 재판권 조항을 \"치외 법권을 인정했다\"고 설명하기도 합니다.","keywords":["영사 재판권"],"ref":{"tab":"faq","idx":2},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-09","grade":"h1"},
{"id":"hist-h-k1-09#f3","kind":"faq","title":"양요의 \"양\"은 무슨 뜻이에요?","text":"\"양(洋)\"은 서양을 뜻하고 \"요(擾)\"는 어지러운 소란을 뜻합니다. 곧 양요는 \"서양 세력이 일으킨 소란\"이라는 뜻입니다. 병인년(1866년)에 일어난 것이 병인양요, 신미년(1871년)에 일어난 것이 신미양요입니다.","keywords":[],"ref":{"tab":"faq","idx":3},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-09","grade":"h1"},
{"id":"hist-h-k1-09#m0","kind":"mistake","title":"자주 하는 실수","text":"병인양요와 신미양요의 나라를 바꾸어 외우는 실수 — 병인양요(1866년)는 프랑스, 신미양요(1871년)는 미국입니다. 각각의 구실(병인박해, 제너럴셔먼호 사건)과 짝지어 외웁니다.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-09","grade":"h1"},
{"id":"hist-h-k1-09#m1","kind":"mistake","title":"자주 하는 실수","text":"최혜국 대우가 강화도 조약에 있었다고 생각하는 실수 — 최혜국 대우는 조미 수호 통상 조약(1882년)에 처음 들어갔습니다. 강화도 조약의 핵심 불평등 조항은 해안 측량권과 영사 재판권입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-09","grade":"h1"},
{"id":"hist-h-k1-09#m2","kind":"mistake","title":"자주 하는 실수","text":"\"조선은 자주국\" 조항을 조선의 주권을 존중한 조항으로 이해하는 실수 — 청의 종주권을 부정하여 일본이 조선에 진출하려는 의도였습니다.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-09","grade":"h1"},
{"id":"hist-h-k1-10","kind":"unit","title":"근대 국가 수립을 위한 노력","text":"개화파와 농민, 독립 협회와 대한 제국 등 여러 세력이 근대 국가를 세우려고 펼친 다양한 노력을 이해합니다. 개화 정책의 추진 과정과 임오군란·갑신정변의 원인과 결과를 설명할 수 있다. 동학 농민 운동의 전개 과정과 반봉건·반외세의 성격을 설명할 수 있다. 갑오개혁·을미개혁과 광무개혁의 주요 내용을 비교할 수 있다. 독립 협회의 활동과 근대 국가 수립을 …","keywords":["통리기무아문","위정척사 운동","임오군란","갑신정변","거문도 사건","집강소","군국기무처","홍범 14조","헌의 6조","구본신참"],"ref":{"tab":"concepts","idx":0},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-10","grade":"h1"},
{"id":"hist-h-k1-10#c0","kind":"concept","title":"개화 정책의 추진과 임오군란","text":"개항 뒤 조선 정부는 새로운 문물을 받아들이는 개화 정책을 추진했습니다. 기구: 개화 정책을 총괄하는 통리기무아문을 설치했습니다(1880년). 군사: 신식 군대인 별기군을 만들어 일본인 교관에게 훈련받게 했습니다(1881년). 사절단: 일본에 수신사와 조사 시찰단을, 청에 영선사(무기 ","keywords":["통리기무아문","위정척사 운동","임오군란"],"ref":{"tab":"concepts","idx":0},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-10","grade":"h1"},
{"id":"hist-h-k1-10#c1","kind":"concept","title":"갑신정변과 열강의 대립","text":"임오군란 뒤 개화파는 청과의 관계와 개혁 방법을 두고 둘로 나뉘었습니다. 구분 · 온건 개화파 · 급진 개화파 인물 · 김홍집, 김윤식, 어윤중 · 김옥균, 박영효, 홍영식, 서광범 청과의 관계 · 청과 관계를 유지 · 청의 간섭에서 벗어나려 함 개혁 방법 · 우리 전통(유교)을 지키며","keywords":["임오군란","갑신정변"],"ref":{"tab":"concepts","idx":1},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-10","grade":"h1"},
{"id":"hist-h-k1-10#c2","kind":"concept","title":"동학 농민 운동의 전개와 의의","text":"개항 뒤 지배층의 수탈과 일본으로의 곡물 유출로 농민의 삶은 더 어려워졌습니다. 이때 \"사람이 곧 하늘(인내천)\"이라고 가르친 동학이 농민 사이에 퍼졌습니다. 고부 농민 봉기(1894년 1월): 고부 군수 조병갑의 횡포에 맞서 전봉준이 농민을 이끌고 일어났습니다. 1차 봉기: 농민군은 ","keywords":["집강소"],"ref":{"tab":"concepts","idx":2},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-10","grade":"h1"},
{"id":"hist-h-k1-10#c3","kind":"concept","title":"갑오개혁과 을미개혁","text":"1894년 일본군이 경복궁을 점령한 가운데, 정부는 군국기무처를 중심으로 개혁을 추진했습니다(갑오개혁). 개혁은 일본의 간섭 속에 이루어졌지만, 개화파의 개혁 구상과 농민의 요구가 일부 반영되었습니다. 개혁 · 주요 내용 1차 갑오개혁 · 과거제 폐지, 공사 노비법 혁파(신분제 폐지),","keywords":["군국기무처","홍범 14조"],"ref":{"tab":"concepts","idx":3},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-10","grade":"h1"},
{"id":"hist-h-k1-10#c4","kind":"concept","title":"독립 협회의 활동","text":"아관 파천 뒤 러시아 등 열강의 간섭과 이권 침탈이 심해졌습니다. 이에 갑신정변 뒤 미국에 망명했다 돌아온 서재필이 독립신문을 펴내고(1896년), 개화 지식인들과 함께 독립 협회를 만들었습니다. 독립 협회는 청의 사신을 맞던 영은문 자리에 독립문을 세웠습니다. 목표 · 활동 자주 국권","keywords":["갑신정변","헌의 6조"],"ref":{"tab":"concepts","idx":4},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-10","grade":"h1"},
{"id":"hist-h-k1-10#c5","kind":"concept","title":"대한 제국과 광무개혁","text":"1897년 고종은 러시아 공사관에서 경운궁(지금의 덕수궁)으로 돌아왔습니다. 그리고 연호를 광무로 정하고 환구단에서 황제 자리에 올라 나라 이름을 대한 제국이라 했습니다. 자주독립 국가임을 안팎에 알린 것입니다. 1899년에는 대한국 국제를 반포해 황제가 군대·입법·행정·외교 등에 대해","keywords":["구본신참"],"ref":{"tab":"concepts","idx":5},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-10","grade":"h1"},
{"id":"hist-h-k1-10#t0","kind":"term","title":"통리기무아문","text":"1880년 개화 정책을 총괄하려고 설치한 기구입니다.","keywords":["통리기무아문"],"ref":{"tab":"terms","idx":0},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-10","grade":"h1"},
{"id":"hist-h-k1-10#t1","kind":"term","title":"위정척사 운동","text":"성리학의 질서를 지키고(위정) 서양과 일본 등 외세를 물리치자는(척사) 유생들의 운동입니다.","keywords":["위정척사 운동"],"ref":{"tab":"terms","idx":1},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-10","grade":"h1"},
{"id":"hist-h-k1-10#t2","kind":"term","title":"임오군란","text":"1882년 차별받던 구식 군인들이 일으킨 봉기입니다. 청군이 진압하면서 청의 내정 간섭이 심해졌습니다.","keywords":["임오군란"],"ref":{"tab":"terms","idx":2},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-10","grade":"h1"},
{"id":"hist-h-k1-10#t3","kind":"term","title":"갑신정변","text":"1884년 김옥균 등 급진 개화파가 우정총국 개국 축하연을 틈타 일으킨 정변입니다. 3일 만에 실패했습니다.","keywords":["갑신정변"],"ref":{"tab":"terms","idx":3},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-10","grade":"h1"},
{"id":"hist-h-k1-10#t4","kind":"term","title":"거문도 사건","text":"1885년 영국이 러시아를 견제한다며 거문도를 불법으로 점령한 사건입니다(1887년 철수).","keywords":["거문도 사건"],"ref":{"tab":"terms","idx":4},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-10","grade":"h1"},
{"id":"hist-h-k1-10#t5","kind":"term","title":"집강소","text":"전주 화약 뒤 동학 농민군이 전라도 각지에 설치하여 폐정 개혁을 추진한 기구입니다.","keywords":["집강소"],"ref":{"tab":"terms","idx":5},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-10","grade":"h1"},
{"id":"hist-h-k1-10#t6","kind":"term","title":"군국기무처","text":"1차 갑오개혁(1894년)을 이끈 개혁 추진 기구입니다.","keywords":["군국기무처"],"ref":{"tab":"terms","idx":6},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-10","grade":"h1"},
{"id":"hist-h-k1-10#t7","kind":"term","title":"홍범 14조","text":"2차 갑오개혁 때 고종이 반포한 개혁의 기본 방향입니다. 청에 의존하지 않는 자주독립 등을 담았습니다.","keywords":["홍범 14조"],"ref":{"tab":"terms","idx":7},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-10","grade":"h1"},
{"id":"hist-h-k1-10#t8","kind":"term","title":"헌의 6조","text":"1898년 독립 협회가 관민 공동회에서 결의하여 고종에게 올린 개혁안입니다.","keywords":["헌의 6조"],"ref":{"tab":"terms","idx":8},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-10","grade":"h1"},
{"id":"hist-h-k1-10#t9","kind":"term","title":"구본신참","text":"\"옛것을 근본으로 하고 새것을 참고한다\"는 뜻으로, 대한 제국 광무개혁의 원칙입니다.","keywords":["구본신참"],"ref":{"tab":"terms","idx":9},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-10","grade":"h1"},
{"id":"hist-h-k1-10#f0","kind":"faq","title":"온건 개화파와 급진 개화파는 뭐가 달라요?","text":"가장 큰 차이는 청과의 관계와 개혁의 범위입니다. 온건 개화파(김홍집 등)는 청과 관계를 유지하며 유교 질서는 지키고 서양 기술만 받아들이자고 했습니다(동도서기). 급진 개화파(김옥균 등)는 청의 간섭에서 벗어나 서양의 제도와 사상까지 받아들여 빨리 바꾸자고 했습니다.","keywords":[],"ref":{"tab":"faq","idx":0},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-10","grade":"h1"},
{"id":"hist-h-k1-10#f1","kind":"faq","title":"갑오개혁은 일본이 시킨 개혁인데 왜 의미가 있어요?","text":"갑오개혁은 일본의 간섭 속에 이루어졌다는 한계가 분명합니다. 그러나 개혁을 맡은 사람들은 조선의 개화파 관리들이었고, 신분제 폐지·과거제 폐지처럼 오래 요구되어 온 내용과 동학 농민군의 요구가 일부 반영되었습니다. 그래서 의의와 한계를 함께 평가합니다.","keywords":[],"ref":{"tab":"faq","idx":1},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-10","grade":"h1"},
{"id":"hist-h-k1-10#f2","kind":"faq","title":"동학 농민 운동의 \"반봉건\"과 \"반외세\"가 뭐예요?","text":"반봉건은 신분 차별, 탐관오리의 수탈 같은 낡은 사회 제도에 반대한다는 뜻입니다. 반외세는 외국 세력의 침략에 반대한다는 뜻입니다. 1차 봉기에서는 반봉건, 2차 봉기에서는 반외세의 성격이 특히 두드러집니다.","keywords":[],"ref":{"tab":"faq","idx":2},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-10","grade":"h1"},
{"id":"hist-h-k1-10#f3","kind":"faq","title":"홍범 14조, 14개조 정강, 헌의 6조가 너무 헷갈려요.","text":"누가 만들었는지로 나누면 쉽습니다. 14개조 정강은 갑신정변(1884년)의 급진 개화파, 홍범 14조는 2차 갑오개혁(1895년)의 고종, 헌의 6조는 관민 공동회(1898년)의 독립 협회입니다. 숫자가 비슷한 14개조 정강과 홍범 14조는 \"정변\"과 \"개혁\"으로 구별합니다.","keywords":["홍범 14조","헌의 6조"],"ref":{"tab":"faq","idx":3},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-10","grade":"h1"},
{"id":"hist-h-k1-10#m0","kind":"mistake","title":"자주 하는 실수","text":"임오군란의 결과와 갑신정변의 결과를 섞는 실수 — 임오군란 뒤에는 제물포 조약·조청 상민 수륙 무역 장정, 갑신정변 뒤에는 한성 조약·톈진 조약입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-10","grade":"h1"},
{"id":"hist-h-k1-10#m1","kind":"mistake","title":"자주 하는 실수","text":"단발령을 갑오개혁의 내용으로 아는 실수 — 단발령과 태양력 사용은 을미사변 뒤의 을미개혁입니다. 신분제 폐지와 과거제 폐지가 1차 갑오개혁입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-10","grade":"h1"},
{"id":"hist-h-k1-10#m2","kind":"mistake","title":"자주 하는 실수","text":"독립 협회와 대한 제국이 같은 주장을 했다고 생각하는 실수 — 둘 다 자주독립을 내세웠지만, 독립 협회는 민권과 의회를, 대한 제국은 황제권 강화를 강조했습니다.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-10","grade":"h1"},
{"id":"hist-h-k1-11","kind":"unit","title":"개항 이후 경제·사회·문화","text":"개항 이후 열강의 경제 침탈에 맞선 경제 주권 수호 운동과, 서구 문물이 들어오며 달라진 생활과 문화를 탐구합니다. 개항 이후 무역의 변화와 열강의 이권 침탈 과정을 설명할 수 있다. 방곡령, 상권 수호 운동, 국채 보상 운동 등 경제 주권 수호 운동을 설명할 수 있다. 평등 의식의 확산과 근대 문물·교육·언론의 도입이 생활에 준 변화를 평가할 수 있다.","keywords":["거류지 무역","중계 무역","이권","방곡령","국채 보상 운동","여권통문","원산 학사","육영 공원","한성순보","독립신문"],"ref":{"tab":"concepts","idx":0},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-11","grade":"h1"},
{"id":"hist-h-k1-11#c0","kind":"concept","title":"개항 이후 무역의 변화","text":"개항 초기 일본 상인은 개항장 주변에서만 장사할 수 있었습니다(거류지 무역). 그래서 조선 상인인 객주·여각·보부상이 외국 상인과 내륙 사이를 이어 주며 이익을 얻었습니다. 이 무렵 일본 상인은 영국산 면제품을 들여와 팔고, 조선의 쌀·콩 같은 곡물과 금을 사 갔습니다(중계 무역). 임","keywords":["거류지 무역","중계 무역"],"ref":{"tab":"concepts","idx":0},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-11","grade":"h1"},
{"id":"hist-h-k1-11#c1","kind":"concept","title":"열강의 이권 침탈","text":"1896년 아관 파천 뒤 열강은 최혜국 대우를 내세워 조선의 이권을 앞다투어 차지했습니다. 나라 · 차지한 이권(예) 러시아 · 압록강·두만강·울릉도의 삼림 채벌권, 광산 채굴권 미국 · 운산 금광 채굴권, 서울의 전기·전차 사업, 경인선 부설권(뒤에 일본에 넘김) 일본 · 경인선 부설","keywords":["이권"],"ref":{"tab":"concepts","idx":1},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-11","grade":"h1"},
{"id":"hist-h-k1-11#c2","kind":"concept","title":"경제 주권 수호 운동","text":"경제 침탈이 심해지자 정부와 민간은 경제 주권을 지키려고 여러 운동을 벌였습니다. 방곡령(1889년~): 곡물이 일본으로 지나치게 빠져나가자 함경도·황해도의 지방관이 곡물 수출을 막았습니다. 그러나 일본은 \"1개월 전에 미리 알린다\"는 조일 통상 장정의 규정을 어겼다며 항의했고, 조선은","keywords":["이권","방곡령","국채 보상 운동"],"ref":{"tab":"concepts","idx":2},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-11","grade":"h1"},
{"id":"hist-h-k1-11#c3","kind":"concept","title":"평등 의식의 확산과 사회 개혁","text":"개항 뒤 신분에 따른 차별을 없애려는 생각이 여러 갈래로 퍼졌습니다. 종교: 동학은 \"사람이 곧 하늘(인내천)\"이라 가르쳤고, 천주교와 개신교도 사람은 모두 평등하다고 가르쳤습니다. 갑신정변(1884년): 14개조 정강에서 문벌 폐지와 인민 평등권을 내세웠습니다. 동학 농민 운동(189","keywords":["여권통문"],"ref":{"tab":"concepts","idx":3},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-11","grade":"h1"},
{"id":"hist-h-k1-11#c4","kind":"concept","title":"근대 문물의 도입","text":"개항 뒤 서양의 새로운 기술과 시설이 들어와 생활이 달라졌습니다. 분야 · 내용 통신 · 우정총국 설립(1884년, 갑신정변으로 중단 뒤 우체사로 다시 시작), 전신 가설(1885년, 서울~인천~의주) 전기 · 경복궁에 전등을 처음 밝힘(1887년), 한성 전기 회사 설립(1898년) ","keywords":[],"ref":{"tab":"concepts","idx":4},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-11","grade":"h1"},
{"id":"hist-h-k1-11#c5","kind":"concept","title":"근대 교육과 언론의 발달","text":"근대 교육 원산 학사(1883년): 원산 주민들이 힘을 모아 세운 최초의 근대 사립 학교입니다. 동문학(1883년): 정부가 세운 영어 통역관 양성 학교입니다. 육영 공원(1886년): 정부가 세운 근대식 관립 학교로, 미국인 교사가 양반 자제에게 영어와 신학문을 가르쳤습니다. 개신교 ","keywords":["원산 학사","육영 공원","한성순보","독립신문"],"ref":{"tab":"concepts","idx":5},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-11","grade":"h1"},
{"id":"hist-h-k1-11#t0","kind":"term","title":"거류지 무역","text":"개항 초기 외국 상인이 개항장 주변의 정해진 구역에서만 장사하던 무역 방식입니다.","keywords":["거류지 무역"],"ref":{"tab":"terms","idx":0},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-11","grade":"h1"},
{"id":"hist-h-k1-11#t1","kind":"term","title":"중계 무역","text":"다른 나라의 물건을 사들여 또 다른 나라에 되파는 무역입니다. 개항 초 일본 상인은 영국산 면제품을 조선에 팔았습니다.","keywords":["중계 무역"],"ref":{"tab":"terms","idx":1},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-11","grade":"h1"},
{"id":"hist-h-k1-11#t2","kind":"term","title":"이권","text":"광산·삼림·철도처럼 이익을 얻을 수 있는 권리입니다. 아관 파천 뒤 열강이 많은 이권을 차지했습니다.","keywords":["이권"],"ref":{"tab":"terms","idx":2},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-11","grade":"h1"},
{"id":"hist-h-k1-11#t3","kind":"term","title":"방곡령","text":"곡물이 지나치게 빠져나가는 것을 막으려고 지방관이 곡물 수출을 금지한 명령입니다(1889년 함경도 등).","keywords":["방곡령"],"ref":{"tab":"terms","idx":3},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-11","grade":"h1"},
{"id":"hist-h-k1-11#t4","kind":"term","title":"국채 보상 운동","text":"1907년 일본에 진 나랏빚을 국민의 모금으로 갚자며 대구에서 시작된 운동입니다.","keywords":["국채 보상 운동"],"ref":{"tab":"terms","idx":4},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-11","grade":"h1"},
{"id":"hist-h-k1-11#t5","kind":"term","title":"여권통문","text":"1898년 서울의 여성들이 여성의 교육권·직업권·참정권을 주장하며 발표한 글입니다.","keywords":["여권통문"],"ref":{"tab":"terms","idx":5},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-11","grade":"h1"},
{"id":"hist-h-k1-11#t6","kind":"term","title":"원산 학사","text":"1883년 원산 주민들이 세운 최초의 근대 사립 학교입니다.","keywords":["원산 학사"],"ref":{"tab":"terms","idx":6},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-11","grade":"h1"},
{"id":"hist-h-k1-11#t7","kind":"term","title":"육영 공원","text":"1886년 정부가 세운 근대식 관립 학교입니다. 미국인 교사가 양반 자제를 가르쳤습니다.","keywords":["육영 공원"],"ref":{"tab":"terms","idx":7},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-11","grade":"h1"},
{"id":"hist-h-k1-11#t8","kind":"term","title":"한성순보","text":"1883년 박문국에서 펴낸 최초의 근대 신문입니다. 순한문으로 열흘마다 발행했습니다.","keywords":["한성순보"],"ref":{"tab":"terms","idx":8},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-11","grade":"h1"},
{"id":"hist-h-k1-11#t9","kind":"term","title":"독립신문","text":"1896년 서재필이 펴낸 최초의 민간 신문입니다. 한글판과 영문판을 냈습니다.","keywords":["독립신문"],"ref":{"tab":"terms","idx":9},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-11","grade":"h1"},
{"id":"hist-h-k1-11#f0","kind":"faq","title":"근대 문물이 들어온 건 좋은 일 아니에요?","text":"생활이 편리해지고 새로운 지식이 퍼진 것은 분명 긍정적인 면입니다. 하지만 철도·전신·광산 같은 시설과 자원의 상당 부분을 열강이 차지했고, 그것이 침략에 쓰이기도 했습니다. 그래서 근대 문물은 \"편리함\"과 \"침탈의 수단\"이라는 양면에서 평가합니다.","keywords":[],"ref":{"tab":"faq","idx":0},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-11","grade":"h1"},
{"id":"hist-h-k1-11#f1","kind":"faq","title":"방곡령은 정당한 조치였는데 왜 배상금까지 물었어요?","text":"1883년 조일 통상 장정에는 곡물 수출을 막으려면 1개월 전에 일본에 알려야 한다는 규정이 있었습니다. 일본은 이 통고가 제대로 되지 않았다며 항의했습니다. 힘이 약한 조선은 결국 방곡령을 철회하고 배상금을 물었습니다. 불평등한 조약 아래에서 경제 주권을 지키기가 얼마나 어려웠는지 보여 줍니다.","keywords":["방곡령"],"ref":{"tab":"faq","idx":1},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-11","grade":"h1"},
{"id":"hist-h-k1-11#f2","kind":"faq","title":"한성순보랑 독립신문은 뭐가 달라요?","text":"한성순보(1883년)는 정부 기관인 박문국이 순한문으로 펴낸 최초의 근대 신문으로, 정부 소식을 알리는 관보 성격이 강했습니다. 독립신문(1896년)은 서재필이 펴낸 최초의 민간 신문으로, 한글판과 영문판을 내어 많은 백성이 읽을 수 있게 했습니다.","keywords":["한성순보","독립신문"],"ref":{"tab":"faq","idx":2},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-11","grade":"h1"},
{"id":"hist-h-k1-11#f3","kind":"faq","title":"국채 보상 운동에는 누가 참여했어요?","text":"신분과 나이, 남녀를 가리지 않고 많은 사람이 참여했습니다. 남성들은 담배를 끊어 모은 돈을 내고, 여성들은 반지와 비녀를 내놓았으며, 학생과 상인, 노동자도 함께했습니다. 국민 모두가 나라의 경제 주권을 지키려 한 운동이었습니다.","keywords":["국채 보상 운동"],"ref":{"tab":"faq","idx":3},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-11","grade":"h1"},
{"id":"hist-h-k1-11#m0","kind":"mistake","title":"자주 하는 실수","text":"청 상인이 개항 직후부터 내륙에서 장사했다고 생각하는 실수 — 청 상인의 내륙 진출은 1882년 조청 상민 수륙 무역 장정 이후입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-11","grade":"h1"},
{"id":"hist-h-k1-11#m1","kind":"mistake","title":"자주 하는 실수","text":"한성순보를 최초의 민간 신문으로 아는 실수 — 한성순보는 정부가 펴낸 최초의 근대 신문이고, 최초의 민간 신문은 독립신문입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-11","grade":"h1"},
{"id":"hist-h-k1-11#m2","kind":"mistake","title":"자주 하는 실수","text":"방곡령이 성공했다고 아는 실수 — 일본의 항의로 방곡령은 철회되었고 조선은 배상금을 물었습니다.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-11","grade":"h1"},
{"id":"hist-h-k1-12","kind":"unit","title":"국권 침탈과 국권 수호 운동","text":"러일 전쟁 이후 일제가 국권을 빼앗아 간 과정과, 의병 운동과 애국 계몽 운동으로 이에 맞선 노력을 살펴봅니다. 러일 전쟁 이후 일제가 국권을 빼앗아 간 과정을 조약 순서대로 설명할 수 있다. 을사늑약에 맞선 저항과 헤이그 특사 파견의 의미를 설명할 수 있다. 항일 의병 운동과 의열 투쟁, 애국 계몽 운동의 전개와 특징을 비교할 수 있다. 대한 제국 칙령…","keywords":["을사늑약","통감부","한일 신협약","국권 피탈","헤이그 특사","정미의병","13도 창의군","애국 계몽 운동","신민회","대한 제국 칙령 제41호"],"ref":{"tab":"concepts","idx":0},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-12","grade":"h1"},
{"id":"hist-h-k1-12#c0","kind":"concept","title":"러일 전쟁과 을사늑약","text":"대한 제국을 두고 일본과 러시아의 대립이 깊어지자, 대한 제국은 1904년 1월 국외 중립을 선언했습니다. 그러나 일본은 이를 무시하고 1904년 2월 러일 전쟁을 일으켰습니다. 전쟁 중 일본은 대한 제국에 차례로 조약을 강요했습니다. 조약 · 내용 한일 의정서(1904년 2월) · 일","keywords":["을사늑약"],"ref":{"tab":"concepts","idx":0},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-12","grade":"h1"},
{"id":"hist-h-k1-12#c1","kind":"concept","title":"한일 신협약과 국권 피탈","text":"1907년 고종이 헤이그에 특사를 보낸 일을 구실로, 일본은 고종을 강제로 물러나게 했습니다. 이어 한일 신협약(정미 7조약)을 강요했습니다. 정부 각 부에 일본인 차관을 두어 실제 행정을 맡게 했습니다(차관 정치). 비밀리에 맺은 부속 각서에 따라 대한 제국 군대를 해산했습니다. 이후","keywords":["을사늑약","통감부","한일 신협약","국권 피탈"],"ref":{"tab":"concepts","idx":1},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-12","grade":"h1"},
{"id":"hist-h-k1-12#c2","kind":"concept","title":"을사늑약에 맞선 저항과 헤이그 특사","text":"을사늑약이 강요되자 곳곳에서 저항이 일어났습니다. 언론: 장지연은 황성신문에 「시일야방성대곡」(이날에 목 놓아 통곡하노라)을 실어 조약을 비판했습니다. 상소와 항거: 많은 관리와 유생이 조약 무효와 조약에 찬성한 대신(을사오적) 처벌을 요구했습니다. 을사오적을 처단하려는 움직임도 일어났","keywords":["을사늑약","헤이그 특사"],"ref":{"tab":"concepts","idx":2},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-12","grade":"h1"},
{"id":"hist-h-k1-12#c3","kind":"concept","title":"항일 의병 운동과 의열 투쟁","text":"나라가 위태로워질 때마다 사람들은 의병을 일으켜 무장 투쟁을 벌였습니다. 의병 · 계기 · 특징 을미의병(1895년) · 을미사변, 단발령 · 유인석 등 유생이 주도. 아관 파천 뒤 고종의 해산 권고로 대부분 해산 을사의병(1905년) · 을사늑약 · 최익현(전라도 태인)·민종식(홍주성","keywords":["을사늑약","정미의병","13도 창의군"],"ref":{"tab":"concepts","idx":3},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-12","grade":"h1"},
{"id":"hist-h-k1-12#c4","kind":"concept","title":"애국 계몽 운동","text":"무장 투쟁과 함께, 교육·언론·산업을 일으켜 실력을 길러 국권을 지키자는 애국 계몽 운동이 일어났습니다. 단체 · 활동 보안회(1904년) · 일본의 황무지 개간권 요구를 막아 냄 헌정 연구회(1905년) · 입헌 정치 체제를 세우자고 주장 대한 자강회(1906년) · 교육과 산업 진흥","keywords":["애국 계몽 운동","신민회"],"ref":{"tab":"concepts","idx":4},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-12","grade":"h1"},
{"id":"hist-h-k1-12#c5","kind":"concept","title":"독도와 간도","text":"독도 독도는 예로부터 울릉도에 딸린 우리 땅으로 여겨졌습니다. 『세종실록지리지』에는 울릉도(무릉)와 독도(우산)가 강원도 울진현에 속한다고 적혀 있고, 조선 숙종 때 안용복은 일본에 건너가 울릉도와 독도가 조선 땅임을 주장했습니다. 1900년 대한 제국은 칙령 제41호를 반포하여 울릉도","keywords":[],"ref":{"tab":"concepts","idx":5},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-12","grade":"h1"},
{"id":"hist-h-k1-12#t0","kind":"term","title":"을사늑약","text":"1905년 일본이 강요하여 대한 제국의 외교권을 빼앗고 통감부를 둔 조약입니다(제2차 한일 협약).","keywords":["을사늑약"],"ref":{"tab":"terms","idx":0},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-12","grade":"h1"},
{"id":"hist-h-k1-12#t1","kind":"term","title":"통감부","text":"을사늑약 뒤 일본이 서울에 둔 기구입니다. 외교를 넘어 내정까지 간섭했고, 초대 통감은 이토 히로부미였습니다.","keywords":["통감부"],"ref":{"tab":"terms","idx":1},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-12","grade":"h1"},
{"id":"hist-h-k1-12#t2","kind":"term","title":"한일 신협약","text":"1907년 고종을 강제로 물러나게 한 뒤 맺은 조약입니다. 차관 정치를 시작했고, 부속 각서로 군대를 해산했습니다.","keywords":["한일 신협약"],"ref":{"tab":"terms","idx":2},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-12","grade":"h1"},
{"id":"hist-h-k1-12#t3","kind":"term","title":"국권 피탈","text":"1910년 한국 병합 조약으로 대한 제국이 국권을 완전히 빼앗긴 일입니다.","keywords":["국권 피탈"],"ref":{"tab":"terms","idx":3},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-12","grade":"h1"},
{"id":"hist-h-k1-12#t4","kind":"term","title":"헤이그 특사","text":"1907년 고종이 을사늑약의 부당함을 알리려고 만국 평화 회의에 보낸 이준·이상설·이위종입니다.","keywords":["헤이그 특사"],"ref":{"tab":"terms","idx":4},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-12","grade":"h1"},
{"id":"hist-h-k1-12#t5","kind":"term","title":"정미의병","text":"1907년 고종 강제 퇴위와 군대 해산에 맞서 일어난 의병입니다. 해산 군인이 합류해 전투력이 강해졌습니다.","keywords":["정미의병"],"ref":{"tab":"terms","idx":5},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-12","grade":"h1"},
{"id":"hist-h-k1-12#t6","kind":"term","title":"13도 창의군","text":"1907년 전국의 의병이 모여 만든 연합 부대입니다. 1908년 서울 진공 작전을 펼쳤습니다.","keywords":["13도 창의군"],"ref":{"tab":"terms","idx":6},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-12","grade":"h1"},
{"id":"hist-h-k1-12#t7","kind":"term","title":"애국 계몽 운동","text":"교육·언론·산업을 일으켜 실력을 길러 국권을 지키려 한 운동입니다.","keywords":["애국 계몽 운동"],"ref":{"tab":"terms","idx":7},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-12","grade":"h1"},
{"id":"hist-h-k1-12#t8","kind":"term","title":"신민회","text":"1907년 안창호·양기탁 등이 만든 비밀 결사입니다. 공화정의 국민 국가를 목표로 학교 설립과 국외 독립운동 기지 건설에 힘썼습니다.","keywords":["신민회"],"ref":{"tab":"terms","idx":8},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-12","grade":"h1"},
{"id":"hist-h-k1-12#t9","kind":"term","title":"대한 제국 칙령 제41호","text":"1900년 울릉도를 울도군으로 높이고 울도 군수가 석도(독도)를 관할하게 한 법령입니다.","keywords":["대한 제국 칙령 제41호"],"ref":{"tab":"terms","idx":9},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-12","grade":"h1"},
{"id":"hist-h-k1-12#f0","kind":"faq","title":"을사조약이 아니라 왜 을사늑약이라고 해요?","text":"\"늑약\"은 억지로 강요하여 맺은 조약이라는 뜻입니다. 1905년 일본은 군대로 궁궐을 에워싸고 대신들을 위협하여 조약을 맺게 했고, 고종은 끝까지 이를 인정하지 않았습니다. 그래서 정상적인 조약이 아니라는 뜻을 담아 을사늑약이라고 부릅니다.","keywords":["을사늑약"],"ref":{"tab":"faq","idx":0},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-12","grade":"h1"},
{"id":"hist-h-k1-12#f1","kind":"faq","title":"의병 운동과 애국 계몽 운동은 뭐가 달라요?","text":"의병 운동은 무기를 들고 일본군과 직접 싸운 무장 투쟁입니다. 애국 계몽 운동은 학교·신문·회사를 세워 국민의 실력을 길러 국권을 지키려 한 운동입니다. 방법은 달랐지만 국권을 지키려는 목표는 같았고, 신민회의 국외 독립운동 기지처럼 두 흐름이 만나기도 했습니다.","keywords":["애국 계몽 운동"],"ref":{"tab":"faq","idx":1},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-12","grade":"h1"},
{"id":"hist-h-k1-12#f2","kind":"faq","title":"독도가 우리 땅이라는 역사적 근거는 뭐예요?","text":"『세종실록지리지』는 울릉도와 독도를 강원도 울진현에 속한 섬으로 적었고, 조선 숙종 때 안용복은 일본에 가서 두 섬이 조선 땅임을 주장했습니다. 1877년 일본 최고 행정 기관(태정관)도 울릉도와 독도가 일본과 관계없다는 지시를 내렸습니다. 그리고 1900년 대한 제국은 칙령 제41호로 독도를 울도군 관할로 정했습니다.","keywords":[],"ref":{"tab":"faq","idx":2},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-12","grade":"h1"},
{"id":"hist-h-k1-12#f3","kind":"faq","title":"헤이그 특사는 왜 실패했어요?","text":"을사늑약으로 대한 제국은 외교권을 빼앗긴 상태였습니다. 그래서 회의 측은 외교권이 없는 나라의 대표를 정식으로 받아들이지 않았고, 일본도 참석을 방해했습니다. 특사들은 회의장 밖에서 언론을 통해 일본의 침략을 알렸지만, 일본은 이를 구실로 고종을 강제로 물러나게 했습니다.","keywords":["헤이그 특사"],"ref":{"tab":"faq","idx":3},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-12","grade":"h1"},
{"id":"hist-h-k1-12#m0","kind":"mistake","title":"자주 하는 실수","text":"을사늑약과 한일 신협약의 내용을 바꾸어 아는 실수 — 을사늑약(1905년)은 외교권 박탈·통감부 설치, 한일 신협약(1907년)은 차관 정치·군대 해산입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-12","grade":"h1"},
{"id":"hist-h-k1-12#m1","kind":"mistake","title":"자주 하는 실수","text":"해산 군인이 을사의병에 합류했다고 아는 실수 — 군대 해산은 1907년이므로, 해산 군인이 합류한 것은 정미의병입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-12","grade":"h1"},
{"id":"hist-h-k1-12#m2","kind":"mistake","title":"자주 하는 실수","text":"간도 협약을 대한 제국이 맺었다고 아는 실수 — 외교권을 빼앗은 일본이 청과 맺은 협약입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-h-k1","unit":"hist-h-k1-12","grade":"h1"},
{"id":"hist-h-k2-01","kind":"unit","title":"일제의 식민 통치와 경제 수탈","text":"일제의 식민 통치 정책이 시기마다 어떻게 바뀌었는지, 식민지 경제 구조가 사람들의 삶을 어떻게 바꾸었는지 분석합니다. 1910년대 무단 통치, 1920년대 이른바 ‘문화 통치’, 1930년대 이후 민족 말살 통치의 특징을 비교할 수 있다. 토지 조사 사업·회사령·산미 증식 계획·병참 기지화가 한국인의 경제생활에 끼친 영향을 설명할 수 있다. 세계 대전과 …","keywords":["조선 총독부","헌병 경찰","즉결 처분권","토지 조사 사업","회사령","산미 증식 계획","치안 유지법","병참 기지화","국가 총동원법","창씨개명"],"ref":{"tab":"concepts","idx":0},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-01","grade":"h1"},
{"id":"hist-h-k2-01#c0","kind":"concept","title":"조선 총독부와 1910년대 무단 통치","text":"1910년 국권을 빼앗은 일제는 조선 총독부를 설치해 한국을 식민지로 다스렸습니다. 총독은 일본의 현역 육·해군 대장 가운데에서 임명되었고, 일본 왕에게 직속되어 입법·행정·사법권과 군대 통수권을 모두 쥐었습니다. 한국인의 의견을 듣는다며 둔 중추원은 실제 권한이 없는 자문 기구에 지나","keywords":["조선 총독부","헌병 경찰","즉결 처분권"],"ref":{"tab":"concepts","idx":0},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-01","grade":"h1"},
{"id":"hist-h-k2-01#c1","kind":"concept","title":"토지 조사 사업과 회사령","text":"일제는 식민지 경제의 기초를 다지려고 토지 조사 사업(1910~1918년)을 벌였습니다. 1912년 토지 조사령을 발표해, 토지 소유자가 정해진 기간 안에 복잡한 서류를 갖추어 신고해야 소유권을 인정받게 했습니다. 신고되지 않은 토지, 왕실과 관청이 가지고 있던 땅, 마을이나 문중이 함","keywords":["조선 총독부","토지 조사 사업","회사령"],"ref":{"tab":"concepts","idx":1},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-01","grade":"h1"},
{"id":"hist-h-k2-01#c2","kind":"concept","title":"1920년대 이른바 ‘문화 통치’","text":"3·1 운동(1919년)으로 무력만으로는 한국인을 다스리기 어렵다는 것을 깨달은 일제는 통치 방식을 바꾸어 이른바 ‘문화 통치’를 내세웠습니다. 그러나 내세운 것과 실제는 크게 달랐습니다. 내세운 것 · 실제 문관도 총독에 임명할 수 있음 · 광복 때까지 문관 출신 총독은 한 명도 임명","keywords":["헌병 경찰","치안 유지법"],"ref":{"tab":"concepts","idx":2},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-01","grade":"h1"},
{"id":"hist-h-k2-01#c3","kind":"concept","title":"국제 질서의 변동과 식민 경제 정책","text":"식민 통치 정책은 국제 정세와 일본 경제의 형편에 따라 바뀌었습니다. 원인 → 일본의 필요 → 식민지 정책의 흐름으로 보면 이해가 쉽습니다. 1920년대: 제1차 세계 대전 뒤의 쌀 부족 → 산미 증식 계획 제1차 세계 대전(1914~1918년) 동안 일본은 공업이 빠르게 성장해 도시 ","keywords":["산미 증식 계획"],"ref":{"tab":"concepts","idx":3},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-01","grade":"h1"},
{"id":"hist-h-k2-01#c4","kind":"concept","title":"민족 말살 통치와 인력·물자 수탈","text":"중일 전쟁(1937년) 뒤 일제는 한국인을 전쟁에 동원하려고 민족의 정체성 자체를 없애려 했습니다. 이를 민족 말살 통치라고 합니다. 내선일체(일본과 조선은 한 몸), 일선 동조론(일본과 조선의 조상이 같다)을 내세웠습니다. 황국 신민 서사 암송, 신사 참배, 일본 왕이 사는 궁성을 향","keywords":["국가 총동원법","창씨개명"],"ref":{"tab":"concepts","idx":4},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-01","grade":"h1"},
{"id":"hist-h-k2-01#c5","kind":"concept","title":"경제 침탈과 해외 이주 동포의 삶","text":"경제 수탈로 살길이 막히거나, 탄압을 피해 독립운동을 이어 가려고 많은 한국인이 나라 밖으로 떠났습니다. 지역 · 이주 배경과 삶 만주(간도) · 19세기 후반부터 농민이 이주했고, 국권 피탈 뒤 독립운동 기지가 되었습니다. 독립군을 쫓던 일본군이 한인 마을을 습격한 간도 참변(1920","keywords":[],"ref":{"tab":"concepts","idx":5},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-01","grade":"h1"},
{"id":"hist-h-k2-01#t0","kind":"term","title":"조선 총독부","text":"일제가 1910년 한국을 식민지로 다스리려고 설치한 최고 통치 기구입니다. 총독은 입법·행정·사법권과 군대 통수권을 모두 가졌습니다.","keywords":["조선 총독부"],"ref":{"tab":"terms","idx":0},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-01","grade":"h1"},
{"id":"hist-h-k2-01#t1","kind":"term","title":"헌병 경찰","text":"군사 경찰인 헌병이 일반 경찰 업무까지 맡은 1910년대의 제도입니다. 재판 없이 벌을 내리는 즉결 처분권을 가졌습니다.","keywords":["헌병 경찰"],"ref":{"tab":"terms","idx":1},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-01","grade":"h1"},
{"id":"hist-h-k2-01#t2","kind":"term","title":"즉결 처분권","text":"헌병 경찰이 정식 재판 없이 그 자리에서 벌금·구류·태형 등의 벌을 내릴 수 있었던 권한입니다.","keywords":["즉결 처분권"],"ref":{"tab":"terms","idx":2},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-01","grade":"h1"},
{"id":"hist-h-k2-01#t3","kind":"term","title":"토지 조사 사업","text":"1910~1918년 일제가 실시한 토지 조사입니다. 기한 안에 신고하게 하여 많은 땅을 총독부 소유로 만들고, 농민의 경작권을 부정했습니다.","keywords":["토지 조사 사업"],"ref":{"tab":"terms","idx":3},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-01","grade":"h1"},
{"id":"hist-h-k2-01#t4","kind":"term","title":"회사령","text":"1910년 공포된 법으로, 회사를 세우려면 조선 총독의 허가를 받게 했습니다. 민족 자본의 성장을 막았고 1920년에 폐지되었습니다.","keywords":["회사령"],"ref":{"tab":"terms","idx":4},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-01","grade":"h1"},
{"id":"hist-h-k2-01#t5","kind":"term","title":"산미 증식 계획","text":"1920~1934년 일본의 쌀 부족을 한국에서 채우려고 쌀 생산을 늘리려 한 정책입니다. 생산 증가보다 반출이 많아 한국인의 쌀 소비가 줄었습니다.","keywords":["산미 증식 계획"],"ref":{"tab":"terms","idx":5},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-01","grade":"h1"},
{"id":"hist-h-k2-01#t6","kind":"term","title":"치안 유지법","text":"1925년 일제가 만든 법으로, 사회주의 운동과 독립운동을 탄압하는 데 쓰였습니다.","keywords":["치안 유지법"],"ref":{"tab":"terms","idx":6},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-01","grade":"h1"},
{"id":"hist-h-k2-01#t7","kind":"term","title":"병참 기지화","text":"1930년대 이후 일제가 대륙 침략 전쟁에 필요한 물자를 대도록 한국의 산업을 군수 공업 중심으로 바꾼 것입니다.","keywords":["병참 기지화"],"ref":{"tab":"terms","idx":7},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-01","grade":"h1"},
{"id":"hist-h-k2-01#t8","kind":"term","title":"국가 총동원법","text":"1938년 일제가 전쟁에 필요한 인력과 물자를 마음대로 동원하려고 적용한 법입니다. 징용·공출 등의 근거가 되었습니다.","keywords":["국가 총동원법"],"ref":{"tab":"terms","idx":8},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-01","grade":"h1"},
{"id":"hist-h-k2-01#t9","kind":"term","title":"창씨개명","text":"1940년부터 일제가 한국인에게 일본식 성과 이름으로 바꾸도록 강요한 정책입니다.","keywords":["창씨개명"],"ref":{"tab":"terms","idx":9},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-01","grade":"h1"},
{"id":"hist-h-k2-01#f0","kind":"faq","title":"‘문화 통치’는 무단 통치보다 좋아진 것 아닌가요?","text":"겉모습은 부드러워졌지만 지배의 본질은 그대로였습니다. 경찰 수와 예산은 오히려 늘었고, 신문은 검열을 받았으며, 치안 유지법으로 독립운동을 탄압했습니다. 오히려 일부 한국인을 친일 세력으로 끌어들여 민족을 분열시키려 했다는 점에서 더 교묘한 통치였습니다.","keywords":[],"ref":{"tab":"faq","idx":0},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-01","grade":"h1"},
{"id":"hist-h-k2-01#f1","kind":"faq","title":"쌀 생산이 늘었는데 왜 한국인은 쌀을 덜 먹었나요?","text":"늘어난 생산량보다 일본으로 가져간 양이 훨씬 많았기 때문입니다. 한국 안에 남은 쌀이 줄어 한국인은 만주에서 들여온 조·콩 같은 잡곡으로 모자란 식량을 메웠습니다. 생산이 늘었다는 것과 그 쌀을 누가 먹었느냐는 다른 문제입니다.","keywords":[],"ref":{"tab":"faq","idx":1},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-01","grade":"h1"},
{"id":"hist-h-k2-01#f2","kind":"faq","title":"토지 조사 사업 때 신고를 안 해서 땅을 다 빼앗긴 건가요?","text":"신고되지 않아 총독부 소유가 된 땅도 있었지만, 그것이 피해의 전부는 아닙니다. 왕실·관청의 땅과 마을 공유지가 총독부 소유가 되었고, 무엇보다 농민의 관습적 경작권이 부정되어 많은 농민이 불안정한 소작농이 되었습니다.","keywords":["토지 조사 사업"],"ref":{"tab":"faq","idx":2},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-01","grade":"h1"},
{"id":"hist-h-k2-01#m0","kind":"mistake","title":"자주 하는 실수","text":"산미 증식 계획으로 쌀 생산이 늘었으니 한국인의 생활도 나아졌다고 생각하는 실수 — 반출량이 더 많아 1인당 쌀 소비는 줄었고 농민 부담은 커졌습니다.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-01","grade":"h1"},
{"id":"hist-h-k2-01#m1","kind":"mistake","title":"자주 하는 실수","text":"‘문화 통치’를 일제가 한국인의 자유를 보장한 통치로 이해하는 실수 — 경찰력은 늘고 검열·치안 유지법으로 탄압은 계속된, 민족 분열 통치였습니다.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-01","grade":"h1"},
{"id":"hist-h-k2-01#m2","kind":"mistake","title":"자주 하는 실수","text":"시기를 섞는 실수 — 헌병 경찰·회사령·토지 조사 사업은 1910년대, 산미 증식 계획·치안 유지법은 1920년대, 창씨개명·국가 총동원법·징병제는 1930년대 후반 이후입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-01","grade":"h1"},
{"id":"hist-h-k2-02","kind":"unit","title":"3·1 운동과 임시 정부","text":"1910년대 국내외 독립운동에서 3·1 운동으로 이어진 흐름과, 대한민국 임시 정부 수립의 의의를 이해합니다. 1910년대 국내 비밀 결사와 국외 독립운동 기지의 활동을 설명할 수 있다. 3·1 운동의 배경과 전개 과정을 순서대로 정리할 수 있다. 3·1 운동의 의의와 세계 민족 운동에 끼친 영향을 설명할 수 있다. 대한민국 임시 정부의 수립 과정과 민주…","keywords":["독립 의군부","대한 광복회","신흥 무관 학교","민족 자결주의","2·8 독립 선언","민주 공화제","임시 의정원","연통제","교통국","국민 대표 회의"],"ref":{"tab":"concepts","idx":0},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-02","grade":"h1"},
{"id":"hist-h-k2-02#c0","kind":"concept","title":"1910년대 국내 비밀 결사","text":"무단 통치로 드러내 놓고 활동하기 어려워지자, 국내의 독립운동은 비밀 결사의 형태로 이어졌습니다. 1911년 일제가 105인 사건을 꾸며 신민회를 무너뜨린 뒤에도 독립운동의 맥은 끊기지 않았습니다. 단체 · 중심 인물·지역 · 목표와 활동 독립 의군부(1912년) · 임병찬, 전라도 ·","keywords":["독립 의군부","대한 광복회","민주 공화제"],"ref":{"tab":"concepts","idx":0},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-02","grade":"h1"},
{"id":"hist-h-k2-02#c1","kind":"concept","title":"국외 독립운동 기지 건설","text":"독립운동가들은 일제의 감시가 미치기 어려운 나라 밖에 독립운동 기지를 세웠습니다. 한인이 모여 사는 마을을 만들고, 학교를 세워 인재를 기르고, 독립군을 길러 독립 전쟁을 준비하려는 것이었습니다. 지역 · 주요 활동 서간도(남만주) · 신민회 회원들이 삼원보에 경학사를 세우고, 신흥 강","keywords":["신흥 무관 학교"],"ref":{"tab":"concepts","idx":1},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-02","grade":"h1"},
{"id":"hist-h-k2-02#c2","kind":"concept","title":"3·1 운동의 배경과 전개","text":"배경 국내: 무단 통치와 토지 조사 사업 등으로 한국인의 불만이 쌓였습니다. 1919년 1월 고종이 갑자기 세상을 떠나자 독살되었다는 소문이 퍼져 분노가 커졌습니다. 국제: 제1차 세계 대전이 끝날 무렵 미국 대통령 윌슨이 민족 자결주의(각 민족은 자기 운명을 스스로 결정해야 한다)를 ","keywords":["민족 자결주의","2·8 독립 선언"],"ref":{"tab":"concepts","idx":2},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-02","grade":"h1"},
{"id":"hist-h-k2-02#c3","kind":"concept","title":"3·1 운동의 의의와 세계에 끼친 영향","text":"3·1 운동은 실패로 끝난 운동이 아닙니다. 당장 독립을 이루지는 못했지만 우리 역사의 방향을 크게 바꾸었습니다. 국내에 남긴 의의 모든 계층(학생·농민·노동자·상인·종교인, 남녀노소)이 함께 참여한 최대 규모의 민족 운동으로, 독립 의지를 세계에 알렸습니다. 독립운동을 하나로 이끌 지","keywords":[],"ref":{"tab":"concepts","idx":3},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-02","grade":"h1"},
{"id":"hist-h-k2-02#c4","kind":"concept","title":"대한민국 임시 정부의 수립과 민주 공화제","text":"3·1 운동 직후 여러 곳에서 임시 정부가 세워졌습니다. 이름 · 곳 · 특징 대한 국민 의회 · 연해주 · 1919년 3월 수립 대한민국 임시 정부 · 상하이 · 1919년 4월 임시 의정원을 구성하고 대한민국 임시 헌장 발표 한성 정부 · 서울 · 1919년 4월 13도 대표가 국민","keywords":["민주 공화제","임시 의정원"],"ref":{"tab":"concepts","idx":4},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-02","grade":"h1"},
{"id":"hist-h-k2-02#c5","kind":"concept","title":"대한민국 임시 정부의 활동과 시련","text":"임시 정부는 나라 밖에 있으면서도 국내와 이어지고, 세계에 독립을 호소하려 애썼습니다. 분야 · 활동 국내와 연결 · 연통제(국내의 비밀 행정 조직)와 교통국(비밀 통신 조직)을 두어 정부 문서를 전하고 독립 자금을 모으며 정보를 모음 독립 자금 · 독립 공채를 발행하고 의연금을 모음.","keywords":["연통제","교통국"],"ref":{"tab":"concepts","idx":5},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-02","grade":"h1"},
{"id":"hist-h-k2-02#t0","kind":"term","title":"독립 의군부","text":"1912년 임병찬이 고종의 밀지를 받아 조직한 비밀 결사입니다. 왕조를 다시 세우려는 복벽주의를 내세웠습니다.","keywords":["독립 의군부"],"ref":{"tab":"terms","idx":0},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-02","grade":"h1"},
{"id":"hist-h-k2-02#t1","kind":"term","title":"대한 광복회","text":"1915년 박상진을 중심으로 대구에서 조직된 비밀 결사입니다. 공화정 국가 수립을 목표로 군자금 모금과 친일 부호 처단 활동을 했습니다.","keywords":["대한 광복회"],"ref":{"tab":"terms","idx":1},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-02","grade":"h1"},
{"id":"hist-h-k2-02#t2","kind":"term","title":"신흥 무관 학교","text":"서간도 삼원보에 세운 신흥 강습소(1911년)가 발전한 학교로, 많은 독립군 간부를 길러 냈습니다.","keywords":["신흥 무관 학교"],"ref":{"tab":"terms","idx":2},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-02","grade":"h1"},
{"id":"hist-h-k2-02#t3","kind":"term","title":"민족 자결주의","text":"각 민족이 자기 운명을 스스로 결정해야 한다는 주장입니다. 제1차 세계 대전 무렵 미국 대통령 윌슨이 내세워 3·1 운동의 국제적 배경이 되었습니다.","keywords":["민족 자결주의"],"ref":{"tab":"terms","idx":3},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-02","grade":"h1"},
{"id":"hist-h-k2-02#t4","kind":"term","title":"2·8 독립 선언","text":"1919년 2월 8일 일본 도쿄의 한국인 유학생들이 발표한 독립 선언으로, 3·1 운동에 영향을 주었습니다.","keywords":["2·8 독립 선언"],"ref":{"tab":"terms","idx":4},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-02","grade":"h1"},
{"id":"hist-h-k2-02#t5","kind":"term","title":"민주 공화제","text":"국민이 주권을 가지고, 국민이 뽑은 대표가 나라를 다스리는 정치 체제입니다. 대한민국 임시 헌장 제1조에 담겼습니다.","keywords":["민주 공화제"],"ref":{"tab":"terms","idx":5},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-02","grade":"h1"},
{"id":"hist-h-k2-02#t6","kind":"term","title":"임시 의정원","text":"대한민국 임시 정부의 입법 기관입니다. 오늘날의 국회에 해당합니다.","keywords":["임시 의정원"],"ref":{"tab":"terms","idx":6},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-02","grade":"h1"},
{"id":"hist-h-k2-02#t7","kind":"term","title":"연통제","text":"대한민국 임시 정부가 국내와 연결하려고 만든 비밀 행정 조직입니다. 정부 문서 전달과 독립 자금 모금을 맡았습니다.","keywords":["연통제"],"ref":{"tab":"terms","idx":7},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-02","grade":"h1"},
{"id":"hist-h-k2-02#t8","kind":"term","title":"교통국","text":"대한민국 임시 정부의 비밀 통신 조직으로, 국내외 정보 수집과 연락을 맡았습니다.","keywords":["교통국"],"ref":{"tab":"terms","idx":8},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-02","grade":"h1"},
{"id":"hist-h-k2-02#t9","kind":"term","title":"국민 대표 회의","text":"1923년 임시 정부의 진로를 놓고 열린 회의입니다. 창조파와 개조파가 맞서 결렬되었습니다.","keywords":["국민 대표 회의"],"ref":{"tab":"terms","idx":9},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-02","grade":"h1"},
{"id":"hist-h-k2-02#f0","kind":"faq","title":"3·1 운동은 독립을 못 이루었는데 왜 그렇게 중요하게 배워요?","text":"당장 독립을 이루지는 못했지만 독립운동의 방향을 바꾸었기 때문입니다. 대한민국 임시 정부가 세워졌고, 무장 투쟁과 대중 운동이 활발해졌으며, 일제의 통치 방식까지 바꾸게 했습니다. 아시아의 다른 민족 운동에도 영향을 주었습니다.","keywords":[],"ref":{"tab":"faq","idx":0},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-02","grade":"h1"},
{"id":"hist-h-k2-02#f1","kind":"faq","title":"임시 정부가 왜 여러 개였어요?","text":"3·1 운동 직후 연해주(대한 국민 의회), 상하이(대한민국 임시 정부), 서울(한성 정부) 등에서 거의 동시에 임시 정부가 세워졌기 때문입니다. 독립운동의 힘을 하나로 모으려고 1919년 9월 상하이의 대한민국 임시 정부로 통합했습니다.","keywords":[],"ref":{"tab":"faq","idx":1},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-02","grade":"h1"},
{"id":"hist-h-k2-02#f2","kind":"faq","title":"민주 공화제가 정확히 뭐예요?","text":"왕이 아니라 국민이 나라의 주인(주권자)이고, 국민이 뽑은 대표가 나라를 다스리는 정치 체제입니다. 대한민국 임시 헌장 제1조에 처음 담겼고, 오늘날 대한민국 헌법 제1조도 \"대한민국은 민주공화국이다\"라고 밝히고 있습니다.","keywords":["민주 공화제"],"ref":{"tab":"faq","idx":2},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-02","grade":"h1"},
{"id":"hist-h-k2-02#m0","kind":"mistake","title":"자주 하는 실수","text":"독립 의군부와 대한 광복회의 목표를 바꾸어 기억하는 실수 — 독립 의군부는 복벽주의, 대한 광복회는 공화정 수립입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-02","grade":"h1"},
{"id":"hist-h-k2-02#m1","kind":"mistake","title":"자주 하는 실수","text":"임시 정부가 3·1 운동보다 먼저 세워졌다고 생각하는 실수 — 3·1 운동(1919년 3월)을 계기로 임시 정부(1919년 4월 수립, 9월 통합)가 세워졌습니다.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-02","grade":"h1"},
{"id":"hist-h-k2-02#m2","kind":"mistake","title":"자주 하는 실수","text":"연통제(비밀 행정 조직)와 교통국(비밀 통신 조직)을 섞어 기억하는 실수 — ‘연통’은 행정 연락망, ‘교통’은 통신·연락망으로 구분하세요.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-02","grade":"h1"},
{"id":"hist-h-k2-03","kind":"unit","title":"민족 운동의 전개와 분화","text":"실력 양성 운동과 무장 투쟁, 의열 투쟁 등 여러 갈래의 민족 운동과 신간회로 힘을 모은 노력을 살펴봅니다. 물산 장려 운동과 민립 대학 설립 운동의 목적과 한계를 설명할 수 있다. 사회주의 사상의 확산으로 민족 운동이 분화한 과정과, 6·10 만세 운동·신간회·광주 학생 항일 운동으로 이어진 연대의 흐름을 설명할 수 있다. 봉오동·청산리 전투의 의의와 …","keywords":["물산 장려 운동","민립 대학 설립 운동","자치론","6·10 만세 운동","신간회","광주 학생 항일 운동","간도 참변","자유시 참변","의열단","한인 애국단"],"ref":{"tab":"concepts","idx":0},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-03","grade":"h1"},
{"id":"hist-h-k2-03#c0","kind":"concept","title":"실력 양성 운동","text":"3·1 운동 뒤 일부 민족주의자들은 \"당장 독립하기 어렵다면 먼저 경제와 교육의 실력을 길러 독립의 기반을 마련하자\"고 생각했습니다. 이를 실력 양성 운동이라고 합니다. 물산 장려 운동 배경: 1920년 회사령이 폐지되고 일본 상품에 매기던 관세도 없어질 것으로 예상되자, 일본 자본과 ","keywords":["물산 장려 운동"],"ref":{"tab":"concepts","idx":0},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-03","grade":"h1"},
{"id":"hist-h-k2-03#c1","kind":"concept","title":"사회주의 사상의 확산과 민족 운동의 분화","text":"3·1 운동 뒤 러시아 혁명의 영향으로 사회주의 사상이 청년·지식인 사이에 빠르게 퍼졌습니다. 사회주의자들은 민족의 독립과 함께 농민·노동자가 차별받지 않는 사회를 만들자고 주장했고, 농민·노동 운동과 청년·여성 운동을 이끌었습니다. 1925년에는 조선 공산당이 비밀리에 만들어졌지만, ","keywords":["자치론"],"ref":{"tab":"concepts","idx":1},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-03","grade":"h1"},
{"id":"hist-h-k2-03#c2","kind":"concept","title":"6·10 만세 운동과 신간회","text":"6·10 만세 운동 (1926년) 대한 제국의 마지막 황제 순종이 세상을 떠나자, 사회주의 계열과 천도교 계열, 학생들이 순종의 장례일(인산일)에 맞추어 만세 시위를 준비했습니다. 계획이 미리 드러나 많은 사람이 체포되었지만, 6월 10일 학생들이 장례 행렬을 따라 만세 시위를 벌였습니","keywords":["6·10 만세 운동","신간회"],"ref":{"tab":"concepts","idx":2},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-03","grade":"h1"},
{"id":"hist-h-k2-03#c3","kind":"concept","title":"광주 학생 항일 운동","text":"1929년 10월 말, 광주와 나주를 오가는 통학 열차에서 일본인 학생이 한국인 여학생을 희롱하면서 한국인 학생과 일본인 학생이 충돌했습니다. 일본 경찰이 일본인 학생 편을 들며 한국인 학생만 처벌하자, 11월 3일 광주의 한국인 학생들이 대규모 시위에 나섰습니다. 배경: 일상에서 쌓인","keywords":["6·10 만세 운동","신간회","광주 학생 항일 운동"],"ref":{"tab":"concepts","idx":3},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-03","grade":"h1"},
{"id":"hist-h-k2-03#c4","kind":"concept","title":"봉오동·청산리 전투와 독립군의 시련","text":"3·1 운동 뒤 만주와 연해주에서는 많은 독립군 부대가 조직되어 국경을 넘나들며 일본군과 싸웠습니다. 승리 봉오동 전투(1920년 6월): 홍범도가 이끄는 대한 독립군을 중심으로 한 연합 부대가 봉오동으로 일본군을 끌어들여 크게 이겼습니다. 청산리 전투(1920년 10월): 김좌진의 북","keywords":["간도 참변","자유시 참변"],"ref":{"tab":"concepts","idx":4},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-03","grade":"h1"},
{"id":"hist-h-k2-03#c5","kind":"concept","title":"의열 투쟁 — 의열단과 한인 애국단","text":"의열 투쟁은 적은 인원으로 일제의 핵심 기관을 파괴하거나 침략의 책임자를 처단하여 일제에 타격을 주고 민족의 독립 의지를 알린 투쟁입니다. 의열단 (1919년) 김원봉 등이 만주에서 조직했습니다. 신채호가 쓴 조선 혁명 선언(1923년)을 활동 지침으로 삼아, 민중의 직접 혁명으로 일제","keywords":["의열단","한인 애국단"],"ref":{"tab":"concepts","idx":5},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-03","grade":"h1"},
{"id":"hist-h-k2-03#t0","kind":"term","title":"물산 장려 운동","text":"1920년대 우리 상품(토산품)을 쓰자며 일어난 경제적 실력 양성 운동입니다. \"내 살림 내 것으로\"를 구호로 삼았습니다.","keywords":["물산 장려 운동"],"ref":{"tab":"terms","idx":0},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-03","grade":"h1"},
{"id":"hist-h-k2-03#t1","kind":"term","title":"민립 대학 설립 운동","text":"1920년대 한국인의 힘으로 대학을 세우려고 모금을 벌인 운동입니다. 일제의 방해로 실패했습니다.","keywords":["민립 대학 설립 운동"],"ref":{"tab":"terms","idx":1},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-03","grade":"h1"},
{"id":"hist-h-k2-03#t2","kind":"term","title":"자치론","text":"일제의 지배를 인정한 상태에서 자치권을 얻자는 타협적 민족주의자의 주장입니다.","keywords":["자치론"],"ref":{"tab":"terms","idx":2},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-03","grade":"h1"},
{"id":"hist-h-k2-03#t3","kind":"term","title":"6·10 만세 운동","text":"1926년 순종의 장례일에 학생들이 중심이 되어 일어난 만세 시위입니다. 민족주의·사회주의 계열의 연대 가능성을 보여 주었습니다.","keywords":["6·10 만세 운동"],"ref":{"tab":"terms","idx":3},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-03","grade":"h1"},
{"id":"hist-h-k2-03#t4","kind":"term","title":"신간회","text":"1927년 비타협적 민족주의자와 사회주의자가 함께 만든 민족 협동 전선으로, 일제 강점기 최대의 합법적 항일 단체입니다.","keywords":["신간회"],"ref":{"tab":"terms","idx":4},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-03","grade":"h1"},
{"id":"hist-h-k2-03#t5","kind":"term","title":"광주 학생 항일 운동","text":"1929년 광주에서 시작된 학생들의 항일 운동으로, 3·1 운동 이후 최대 규모의 민족 운동입니다.","keywords":["광주 학생 항일 운동"],"ref":{"tab":"terms","idx":5},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-03","grade":"h1"},
{"id":"hist-h-k2-03#t6","kind":"term","title":"간도 참변","text":"1920년 봉오동·청산리 전투에서 진 일본군이 보복으로 간도의 한인을 학살한 사건입니다.","keywords":["간도 참변"],"ref":{"tab":"terms","idx":6},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-03","grade":"h1"},
{"id":"hist-h-k2-03#t7","kind":"term","title":"자유시 참변","text":"1921년 러시아 자유시로 옮겨 간 독립군이 무장 해제를 강요당하는 과정에서 큰 피해를 입은 사건입니다.","keywords":["자유시 참변"],"ref":{"tab":"terms","idx":7},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-03","grade":"h1"},
{"id":"hist-h-k2-03#t8","kind":"term","title":"의열단","text":"1919년 김원봉 등이 만주에서 조직한 단체로, 식민 통치 기관 파괴와 요인 처단 같은 의열 투쟁을 벌였습니다.","keywords":["의열단"],"ref":{"tab":"terms","idx":8},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-03","grade":"h1"},
{"id":"hist-h-k2-03#t9","kind":"term","title":"한인 애국단","text":"1931년 김구가 상하이에서 조직한 단체로, 1932년 이봉창·윤봉길의 의거를 이끌었습니다.","keywords":["한인 애국단"],"ref":{"tab":"terms","idx":9},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-03","grade":"h1"},
{"id":"hist-h-k2-03#f0","kind":"faq","title":"6·10 만세 운동이랑 광주 학생 항일 운동이 자꾸 헷갈려요.","text":"둘 다 학생이 앞장섰지만 계기와 시기가 다릅니다. 6·10 만세 운동은 1926년 순종의 장례일에 일어났고, 광주 학생 항일 운동은 1929년 통학 열차의 한일 학생 충돌을 일본 경찰이 편파적으로 처리한 것이 계기였습니다. 시기 사이에 1927년 신간회 결성이 있다는 것도 함께 기억하세요.","keywords":["6·10 만세 운동","광주 학생 항일 운동"],"ref":{"tab":"faq","idx":0},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-03","grade":"h1"},
{"id":"hist-h-k2-03#f1","kind":"faq","title":"신간회는 왜 오래가지 못하고 해소되었어요?","text":"지도부 일부가 온건한 방향으로 바뀌자 사회주의자들의 불만이 커졌고, 국제 공산당(코민테른)이 노선을 바꾸어 민족주의자와의 협력보다 노동자·농민 중심의 운동을 강조하자 사회주의 계열이 해소를 주장했습니다. 결국 1931년 해소되었습니다.","keywords":["신간회"],"ref":{"tab":"faq","idx":1},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-03","grade":"h1"},
{"id":"hist-h-k2-03#f2","kind":"faq","title":"의열단과 한인 애국단은 무엇이 달라요?","text":"의열단은 1919년 김원봉 등이 만주에서 조직했고 조선 혁명 선언을 지침으로 삼아 주로 식민 통치 기관을 공격했습니다. 한인 애국단은 1931년 김구가 임시 정부를 되살리려고 상하이에서 조직했고, 이봉창·윤봉길의 의거가 대표적입니다.","keywords":["의열단","한인 애국단"],"ref":{"tab":"faq","idx":2},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-03","grade":"h1"},
{"id":"hist-h-k2-03#m0","kind":"mistake","title":"자주 하는 실수","text":"물산 장려 운동과 민립 대학 설립 운동의 구호를 섞는 실수 — \"내 살림 내 것으로\"는 물산 장려 운동, \"한민족 1천만이 한 사람 1원씩\"은 민립 대학 설립 운동입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-03","grade":"h1"},
{"id":"hist-h-k2-03#m1","kind":"mistake","title":"자주 하는 실수","text":"봉오동 전투와 청산리 전투의 지휘관을 섞는 실수 — 봉오동은 홍범도 중심, 청산리는 김좌진의 북로 군정서와 홍범도 부대 등이 함께 싸웠습니다.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-03","grade":"h1"},
{"id":"hist-h-k2-03#m2","kind":"mistake","title":"자주 하는 실수","text":"의열단원과 한인 애국단원을 섞는 실수 — 나석주·김상옥은 의열단, 이봉창·윤봉길은 한인 애국단입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-03","grade":"h1"},
{"id":"hist-h-k2-04","kind":"unit","title":"식민지 사회·문화와 대중운동","text":"일제 강점기에 도시와 일상이 어떻게 달라졌는지, 농민·노동자·여성 등의 대중운동과 민족 문화 지키기를 알아봅니다. 식민지 도시화와 일상생활의 변화를 근대 교통·대중문화·소비 생활을 중심으로 설명할 수 있다. 일제의 식민지 교육 정책과 이에 맞선 민족 교육 운동을 비교할 수 있다. 농민·노동·청년·학생·여성·형평 운동이 일어난 배경과 전개를 설명할 수 있다…","keywords":["토막민","브나로드 운동","소작 쟁의","원산 총파업","근우회","형평 운동","조선어 학회","식민 사관","진단 학회"],"ref":{"tab":"concepts","idx":0},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-04","grade":"h1"},
{"id":"hist-h-k2-04#c0","kind":"concept","title":"도시화와 일상생활의 변화","text":"일제 강점기에는 철도와 항구를 중심으로 도시가 커졌습니다. 그러나 이 도시화는 한국인의 필요보다 식민 지배와 수탈의 필요에 따라 이루어졌습니다. 철도·항구 도시: 철도가 지나는 대전 같은 곳이 새 도시로 성장했고, 군산·목포처럼 쌀을 일본으로 실어 내는 항구 도시가 커졌습니다. 1930","keywords":["토막민"],"ref":{"tab":"concepts","idx":0},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-04","grade":"h1"},
{"id":"hist-h-k2-04#c1","kind":"concept","title":"식민지 교육 정책과 민족 교육 운동","text":"일제는 한국인을 일본에 순종하는 사람으로 만들려고 교육을 이용했습니다. 조선 교육령은 통치 방식에 따라 여러 번 바뀌었습니다. 시기 · 교육 정책 1910년대 · 제1차 조선 교육령(1911년): 보통학교 4년, 일본어·실업 교육 중심. 사립 학교와 서당을 규칙으로 통제 1920년대 ·","keywords":[],"ref":{"tab":"concepts","idx":1},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-04","grade":"h1"},
{"id":"hist-h-k2-04#c2","kind":"concept","title":"농민 운동과 노동 운동","text":"3·1 운동 뒤 농민과 노동자의 의식이 성장하고 사회주의 사상이 퍼지면서, 자신의 권리를 지키려는 대중운동이 활발해졌습니다. 농민 운동 — 소작 쟁의 토지 조사 사업과 산미 증식 계획을 거치며 소작농이 늘고 소작료 부담이 무거워졌습니다. 농민들은 소작료 인하와 소작권 이전 반대를 요구하","keywords":["소작 쟁의","원산 총파업"],"ref":{"tab":"concepts","idx":2},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-04","grade":"h1"},
{"id":"hist-h-k2-04#c3","kind":"concept","title":"청년·학생·여성 운동과 형평 운동","text":"1920년대에는 사회에서 차별받던 여러 집단이 스스로 권리를 외치기 시작했습니다. 청년 운동: 곳곳에 청년 단체가 생겨 강연회·야학 등 계몽 활동을 벌였고, 1924년 조선 청년 총동맹으로 힘을 모았습니다. 학생 운동: 학생들은 식민지 차별 교육에 맞서 동맹 휴학을 벌였고, 6·10 만","keywords":["근우회","형평 운동"],"ref":{"tab":"concepts","idx":3},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-04","grade":"h1"},
{"id":"hist-h-k2-04#c4","kind":"concept","title":"한글을 지킨 사람들 — 조선어 학회","text":"말과 글은 민족의 정신을 담는 그릇입니다. 일제가 일본어를 ‘국어’로 강요할수록 우리말을 지키려는 노력도 커졌습니다. 조선어 연구회(1921년): 주시경의 제자들이 만들었습니다. 한글을 기념하는 가갸날을 정하고(1926년, 뒤에 ‘한글날’로 이름을 바꿈), 잡지 「한글」을 펴냈습니다. ","keywords":["조선어 학회"],"ref":{"tab":"concepts","idx":4},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-04","grade":"h1"},
{"id":"hist-h-k2-04#c5","kind":"concept","title":"한국사 연구와 문학·예술 활동","text":"일제는 조선사 편수회를 두고, 한국사는 스스로 발전하지 못했다(정체성론)거나 늘 외세에 끌려다녔다(타율성론)는 식민 사관을 퍼뜨렸습니다. 이에 맞서 우리 역사를 바르게 밝히려는 연구가 이어졌습니다. 흐름 · 대표 인물 · 특징 민족주의 사학 · 박은식, 신채호, 정인보 · 민족의 정신을","keywords":["식민 사관","진단 학회"],"ref":{"tab":"concepts","idx":5},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-04","grade":"h1"},
{"id":"hist-h-k2-04#t0","kind":"term","title":"토막민","text":"농촌에서 밀려나 도시 변두리에 움막(토막)을 짓고 살던 도시 빈민입니다.","keywords":["토막민"],"ref":{"tab":"terms","idx":0},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-04","grade":"h1"},
{"id":"hist-h-k2-04#t1","kind":"term","title":"브나로드 운동","text":"‘민중 속으로’라는 뜻으로, 1930년대 초 동아일보가 주도하여 학생들이 농촌에서 한글을 가르친 문맹 퇴치 운동입니다.","keywords":["브나로드 운동"],"ref":{"tab":"terms","idx":1},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-04","grade":"h1"},
{"id":"hist-h-k2-04#t2","kind":"term","title":"소작 쟁의","text":"소작농이 소작료 인하, 소작권 이전 반대 등을 요구하며 지주에 맞선 농민 운동입니다. 암태도 소작 쟁의가 대표적입니다.","keywords":["소작 쟁의"],"ref":{"tab":"terms","idx":2},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-04","grade":"h1"},
{"id":"hist-h-k2-04#t3","kind":"term","title":"원산 총파업","text":"1929년 원산 지역 노동자들이 함께 벌인 총파업으로, 1920년대 최대 규모의 노동 쟁의입니다.","keywords":["원산 총파업"],"ref":{"tab":"terms","idx":3},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-04","grade":"h1"},
{"id":"hist-h-k2-04#t4","kind":"term","title":"근우회","text":"1927년 신간회의 자매단체로 만들어진 여성 단체입니다. 여성 차별 철폐와 여성 노동자 권익 보호를 주장했습니다.","keywords":["근우회"],"ref":{"tab":"terms","idx":4},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-04","grade":"h1"},
{"id":"hist-h-k2-04#t5","kind":"term","title":"형평 운동","text":"1923년 진주에서 조선 형평사가 만들어지며 시작된, 백정에 대한 차별을 없애려는 운동입니다.","keywords":["형평 운동"],"ref":{"tab":"terms","idx":5},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-04","grade":"h1"},
{"id":"hist-h-k2-04#t6","kind":"term","title":"조선어 학회","text":"1931년 조선어 연구회를 고쳐 만든 단체로, 한글 맞춤법 통일안과 표준어를 정하고 우리말 사전 편찬을 추진했습니다.","keywords":["조선어 학회"],"ref":{"tab":"terms","idx":6},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-04","grade":"h1"},
{"id":"hist-h-k2-04#t7","kind":"term","title":"식민 사관","text":"일제가 식민 지배를 정당화하려고 만든 역사관입니다. 정체성론·타율성론 등이 있습니다.","keywords":["식민 사관"],"ref":{"tab":"terms","idx":7},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-04","grade":"h1"},
{"id":"hist-h-k2-04#t8","kind":"term","title":"진단 학회","text":"1934년 이병도·손진태 등이 만든 학회로, 문헌 고증을 중시한 실증 사학을 이끌었습니다.","keywords":["진단 학회"],"ref":{"tab":"terms","idx":8},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-04","grade":"h1"},
{"id":"hist-h-k2-04#f0","kind":"faq","title":"일제 강점기에도 백화점이나 라디오가 있었으면 생활이 좋아진 것 아닌가요?","text":"새로운 문물이 들어온 것은 사실이지만, 그 혜택을 누린 사람은 도시의 일본인과 일부 계층이었습니다. 철도와 항구는 쌀과 자원을 실어 내는 데 쓰였고, 많은 한국인은 소작농·저임금 노동자·토막민으로 어렵게 살았습니다. 무엇이 생겼는지와 누가 누렸는지를 함께 보아야 합니다.","keywords":[],"ref":{"tab":"faq","idx":0},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-04","grade":"h1"},
{"id":"hist-h-k2-04#f1","kind":"faq","title":"형평 운동의 ‘형평’은 무슨 뜻이에요?","text":"‘형평’은 저울대처럼 한쪽으로 기울지 않고 고르다는 뜻입니다. 신분제가 법적으로 없어진 뒤에도 차별받던 백정들이 1923년 진주에서 조선 형평사를 만들어, 모든 사람이 평등하게 대우받는 사회를 요구했습니다.","keywords":["형평 운동"],"ref":{"tab":"faq","idx":1},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-04","grade":"h1"},
{"id":"hist-h-k2-04#f2","kind":"faq","title":"조선어 연구회와 조선어 학회는 같은 단체예요?","text":"같은 흐름의 단체입니다. 1921년 만들어진 조선어 연구회가 1931년 조선어 학회로 이름을 바꾸어 개편되었습니다. 가갸날 제정(1926년)은 조선어 연구회, 한글 맞춤법 통일안(1933년)과 표준어 제정(1936년)은 조선어 학회 때의 일입니다. 광복 뒤에는 한글 학회로 이름이 바뀌었습니다.","keywords":["조선어 학회"],"ref":{"tab":"faq","idx":2},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-04","grade":"h1"},
{"id":"hist-h-k2-04#m0","kind":"mistake","title":"자주 하는 실수","text":"문자 보급 운동과 브나로드 운동을 섞는 실수 — 문자 보급 운동은 조선일보(\"아는 것이 힘, 배워야 산다\"), 브나로드 운동은 동아일보(\"민중 속으로\")입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-04","grade":"h1"},
{"id":"hist-h-k2-04#m1","kind":"mistake","title":"자주 하는 실수","text":"형평 운동을 농민 운동으로 착각하는 실수 — 형평 운동은 백정에 대한 신분 차별을 없애려는 사회 운동입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-04","grade":"h1"},
{"id":"hist-h-k2-04#m2","kind":"mistake","title":"자주 하는 실수","text":"역사학자의 흐름을 섞는 실수 — 박은식·신채호는 민족주의 사학, 백남운은 사회 경제 사학, 진단 학회(이병도·손진태)는 실증 사학입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-04","grade":"h1"},
{"id":"hist-h-k2-05","kind":"unit","title":"독립 국가 건설을 위한 노력","text":"일제가 침략 전쟁을 넓혀 간 시기에 국내외 독립운동 세력이 힘을 모아 광복과 새 나라를 준비한 과정을 분석합니다. 만주 사변·중일 전쟁·태평양 전쟁으로 이어진 일제의 침략 전쟁 확대 과정을 설명할 수 있습니다. 1930년대 한중 연합 작전과 민족 혁명당·조선 의용대 등 독립운동 세력의 통합 노력을 파악할 수 있습니다. 한국광복군의 활동과 대한민국 건국 강…","keywords":["만주 사변","한중 연합 작전","민족 혁명당","조선 의용대","한국광복군","대한민국 건국 강령","삼균주의","조선 독립 동맹","조선 건국 동맹","카이로 선언"],"ref":{"tab":"concepts","idx":0},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-05","grade":"h1"},
{"id":"hist-h-k2-05#c0","kind":"concept","title":"일제의 침략 전쟁 확대","text":"1929년 세계 대공황으로 경제 위기에 빠진 일본은 대륙 침략으로 위기를 벗어나려 했습니다. 침략은 세 단계로 넓어졌습니다. 연도 · 사건 · 내용 1931년 · 만주 사변 · 만주를 침략하고 이듬해(1932년) 만주국을 세움 1937년 · 중일 전쟁 · 중국 본토로 침략을 넓힘 194","keywords":["만주 사변"],"ref":{"tab":"concepts","idx":0},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-05","grade":"h1"},
{"id":"hist-h-k2-05#c1","kind":"concept","title":"1930년대 만주의 한중 연합 작전","text":"만주 사변 뒤 만주의 중국인들 사이에서도 일본에 대한 반감이 커졌습니다. 그러자 한국 독립군과 중국군이 손잡고 함께 싸우는 한중 연합 작전이 펼쳐졌습니다. 부대 · 지휘 · 함께한 중국군 · 대표 전투 한국 독립군 · 지청천 · 중국 호로군 · 쌍성보 전투, 대전자령 전투 조선 혁명군 ","keywords":["만주 사변","한중 연합 작전"],"ref":{"tab":"concepts","idx":1},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-05","grade":"h1"},
{"id":"hist-h-k2-05#c2","kind":"concept","title":"중국 관내의 통합 노력: 민족 혁명당과 조선 의용대","text":"1932년 윤봉길 의거 뒤 중국 국민당 정부는 한국 독립운동을 적극 돕기 시작했습니다. 중국 관내(만리장성 남쪽)의 독립운동가들은 흩어진 힘을 하나로 모으려 했습니다. 민족 혁명당(1935년): 김원봉의 의열단, 한국 독립당, 조선 혁명당 등 여러 단체가 모여 만든 정당입니다. 김구 등","keywords":["민족 혁명당","조선 의용대"],"ref":{"tab":"concepts","idx":2},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-05","grade":"h1"},
{"id":"hist-h-k2-05#c3","kind":"concept","title":"대한민국 임시 정부와 한국광복군, 대한민국 건국 강령","text":"윤봉길 의거 뒤 일제의 추격을 피해 여러 곳을 옮겨 다니던 대한민국 임시 정부는 1940년 충칭에 자리 잡고 체제를 정비했습니다. 김구가 주석을 맡아 이끌었습니다. 한국광복군 창설(1940년): 지청천을 총사령관으로 하는 임시 정부의 정식 군대입니다. 1942년 김원봉이 이끄는 조선 의","keywords":["조선 의용대","한국광복군","대한민국 건국 강령"],"ref":{"tab":"concepts","idx":3},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-05","grade":"h1"},
{"id":"hist-h-k2-05#c4","kind":"concept","title":"조선 독립 동맹과 조선 건국 동맹","text":"광복을 준비한 것은 임시 정부만이 아니었습니다. 단체 · 결성 · 중심인물 · 특징 조선 독립 동맹 · 1942년, 화북 지방 · 김두봉 · 사회주의 계열. 조선 의용군을 두고 중국 공산당군과 함께 항일전 조선 건국 동맹 · 1944년, 국내 · 여운형 · 비밀 결사. 좌우를 아우르고 ","keywords":["조선 의용대","조선 독립 동맹","조선 건국 동맹"],"ref":{"tab":"concepts","idx":4},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-05","grade":"h1"},
{"id":"hist-h-k2-05#c5","kind":"concept","title":"국제 사회의 한국 독립 약속","text":"제2차 세계 대전에서 연합국이 승기를 잡자, 전쟁 뒤의 세계를 논의하는 회담이 열렸습니다. 카이로 선언(1943년 11월): 미국·영국·중국 정상이 모여 \"적당한 절차를 거쳐\" 한국을 자유롭고 독립된 나라로 만들기로 했습니다. 국제 사회가 처음으로 한국의 독립을 약속한 것입니다. 얄타 ","keywords":["카이로 선언"],"ref":{"tab":"concepts","idx":5},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-05","grade":"h1"},
{"id":"hist-h-k2-05#t0","kind":"term","title":"만주 사변","text":"1931년 일본이 만주를 침략한 사건입니다. 일본은 이듬해 만주국을 세웠습니다.","keywords":["만주 사변"],"ref":{"tab":"terms","idx":0},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-05","grade":"h1"},
{"id":"hist-h-k2-05#t1","kind":"term","title":"한중 연합 작전","text":"1930년대 초 만주에서 한국 독립군·조선 혁명군이 중국군과 함께 일본군에 맞서 싸운 작전입니다.","keywords":["한중 연합 작전"],"ref":{"tab":"terms","idx":1},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-05","grade":"h1"},
{"id":"hist-h-k2-05#t2","kind":"term","title":"민족 혁명당","text":"1935년 중국 관내의 의열단·한국 독립당·조선 혁명당 등이 모여 만든 정당입니다. 김원봉이 중심이 되었습니다.","keywords":["민족 혁명당"],"ref":{"tab":"terms","idx":2},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-05","grade":"h1"},
{"id":"hist-h-k2-05#t3","kind":"term","title":"조선 의용대","text":"1938년 김원봉 등이 중국 한커우에서 만든 중국 관내 최초의 한인 무장 부대입니다.","keywords":["조선 의용대"],"ref":{"tab":"terms","idx":3},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-05","grade":"h1"},
{"id":"hist-h-k2-05#t4","kind":"term","title":"한국광복군","text":"1940년 충칭의 대한민국 임시 정부가 만든 정식 군대입니다. 총사령관은 지청천입니다.","keywords":["한국광복군"],"ref":{"tab":"terms","idx":4},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-05","grade":"h1"},
{"id":"hist-h-k2-05#t5","kind":"term","title":"대한민국 건국 강령","text":"1941년 임시 정부가 광복 뒤 세울 나라의 모습을 밝힌 문서입니다. 삼균주의를 바탕으로 합니다.","keywords":["대한민국 건국 강령"],"ref":{"tab":"terms","idx":5},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-05","grade":"h1"},
{"id":"hist-h-k2-05#t6","kind":"term","title":"삼균주의","text":"조소앙이 내세운 사상으로, 정치·경제·교육을 고르게 나누어 균등한 사회를 만들자는 생각입니다.","keywords":["삼균주의"],"ref":{"tab":"terms","idx":6},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-05","grade":"h1"},
{"id":"hist-h-k2-05#t7","kind":"term","title":"조선 독립 동맹","text":"1942년 화북에서 김두봉 등 사회주의 계열 독립운동가가 만든 단체입니다. 조선 의용군을 두었습니다.","keywords":["조선 독립 동맹"],"ref":{"tab":"terms","idx":7},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-05","grade":"h1"},
{"id":"hist-h-k2-05#t8","kind":"term","title":"조선 건국 동맹","text":"1944년 여운형이 국내에서 비밀리에 만든 건국 준비 단체입니다.","keywords":["조선 건국 동맹"],"ref":{"tab":"terms","idx":8},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-05","grade":"h1"},
{"id":"hist-h-k2-05#t9","kind":"term","title":"카이로 선언","text":"1943년 미국·영국·중국 정상이 한국의 독립을 처음으로 약속한 선언입니다.","keywords":["카이로 선언"],"ref":{"tab":"terms","idx":9},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-05","grade":"h1"},
{"id":"hist-h-k2-05#f0","kind":"faq","title":"조선 의용대랑 조선 의용군은 다른 건가요?","text":"다릅니다. 조선 의용대는 1938년 김원봉 등이 중국 한커우에서 만든 부대입니다. 그 뒤 많은 대원이 화북으로 옮겨 가 조선 독립 동맹 아래에서 조선 의용군으로 다시 짜였고, 김원봉과 남은 대원은 한국광복군에 합류했습니다.","keywords":["조선 의용대"],"ref":{"tab":"faq","idx":0},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-05","grade":"h1"},
{"id":"hist-h-k2-05#f1","kind":"faq","title":"한국 독립군, 한국광복군, 한국 독립당 이름이 너무 헷갈려요.","text":"시기와 장소로 나누면 쉽습니다. 한국 독립군은 1930년대 초 만주에서 지청천이 이끈 부대, 한국광복군은 1940년 충칭의 임시 정부가 만든 군대입니다. 한국 독립당은 군대가 아니라 정당으로, 1940년 김구 중심으로 새로 만들어져 임시 정부를 뒷받침했습니다.","keywords":["한국광복군"],"ref":{"tab":"faq","idx":1},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-05","grade":"h1"},
{"id":"hist-h-k2-05#f2","kind":"faq","title":"카이로 선언이 있었는데 왜 바로 독립하지 못했나요?","text":"카이로 선언에는 \"적당한 절차를 거쳐\"라는 단서가 붙어 있었습니다. 강대국들은 한국을 곧바로 독립시키기보다 일정 기간 관리하는 방안도 생각하고 있었고, 이는 광복 뒤 신탁 통치 논의로 이어졌습니다.","keywords":["카이로 선언"],"ref":{"tab":"faq","idx":2},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-05","grade":"h1"},
{"id":"hist-h-k2-05#m0","kind":"mistake","title":"자주 하는 실수","text":"지청천(한국 독립군)과 양세봉(조선 혁명군)을 바꾸어 기억하는 실수 — \"지청천은 쌍성보·대전자령, 양세봉은 영릉가·흥경성\"으로 짝지어 둡니다.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-05","grade":"h1"},
{"id":"hist-h-k2-05#m1","kind":"mistake","title":"자주 하는 실수","text":"조선 독립 동맹(1942년, 화북, 김두봉)과 조선 건국 동맹(1944년, 국내, 여운형)을 섞는 실수 — \"건국 동맹은 국내\"로 구별합니다.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-05","grade":"h1"},
{"id":"hist-h-k2-05#m2","kind":"mistake","title":"자주 하는 실수","text":"카이로 선언에 소련이 참여했다고 생각하는 실수 — 카이로는 미국·영국·중국, 얄타는 미국·영국·소련입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-05","grade":"h1"},
{"id":"hist-h-k2-06","kind":"unit","title":"광복과 대한민국 정부 수립","text":"광복 뒤 냉전 속에서 분단이 시작된 과정과 통일 정부 수립 노력, 자유민주주의에 기초한 정부 수립 과정을 탐색합니다. 광복 직후 38도선 분할과 미소 군정이 시작된 과정을 설명할 수 있습니다. 모스크바 3국 외상 회의 이후의 좌우 대립과 통일 정부 수립 노력을 파악할 수 있습니다. 5·10 총선거와 제헌 헌법을 거쳐 대한민국 정부가 수립된 과정과 그 의미…","keywords":["조선 건국 준비 위원회","미군정","모스크바 3국 외상 회의","신탁 통치","좌우 합작 운동","남북 협상","5·10 총선거","제헌 헌법","반민특위","농지 개혁"],"ref":{"tab":"concepts","idx":0},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-06","grade":"h1"},
{"id":"hist-h-k2-06#c0","kind":"concept","title":"8·15 광복과 38도선, 미소 군정","text":"1945년 8월 15일 일본이 항복하면서 우리 민족은 광복을 맞았습니다. 여운형은 조선 건국 동맹을 바탕으로 곧바로 조선 건국 준비 위원회를 만들어 치안을 맡고 새 나라를 준비했습니다. 그러나 한반도에는 일본군의 무장 해제를 명분으로 북위 38도선을 경계로 남쪽에는 미군, 북쪽에는 소련","keywords":["조선 건국 준비 위원회","미군정"],"ref":{"tab":"concepts","idx":0},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-06","grade":"h1"},
{"id":"hist-h-k2-06#c1","kind":"concept","title":"모스크바 3국 외상 회의와 좌우 대립","text":"1945년 12월 미국·영국·소련의 외무 장관이 모스크바에 모여 한반도 문제를 논의했습니다(모스크바 3국 외상 회의). 한국에 임시 민주 정부를 세운다. 이를 돕기 위해 미소 공동 위원회를 연다. 미국·영국·중국·소련이 최고 5년 동안 신탁 통치하는 방안을 협의한다. 신탁 통치 소식이 ","keywords":["모스크바 3국 외상 회의","신탁 통치"],"ref":{"tab":"concepts","idx":1},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-06","grade":"h1"},
{"id":"hist-h-k2-06#c2","kind":"concept","title":"통일 정부를 세우려는 노력과 유엔의 결의","text":"분단을 막고 통일 정부를 세우려는 노력도 이어졌습니다. 좌우 합작 운동(1946년): 중도 세력인 여운형(중도 좌파)과 김규식(중도 우파)이 좌우 합작 위원회를 만들고 좌우 합작 7원칙을 발표했습니다. 미군정도 처음에는 지원했지만 좌우 양쪽의 반발, 제2차 미소 공동 위원회의 결렬, 1","keywords":["미군정","좌우 합작 운동","남북 협상"],"ref":{"tab":"concepts","idx":2},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-06","grade":"h1"},
{"id":"hist-h-k2-06#c3","kind":"concept","title":"5·10 총선거와 제헌 헌법, 대한민국 정부 수립","text":"1948년 5월 10일 5·10 총선거가 치러졌습니다. 만 21세 이상의 모든 남녀가 투표한 우리 역사상 첫 민주적 보통 선거였습니다. 다만 남북 협상에 참여한 김구·김규식 등과 좌익 세력은 선거에 참여하지 않았고, 제주도의 두 선거구에서는 선거가 제대로 치러지지 못했습니다. 선거로 뽑","keywords":["남북 협상","5·10 총선거","제헌 헌법"],"ref":{"tab":"concepts","idx":3},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-06","grade":"h1"},
{"id":"hist-h-k2-06#c4","kind":"concept","title":"정부 수립 과정의 갈등과 희생","text":"정부가 세워지는 과정에서 큰 갈등과 희생도 있었습니다. 제주 4·3 사건(1948년): 1947년 3·1절 기념 대회에서 경찰의 발포로 주민이 희생되며 갈등이 커졌습니다. 1948년 4월 3일 남조선 노동당 제주도당 세력이 단독 선거 반대 등을 내세우며 무장봉기했고, 이를 진압하는 과정","keywords":[],"ref":{"tab":"concepts","idx":4},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-06","grade":"h1"},
{"id":"hist-h-k2-06#c5","kind":"concept","title":"친일파 청산 노력과 농지 개혁","text":"새 정부의 큰 과제는 일제 잔재를 청산하고 농민의 삶을 안정시키는 것이었습니다. 친일파 청산: 제헌 국회는 1948년 9월 반민족 행위 처벌법을 만들고, 반민족 행위 특별 조사 위원회(반민특위)를 구성했습니다. 그러나 반공을 앞세운 이승만 정부가 소극적이었고, 경찰이 반민특위를 습격하는","keywords":["반민특위","농지 개혁"],"ref":{"tab":"concepts","idx":5},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-06","grade":"h1"},
{"id":"hist-h-k2-06#t0","kind":"term","title":"조선 건국 준비 위원회","text":"광복 직후 여운형 등이 조선 건국 동맹을 바탕으로 만든 단체입니다. 치안을 맡고 새 나라를 준비했습니다.","keywords":["조선 건국 준비 위원회"],"ref":{"tab":"terms","idx":0},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-06","grade":"h1"},
{"id":"hist-h-k2-06#t1","kind":"term","title":"미군정","text":"광복 뒤 38도선 남쪽에서 미군이 군정청을 세워 직접 통치한 것입니다(1945~1948년).","keywords":["미군정"],"ref":{"tab":"terms","idx":1},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-06","grade":"h1"},
{"id":"hist-h-k2-06#t2","kind":"term","title":"모스크바 3국 외상 회의","text":"1945년 12월 미국·영국·소련 외무 장관이 한국에 임시 민주 정부 수립, 미소 공동 위원회 설치, 신탁 통치 협의를 결정한 회의입니다.","keywords":["모스크바 3국 외상 회의"],"ref":{"tab":"terms","idx":2},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-06","grade":"h1"},
{"id":"hist-h-k2-06#t3","kind":"term","title":"신탁 통치","text":"스스로 정부를 운영할 준비가 덜 되었다고 보는 지역을 다른 나라들이 일정 기간 대신 관리하는 것입니다.","keywords":["신탁 통치"],"ref":{"tab":"terms","idx":3},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-06","grade":"h1"},
{"id":"hist-h-k2-06#t4","kind":"term","title":"좌우 합작 운동","text":"1946년 여운형·김규식 등 중도 세력이 좌익과 우익을 합쳐 통일 정부를 세우려 한 운동입니다.","keywords":["좌우 합작 운동"],"ref":{"tab":"terms","idx":4},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-06","grade":"h1"},
{"id":"hist-h-k2-06#t5","kind":"term","title":"남북 협상","text":"1948년 4월 김구·김규식이 평양에서 북측 지도자들과 만나 단독 정부 수립에 반대한 회담입니다.","keywords":["남북 협상"],"ref":{"tab":"terms","idx":5},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-06","grade":"h1"},
{"id":"hist-h-k2-06#t6","kind":"term","title":"5·10 총선거","text":"1948년 5월 10일 치러진 우리 역사상 첫 민주적 보통 선거입니다. 제헌 국회의원을 뽑았습니다.","keywords":["5·10 총선거"],"ref":{"tab":"terms","idx":6},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-06","grade":"h1"},
{"id":"hist-h-k2-06#t7","kind":"term","title":"제헌 헌법","text":"1948년 7월 17일 제헌 국회가 공포한 대한민국의 첫 헌법입니다. 대한민국이 민주 공화국임을 밝혔습니다.","keywords":["제헌 헌법"],"ref":{"tab":"terms","idx":7},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-06","grade":"h1"},
{"id":"hist-h-k2-06#t8","kind":"term","title":"반민특위","text":"반민족 행위 특별 조사 위원회의 줄임말입니다. 1948년 친일 반민족 행위자를 조사·처벌하려고 국회에 만든 기구입니다.","keywords":["반민특위"],"ref":{"tab":"terms","idx":8},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-06","grade":"h1"},
{"id":"hist-h-k2-06#t9","kind":"term","title":"농지 개혁","text":"1949년 법을 만들어 1950년부터 시행한 개혁으로, 유상 매수·유상 분배 방식으로 농민에게 농지를 나누어 주었습니다.","keywords":["농지 개혁"],"ref":{"tab":"terms","idx":9},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-06","grade":"h1"},
{"id":"hist-h-k2-06#f0","kind":"faq","title":"38도선은 왜 하필 그곳에 그어졌나요?","text":"1945년 8월 소련군이 빠르게 한반도로 내려오자, 미국은 일본군의 무장 해제를 나누어 맡자며 북위 38도선을 경계로 제안했고 소련이 받아들였습니다. 처음에는 군사적 편의를 위한 선이었지만, 냉전이 깊어지며 분단선으로 굳어졌습니다.","keywords":[],"ref":{"tab":"faq","idx":0},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-06","grade":"h1"},
{"id":"hist-h-k2-06#f1","kind":"faq","title":"신탁 통치를 왜 그렇게 반대했나요?","text":"막 식민 지배에서 벗어난 사람들에게 다른 나라가 몇 년 동안 대신 다스린다는 말은 \"또 다른 지배\"로 들렸습니다. 그래서 우익을 중심으로 거센 반탁 운동이 일어났습니다. 반면 좌익은 결정의 핵심이 임시 정부 수립이라고 보고 지지했고, 이 차이가 좌우 대립을 키웠습니다.","keywords":["신탁 통치"],"ref":{"tab":"faq","idx":1},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-06","grade":"h1"},
{"id":"hist-h-k2-06#f2","kind":"faq","title":"좌우 합작 운동과 남북 협상은 어떻게 달라요?","text":"좌우 합작 운동(1946년)은 남한 안의 좌익과 우익을 합치려는 운동으로 여운형·김규식이 이끌었습니다. 남북 협상(1948년)은 남과 북의 지도자가 만나 단독 정부 수립을 막으려 한 회담으로 김구·김규식이 참여했습니다. 김규식은 두 운동 모두에 참여했습니다.","keywords":["좌우 합작 운동","남북 협상"],"ref":{"tab":"faq","idx":2},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-06","grade":"h1"},
{"id":"hist-h-k2-06#m0","kind":"mistake","title":"자주 하는 실수","text":"모스크바 3국 외상 회의(1945년, 신탁 통치 협의)와 유엔 총회 결의(1947년, 남북한 총선거)를 섞는 실수 — 회의의 이름과 연도를 함께 기억합니다.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-06","grade":"h1"},
{"id":"hist-h-k2-06#m1","kind":"mistake","title":"자주 하는 실수","text":"남한의 농지 개혁을 무상 분배로 아는 실수 — 남한은 유상 매수·유상 분배, 북한은 무상 몰수·무상 분배입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-06","grade":"h1"},
{"id":"hist-h-k2-06#m2","kind":"mistake","title":"자주 하는 실수","text":"제헌 헌법에서 대통령을 국민이 직접 뽑았다고 생각하는 실수 — 제헌 헌법에서는 국회가 대통령을 뽑았습니다.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-06","grade":"h1"},
{"id":"hist-h-k2-07","kind":"unit","title":"6·25 전쟁과 분단의 고착화","text":"북한의 남침으로 시작된 6·25 전쟁의 전개와 피해, 전쟁 뒤 분단이 굳어진 과정을 국내외 정세와 함께 이해합니다. 6·25 전쟁의 배경과 북한의 남침 과정을 설명할 수 있습니다. 유엔군 참전부터 정전 협정까지 전쟁의 전개 과정을 순서대로 정리할 수 있습니다. 6·25 전쟁의 국제적 성격과 한미 상호 방위 조약의 의미를 파악할 수 있습니다. 전쟁의 피해와…","keywords":["애치슨 선언","유엔군","인천 상륙 작전","1·4 후퇴","정전 협정","군사 분계선","비무장 지대(DMZ)","반공 포로 석방","한미 상호 방위 조약","이산가족"],"ref":{"tab":"concepts","idx":0},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-07","grade":"h1"},
{"id":"hist-h-k2-07#c0","kind":"concept","title":"전쟁의 배경과 북한의 남침","text":"1948년 남과 북에 각각 정부가 세워진 뒤, 38도선 부근에서는 크고 작은 무력 충돌이 자주 일어났습니다. 북한: 소련의 지원으로 군사력을 키웠고, 중국 국공 내전에 참여했던 조선 의용군 출신 병력도 북한군에 들어왔습니다. 김일성은 소련과 중국의 동의와 지원 약속을 얻어 전쟁을 준비했","keywords":["애치슨 선언"],"ref":{"tab":"concepts","idx":0},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-07","grade":"h1"},
{"id":"hist-h-k2-07#c1","kind":"concept","title":"전쟁의 전개 ①: 유엔군 참전과 인천 상륙 작전","text":"북한의 남침에 맞서 유엔 안전 보장 이사회는 북한의 행동을 침략으로 규정하고 유엔군 파견을 결정했습니다. 미국을 비롯한 16개국이 전투 부대를, 여러 나라가 의료 지원을 보냈습니다. 국군과 유엔군은 낙동강 방어선까지 밀렸지만 끝까지 버텼습니다(1950년 8월). 인천 상륙 작전(1950","keywords":["유엔군","인천 상륙 작전"],"ref":{"tab":"concepts","idx":1},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-07","grade":"h1"},
{"id":"hist-h-k2-07#c2","kind":"concept","title":"전쟁의 전개 ②: 중국군 개입과 정전 협정","text":"압록강 근처까지 진격하던 국군과 유엔군 앞에 1950년 10월 중국군이 대규모로 개입했습니다. 국군과 유엔군은 다시 후퇴했고, 12월에는 많은 피란민과 함께 흥남 철수를 했습니다. 1·4 후퇴(1951년 1월 4일): 서울을 다시 내주었습니다. 3월에 서울을 되찾은 뒤 전선은 38도선 ","keywords":["유엔군","1·4 후퇴","정전 협정","군사 분계선"],"ref":{"tab":"concepts","idx":2},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-07","grade":"h1"},
{"id":"hist-h-k2-07#c3","kind":"concept","title":"6·25 전쟁의 국제적 성격과 한미 상호 방위 조약","text":"6·25 전쟁은 같은 민족이 맞서 싸운 전쟁이면서, 동시에 여러 나라가 참여한 국제전이었습니다. 남쪽을 도운 나라 · 북쪽을 도운 나라 미국을 중심으로 한 유엔군(16개국 전투 부대) · 중국(군대 파견), 소련(무기·물자 지원) 6·25 전쟁은 냉전이 시작된 뒤 처음으로 벌어진 대규모","keywords":["유엔군","정전 협정","한미 상호 방위 조약"],"ref":{"tab":"concepts","idx":3},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-07","grade":"h1"},
{"id":"hist-h-k2-07#c4","kind":"concept","title":"전쟁의 피해와 사람들의 삶","text":"3년 동안의 전쟁으로 남북한 모두 큰 피해를 입었습니다. 인명 피해: 군인과 민간인을 합쳐 수백만 명이 죽거나 다치거나 행방불명되었습니다. 전쟁 중에는 여러 곳에서 무고한 민간인이 희생되는 일도 있었습니다(노근리 사건, 거창 사건 등). 이산가족과 전쟁고아: 피란과 분단으로 많은 가족이","keywords":["이산가족"],"ref":{"tab":"concepts","idx":4},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-07","grade":"h1"},
{"id":"hist-h-k2-07#c5","kind":"concept","title":"전쟁 뒤 남북한의 체제 강화와 분단의 고착화","text":"전쟁이 끝난 뒤 남과 북은 서로를 적으로 여기며 각자의 권력을 굳혔습니다. · 남한 · 북한 권력 강화 · 이승만 정부가 반공을 내세워 반대 세력을 억누르고 장기 집권의 기반을 다짐(전쟁 중 1952년 발췌 개헌) · 김일성이 전쟁 책임을 물어 박헌영 등 남조선 노동당 계열을 숙청하고,","keywords":["군사 분계선"],"ref":{"tab":"concepts","idx":5},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-07","grade":"h1"},
{"id":"hist-h-k2-07#t0","kind":"term","title":"애치슨 선언","text":"1950년 1월 미국 국무 장관 애치슨이 미국의 태평양 방위선에서 한국을 뺀다고 발표한 것입니다.","keywords":["애치슨 선언"],"ref":{"tab":"terms","idx":0},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-07","grade":"h1"},
{"id":"hist-h-k2-07#t1","kind":"term","title":"유엔군","text":"유엔 안전 보장 이사회의 결정으로 6·25 전쟁에 참전한 여러 나라의 군대입니다. 16개국이 전투 부대를 보냈습니다.","keywords":["유엔군"],"ref":{"tab":"terms","idx":1},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-07","grade":"h1"},
{"id":"hist-h-k2-07#t2","kind":"term","title":"인천 상륙 작전","text":"1950년 9월 15일 유엔군이 인천에 상륙해 전세를 뒤집은 작전입니다.","keywords":["인천 상륙 작전"],"ref":{"tab":"terms","idx":2},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-07","grade":"h1"},
{"id":"hist-h-k2-07#t3","kind":"term","title":"1·4 후퇴","text":"중국군의 공세로 1951년 1월 4일 국군과 유엔군이 서울을 다시 내주고 물러난 일입니다.","keywords":["1·4 후퇴"],"ref":{"tab":"terms","idx":3},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-07","grade":"h1"},
{"id":"hist-h-k2-07#t4","kind":"term","title":"정전 협정","text":"1953년 7월 27일 맺어진, 전쟁을 멈추기로 한 협정입니다. 군사 분계선과 비무장 지대를 정했습니다.","keywords":["정전 협정"],"ref":{"tab":"terms","idx":4},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-07","grade":"h1"},
{"id":"hist-h-k2-07#t5","kind":"term","title":"군사 분계선","text":"정전 협정으로 정한 남북의 경계선입니다. 흔히 휴전선이라고 부릅니다.","keywords":["군사 분계선"],"ref":{"tab":"terms","idx":5},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-07","grade":"h1"},
{"id":"hist-h-k2-07#t6","kind":"term","title":"비무장 지대(DMZ)","text":"군사 분계선에서 남북으로 각각 2km씩, 군대와 무기를 두지 않기로 한 지역입니다.","keywords":["비무장 지대(DMZ)"],"ref":{"tab":"terms","idx":6},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-07","grade":"h1"},
{"id":"hist-h-k2-07#t7","kind":"term","title":"반공 포로 석방","text":"1953년 6월 정전에 반대한 이승만 정부가 북한으로 돌아가기를 거부한 포로들을 풀어 준 일입니다.","keywords":["반공 포로 석방"],"ref":{"tab":"terms","idx":7},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-07","grade":"h1"},
{"id":"hist-h-k2-07#t8","kind":"term","title":"한미 상호 방위 조약","text":"1953년 10월 한국과 미국이 맺은 군사 동맹 조약입니다. 미군이 한국에 머무를 근거가 되었습니다.","keywords":["한미 상호 방위 조약"],"ref":{"tab":"terms","idx":8},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-07","grade":"h1"},
{"id":"hist-h-k2-07#t9","kind":"term","title":"이산가족","text":"전쟁과 분단으로 남북으로 흩어져 서로 만나지 못하게 된 가족입니다.","keywords":["이산가족"],"ref":{"tab":"terms","idx":9},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-07","grade":"h1"},
{"id":"hist-h-k2-07#f0","kind":"faq","title":"휴전선이랑 38도선은 같은 선인가요?","text":"다릅니다. 38도선은 1945년 미국과 소련이 일본군의 무장 해제를 나누어 맡으려고 그은 위도선입니다. 휴전선(군사 분계선)은 1953년 정전 당시 양쪽 군대가 맞서 있던 전선을 바탕으로 정한 선이라 비스듬하게 그어져 있습니다.","keywords":[],"ref":{"tab":"faq","idx":0},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-07","grade":"h1"},
{"id":"hist-h-k2-07#f1","kind":"faq","title":"대한민국은 왜 정전 협정에 서명하지 않았나요?","text":"이승만 정부는 전쟁을 멈추면 분단이 굳어진다고 보고 북진 통일을 주장하며 정전에 반대했습니다. 반공 포로를 석방하기까지 했고, 결국 정전에 동의하는 대신 미국과 한미 상호 방위 조약을 맺었습니다.","keywords":["정전 협정"],"ref":{"tab":"faq","idx":1},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-07","grade":"h1"},
{"id":"hist-h-k2-07#f2","kind":"faq","title":"6·25 전쟁은 누가 일으킨 건가요?","text":"북한이 일으켰습니다. 북한은 소련과 중국의 동의와 지원 약속을 얻어 전쟁을 준비했고, 1950년 6월 25일 38도선 전역에서 기습 남침했습니다. 뒤에 공개된 옛 소련의 문서들도 이를 뒷받침합니다.","keywords":[],"ref":{"tab":"faq","idx":2},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-07","grade":"h1"},
{"id":"hist-h-k2-07#m0","kind":"mistake","title":"자주 하는 실수","text":"인천 상륙 작전과 중국군 개입의 순서를 바꾸는 실수 — 인천 상륙(1950년 9월)으로 북진했다가, 중국군 개입(1950년 10월)으로 다시 밀렸습니다.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-07","grade":"h1"},
{"id":"hist-h-k2-07#m1","kind":"mistake","title":"자주 하는 실수","text":"대한민국이 정전 협정에 서명했다고 생각하는 실수 — 서명한 쪽은 유엔군·북한군·중국군입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-07","grade":"h1"},
{"id":"hist-h-k2-07#m2","kind":"mistake","title":"자주 하는 실수","text":"정전 협정으로 전쟁이 완전히 끝났다고 생각하는 실수 — 정전은 싸움을 멈춘 것이고, 평화 조약은 맺어지지 않았습니다.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-07","grade":"h1"},
{"id":"hist-h-k2-08","kind":"unit","title":"4·19 혁명과 민주화 운동","text":"독재에 맞선 국민의 저항으로 민주주의가 시련을 딛고 발전해 온 과정을 4·19 혁명부터 6월 민주 항쟁까지 탐구합니다. 이승만 정부의 장기 집권 과정과 4·19 혁명의 원인·전개·의미를 설명할 수 있습니다. 장면 내각의 성격과 5·16 군사 정변, 박정희 정부의 유신 체제와 그에 맞선 운동을 파악할 수 있습니다. 신군부의 등장과 5·18 민주화 운동의 전…","keywords":["발췌 개헌","사사오입 개헌","3·15 부정 선거","4·19 혁명","장면 내각","5·16 군사 정변","유신 헌법","부마 민주 항쟁","5·18 민주화 운동","6월 민주 항쟁"],"ref":{"tab":"concepts","idx":0},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-08","grade":"h1"},
{"id":"hist-h-k2-08#c0","kind":"concept","title":"이승만 정부의 장기 집권","text":"이승만 정부는 헌법을 거듭 고치며 권력을 이어 갔습니다. 연도 · 사건 · 내용 1952년 · 발췌 개헌 · 국회에서 다시 뽑히기 어려워지자, 전쟁 중 부산에서 경찰과 군대를 동원해 대통령 직선제 개헌안을 통과시킴 1954년 · 사사오입 개헌 · 초대 대통령의 중임 제한을 없애는 개헌안","keywords":["발췌 개헌","사사오입 개헌"],"ref":{"tab":"concepts","idx":0},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-08","grade":"h1"},
{"id":"hist-h-k2-08#c1","kind":"concept","title":"4·19 혁명","text":"3·15 부정 선거에 맞선 학생과 시민의 저항은 혁명으로 커졌습니다. 2·28 대구 학생 시위(1960년 2월): 야당 선거 유세에 가지 못하게 일요일에 학생들을 등교시키자 고등학생들이 항의했습니다. 3·15 마산 시위: 선거 당일 부정 선거에 항의하는 시위가 일어났고, 경찰이 총을 쏘","keywords":["3·15 부정 선거","4·19 혁명"],"ref":{"tab":"concepts","idx":1},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-08","grade":"h1"},
{"id":"hist-h-k2-08#c2","kind":"concept","title":"장면 내각과 5·16 군사 정변","text":"1960년 7월 총선거에서 민주당이 크게 이기고, 국회는 윤보선을 대통령으로 뽑았습니다. 실제 권한은 국무총리 장면이 이끄는 내각에 있었습니다(장면 내각, 내각 책임제). 성과: 언론의 자유가 넓어지고, 지방 자치제를 전면 실시했으며, 경제 개발 계획을 세웠습니다. 한계: 민주당 안의 ","keywords":["장면 내각","5·16 군사 정변"],"ref":{"tab":"concepts","idx":2},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-08","grade":"h1"},
{"id":"hist-h-k2-08#c3","kind":"concept","title":"3선 개헌과 유신 체제, 유신 반대 운동","text":"박정희 대통령은 1967년 다시 당선된 뒤, 1969년 대통령이 세 번까지 연임할 수 있게 하는 3선 개헌을 했습니다. 1971년 대통령 선거에서 다시 당선되었지만 야당 후보와의 표 차이는 크지 않았습니다. 1972년 10월 박정희 정부는 비상계엄을 선포하고 국회를 해산한 뒤 유신 헌법","keywords":["유신 헌법"],"ref":{"tab":"concepts","idx":3},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-08","grade":"h1"},
{"id":"hist-h-k2-08#c4","kind":"concept","title":"신군부의 등장과 5·18 민주화 운동","text":"10·26 사태 뒤 많은 사람이 민주주의의 회복을 기대했습니다. 그러나 1979년 12월 12일 전두환·노태우 등 신군부가 군사 반란을 일으켜 군의 권력을 장악했습니다(12·12 사태). 1980년 봄 학생과 시민들은 유신 헌법 폐지와 계엄 해제를 요구했습니다(서울의 봄). 신군부는 5","keywords":["유신 헌법","5·18 민주화 운동"],"ref":{"tab":"concepts","idx":4},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-08","grade":"h1"},
{"id":"hist-h-k2-08#c5","kind":"concept","title":"6월 민주 항쟁과 대통령 직선제 개헌","text":"전두환 정부는 7년 단임의 대통령을 선거인단이 간접 선거로 뽑는 헌법 아래에서 출범했습니다. 언론을 통제하고 민주화 운동을 탄압하는 한편, 야간 통행금지 해제 같은 유화 정책도 폈습니다. 1985년 무렵부터 대통령 직선제 개헌을 요구하는 목소리가 커졌습니다. 1987년 1월 서울대학교 ","keywords":["6월 민주 항쟁"],"ref":{"tab":"concepts","idx":5},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-08","grade":"h1"},
{"id":"hist-h-k2-08#t0","kind":"term","title":"발췌 개헌","text":"1952년 6·25 전쟁 중 부산에서 이승만 정부가 대통령 직선제를 담아 강압적으로 통과시킨 개헌입니다.","keywords":["발췌 개헌"],"ref":{"tab":"terms","idx":0},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-08","grade":"h1"},
{"id":"hist-h-k2-08#t1","kind":"term","title":"사사오입 개헌","text":"1954년 초대 대통령의 중임 제한을 없애는 개헌안을 반올림(사사오입) 논리로 통과시킨 개헌입니다.","keywords":["사사오입 개헌"],"ref":{"tab":"terms","idx":1},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-08","grade":"h1"},
{"id":"hist-h-k2-08#t2","kind":"term","title":"3·15 부정 선거","text":"1960년 3월 15일 정·부통령 선거에서 이승만 정부가 저지른 대규모 부정 선거입니다.","keywords":["3·15 부정 선거"],"ref":{"tab":"terms","idx":2},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-08","grade":"h1"},
{"id":"hist-h-k2-08#t3","kind":"term","title":"4·19 혁명","text":"1960년 3·15 부정 선거에 맞서 학생과 시민이 일어나 이승만 정부를 무너뜨린 민주 혁명입니다.","keywords":["4·19 혁명"],"ref":{"tab":"terms","idx":3},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-08","grade":"h1"},
{"id":"hist-h-k2-08#t4","kind":"term","title":"장면 내각","text":"4·19 혁명 뒤 1960년 내각 책임제 아래에서 국무총리 장면이 이끈 민주당 정부입니다.","keywords":["장면 내각"],"ref":{"tab":"terms","idx":4},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-08","grade":"h1"},
{"id":"hist-h-k2-08#t5","kind":"term","title":"5·16 군사 정변","text":"1961년 5월 16일 박정희를 중심으로 한 군인들이 무력으로 정권을 잡은 사건입니다.","keywords":["5·16 군사 정변"],"ref":{"tab":"terms","idx":5},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-08","grade":"h1"},
{"id":"hist-h-k2-08#t6","kind":"term","title":"유신 헌법","text":"1972년 만든 헌법으로, 대통령을 통일 주체 국민 회의에서 뽑고 연임 제한을 없애 대통령에게 권력을 집중시켰습니다.","keywords":["유신 헌법"],"ref":{"tab":"terms","idx":6},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-08","grade":"h1"},
{"id":"hist-h-k2-08#t7","kind":"term","title":"부마 민주 항쟁","text":"1979년 10월 부산과 마산에서 유신 체제에 반대해 일어난 대규모 시위입니다.","keywords":["부마 민주 항쟁"],"ref":{"tab":"terms","idx":7},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-08","grade":"h1"},
{"id":"hist-h-k2-08#t8","kind":"term","title":"5·18 민주화 운동","text":"1980년 5월 광주에서 시민들이 신군부의 비상계엄 확대와 계엄군의 폭력 진압에 맞서 일어난 민주화 운동입니다.","keywords":["5·18 민주화 운동"],"ref":{"tab":"terms","idx":8},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-08","grade":"h1"},
{"id":"hist-h-k2-08#t9","kind":"term","title":"6월 민주 항쟁","text":"1987년 6월 전국에서 시민들이 대통령 직선제 개헌과 민주화를 요구한 운동입니다. 6·29 민주화 선언을 이끌어 냈습니다.","keywords":["6월 민주 항쟁"],"ref":{"tab":"terms","idx":9},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-08","grade":"h1"},
{"id":"hist-h-k2-08#f0","kind":"faq","title":"사사오입이 무슨 뜻이에요?","text":"\"넷은 버리고 다섯은 올린다\", 곧 반올림이라는 뜻입니다. 1954년 개헌안에 필요한 찬성표는 재적 203명의 3분의 2인 135.33…명, 곧 136명이었는데 찬성이 135명이라 부결되었습니다. 그러자 정부와 여당은 135.33을 반올림하면 135라는 억지 논리로 통과를 선언했습니다.","keywords":[],"ref":{"tab":"faq","idx":0},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-08","grade":"h1"},
{"id":"hist-h-k2-08#f1","kind":"faq","title":"5·16은 \"혁명\"인가요, \"군사 정변\"인가요?","text":"교과서에서는 5·16 군사 정변이라고 부릅니다. 군인들이 무력을 사용해 헌법 절차를 무시하고 합법적인 정부(장면 내각)를 무너뜨리고 정권을 잡았기 때문입니다.","keywords":[],"ref":{"tab":"faq","idx":1},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-08","grade":"h1"},
{"id":"hist-h-k2-08#f2","kind":"faq","title":"부마 민주 항쟁의 \"부마\"는 무슨 뜻이에요?","text":"항쟁이 일어난 두 도시, 부산과 마산의 앞 글자를 딴 이름입니다. 1979년 10월 유신 체제에 반대하는 대규모 시위가 두 도시에서 일어났습니다.","keywords":["부마 민주 항쟁"],"ref":{"tab":"faq","idx":2},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-08","grade":"h1"},
{"id":"hist-h-k2-08#m0","kind":"mistake","title":"자주 하는 실수","text":"발췌 개헌(1952년, 직선제)과 사사오입 개헌(1954년, 초대 대통령 중임 제한 철폐)의 내용을 바꾸어 기억하는 실수 — \"발췌=직선, 사사오입=중임 제한 철폐\"로 짝지어 둡니다.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-08","grade":"h1"},
{"id":"hist-h-k2-08#m1","kind":"mistake","title":"자주 하는 실수","text":"5·18 민주화 운동(1980년, 광주)과 부마 민주 항쟁(1979년, 부산·마산)을 섞는 실수 — 부마 항쟁 뒤 유신이 무너지고, 그 뒤 신군부에 맞선 것이 5·18입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-08","grade":"h1"},
{"id":"hist-h-k2-08#m2","kind":"mistake","title":"자주 하는 실수","text":"6월 민주 항쟁으로 대통령 임기가 7년이 되었다고 생각하는 실수 — 7년 단임 간선제는 1980년 헌법이고, 1987년 헌법은 5년 단임 직선제입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-08","grade":"h1"},
{"id":"hist-h-k2-09","kind":"unit","title":"산업화와 경제 성장","text":"원조 경제에서 출발해 경제 개발 계획과 중화학 공업화로 고도성장을 이룬 과정을 살피고, 그 과정에서 생긴 농촌·노동·도시·환경 문제와 이를 해결하려는 노력을 알아봅니다. 1950년대 원조 경제의 특징과 한계를 설명할 수 있다. 경제 개발 5개년 계획과 중화학 공업화의 흐름을 시기별로 정리할 수 있다. 새마을 운동과 농촌의 변화를 성과와 한계 양면에서 평가…","keywords":["원조 경제","삼백 산업","경제 개발 5개년 계획","수출 주도형 산업화","중화학 공업화","석유 파동","3저 호황","새마을 운동","이촌향도","노동자 대투쟁"],"ref":{"tab":"concepts","idx":0},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-09","grade":"h1"},
{"id":"hist-h-k2-09#c0","kind":"concept","title":"전후 복구와 원조 경제","text":"6·25 전쟁으로 공장·도로·주택 같은 산업 시설이 크게 파괴되었습니다. 1950년대의 복구는 주로 미국의 원조에 기대어 이루어졌습니다. 원조 물자는 밀·원당(설탕 원료)·면화 같은 소비재 원료와 남는 농산물이 중심이었습니다. 이 원료를 가공하는 제분(밀가루)·제당(설탕)·면방직(면직물","keywords":["원조 경제","삼백 산업"],"ref":{"tab":"concepts","idx":0},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-09","grade":"h1"},
{"id":"hist-h-k2-09#c1","kind":"concept","title":"경제 개발 5개년 계획과 수출 주도 산업화","text":"5·16 군사 정변으로 들어선 정부는 1962년부터 경제 개발 5개년 계획을 실행했습니다. 계획은 앞선 정부 때도 세워졌지만, 실제로 추진된 것은 이때부터입니다. 제1·2차 계획(1962~1971): 값싸고 풍부한 노동력을 이용한 노동 집약적 경공업(섬유·가발·신발·합판 등)을 키웠습니","keywords":["경제 개발 5개년 계획"],"ref":{"tab":"concepts","idx":1},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-09","grade":"h1"},
{"id":"hist-h-k2-09#c2","kind":"concept","title":"중화학 공업 육성과 고도성장","text":"1970년대에 들어 경공업 제품의 수출이 한계에 부딪히고, 미국이 주한 미군을 줄이는 등 안보 환경도 바뀌었습니다. 정부는 1973년 중화학 공업화를 선언하고, 제3·4차 계획(1972~1981)에서 철강·기계·조선·전자·석유 화학·비철 금속을 집중 육성했습니다. 포항 종합 제철소가 1","keywords":["중화학 공업화","석유 파동","3저 호황"],"ref":{"tab":"concepts","idx":2},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-09","grade":"h1"},
{"id":"hist-h-k2-09#c3","kind":"concept","title":"농촌의 변화와 새마을 운동","text":"산업화는 도시와 공업을 중심으로 진행되어 농촌은 상대적으로 뒤처졌습니다. 정부는 공장 노동자의 임금을 낮게 유지하려고 곡물 값을 낮게 묶는 저곡가 정책을 폈고, 농가 소득이 도시보다 낮아지자 많은 사람이 일자리를 찾아 도시로 떠났습니다(이촌향도). 정부는 1970년 새마을 운동을 시작했","keywords":["새마을 운동","이촌향도"],"ref":{"tab":"concepts","idx":3},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-09","grade":"h1"},
{"id":"hist-h-k2-09#c4","kind":"concept","title":"산업화의 그늘: 노동 문제와 도시 문제","text":"빠른 성장 뒤에는 노동자들의 희생이 있었습니다. 많은 노동자가 저임금·장시간 노동과 열악한 작업 환경에 시달렸지만, 정부는 수출 경쟁력을 이유로 노동 운동을 억눌렀습니다. 1970년: 서울 평화 시장의 재단사 전태일이 \"근로 기준법을 지켜라\"라고 외치며 목숨을 바쳐 항의했습니다. 이 일","keywords":["이촌향도","노동자 대투쟁"],"ref":{"tab":"concepts","idx":4},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-09","grade":"h1"},
{"id":"hist-h-k2-09#c5","kind":"concept","title":"산업화와 생태환경, 환경 보호 노력","text":"경제 성장이 우선이던 시기에는 공장 폐수와 매연, 쓰레기 처리에 대한 대책이 부족해 하천과 공기가 심하게 오염되었습니다. 1980년대 울산 온산 공업 단지 주변 주민들이 공해로 의심되는 질환을 앓은 일(온산병)이 알려졌습니다. 1991년 낙동강 페놀 오염 사건: 공장에서 유출된 화학 물","keywords":[],"ref":{"tab":"concepts","idx":5},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-09","grade":"h1"},
{"id":"hist-h-k2-09#t0","kind":"term","title":"원조 경제","text":"다른 나라의 원조에 크게 기대어 운영되는 경제입니다. 1950년대 우리나라는 미국의 원조로 전후 복구를 했습니다.","keywords":["원조 경제"],"ref":{"tab":"terms","idx":0},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-09","grade":"h1"},
{"id":"hist-h-k2-09#t1","kind":"term","title":"삼백 산업","text":"1950년대 원조 물자를 가공한 제분·제당·면방직 공업입니다. 밀가루·설탕·면직물이 모두 흰색이어서 붙은 이름입니다.","keywords":["삼백 산업"],"ref":{"tab":"terms","idx":1},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-09","grade":"h1"},
{"id":"hist-h-k2-09#t2","kind":"term","title":"경제 개발 5개년 계획","text":"1962년부터 5년 단위로 세워 추진한 정부의 경제 개발 계획입니다. 1·2차는 경공업, 3·4차는 중화학 공업에 중점을 두었습니다.","keywords":["경제 개발 5개년 계획"],"ref":{"tab":"terms","idx":2},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-09","grade":"h1"},
{"id":"hist-h-k2-09#t3","kind":"term","title":"수출 주도형 산업화","text":"국내 시장 대신 해외 수출을 늘리는 것을 성장의 중심으로 삼는 산업화 방식입니다.","keywords":["수출 주도형 산업화"],"ref":{"tab":"terms","idx":3},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-09","grade":"h1"},
{"id":"hist-h-k2-09#t4","kind":"term","title":"중화학 공업화","text":"철강·기계·조선·전자·석유 화학 같은 무거운 제품과 화학 제품을 만드는 공업을 키우는 것입니다. 1973년 정부가 선언했습니다.","keywords":["중화학 공업화"],"ref":{"tab":"terms","idx":4},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-09","grade":"h1"},
{"id":"hist-h-k2-09#t5","kind":"term","title":"석유 파동","text":"석유 값이 갑자기 크게 올라 세계 경제가 흔들린 일입니다. 1973년(제1차)과 1970년대 말(제2차)에 일어났습니다.","keywords":["석유 파동"],"ref":{"tab":"terms","idx":5},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-09","grade":"h1"},
{"id":"hist-h-k2-09#t6","kind":"term","title":"3저 호황","text":"1980년대 중반 저유가·저금리·저달러로 수출이 크게 늘어난 경제 호황입니다.","keywords":["3저 호황"],"ref":{"tab":"terms","idx":6},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-09","grade":"h1"},
{"id":"hist-h-k2-09#t7","kind":"term","title":"새마을 운동","text":"1970년 정부가 근면·자조·협동을 내세워 시작한 지역 개발 운동입니다. 농촌에서 시작해 도시로 넓혀졌습니다.","keywords":["새마을 운동"],"ref":{"tab":"terms","idx":7},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-09","grade":"h1"},
{"id":"hist-h-k2-09#t8","kind":"term","title":"이촌향도","text":"농촌을 떠나 도시로 옮겨 가는 것입니다. 산업화 시기 일자리를 찾아 많은 사람이 도시로 갔습니다.","keywords":["이촌향도"],"ref":{"tab":"terms","idx":8},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-09","grade":"h1"},
{"id":"hist-h-k2-09#t9","kind":"term","title":"노동자 대투쟁","text":"1987년 6월 민주 항쟁 뒤 전국에서 노동자들이 임금 인상과 노동조합 결성을 요구하며 벌인 대규모 노동 운동입니다.","keywords":["노동자 대투쟁"],"ref":{"tab":"terms","idx":9},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-09","grade":"h1"},
{"id":"hist-h-k2-09#f0","kind":"faq","title":"삼백 산업은 왜 \"삼백\"이라고 해요?","text":"석 삼(三), 흰 백(白)으로 \"흰 제품 세 가지\"라는 뜻입니다. 1950년대 원조로 들어온 원료를 가공해 만든 밀가루(제분)·설탕(제당)·면직물(면방직)이 모두 흰색이어서 붙은 이름입니다.","keywords":["삼백 산업"],"ref":{"tab":"faq","idx":0},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-09","grade":"h1"},
{"id":"hist-h-k2-09#f1","kind":"faq","title":"왜 1970년대에 경공업에서 중화학 공업으로 바꿨어요?","text":"경공업 제품은 다른 개발도상국도 쉽게 만들 수 있어 경쟁이 심해졌고, 수출 증가에도 한계가 있었습니다. 또 미국이 주한 미군을 줄이는 등 안보 환경이 바뀌어 무기를 만드는 데 필요한 중공업의 중요성도 커졌습니다. 그래서 정부는 1973년 중화학 공업화를 선언했습니다.","keywords":[],"ref":{"tab":"faq","idx":1},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-09","grade":"h1"},
{"id":"hist-h-k2-09#f2","kind":"faq","title":"새마을 운동은 좋은 거예요, 나쁜 거예요?","text":"역사적 사건은 한쪽으로만 평가하기 어렵습니다. 새마을 운동은 농촌의 길·지붕·전기 같은 생활 환경을 크게 바꾼 성과가 있습니다. 동시에 정부가 위에서 이끈 운동이었고, 유신 체제를 지지하는 분위기를 만드는 데 이용되었다는 비판도 있습니다. 두 면을 함께 설명할 수 있어야 합니다.","keywords":["새마을 운동"],"ref":{"tab":"faq","idx":2},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-09","grade":"h1"},
{"id":"hist-h-k2-09#m0","kind":"mistake","title":"자주 하는 실수","text":"시기별 산업을 섞는 실수 — 1950년대는 원조 경제·삼백 산업, 1960년대는 경공업 수출, 1970년대는 중화학 공업, 1980년대 중반은 3저 호황입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-09","grade":"h1"},
{"id":"hist-h-k2-09#m1","kind":"mistake","title":"자주 하는 실수","text":"제1차 석유 파동 극복(1970년대 중동 건설 진출)과 3저 호황(1980년대 중반)을 헷갈리는 실수 — 둘은 10년 이상 차이가 납니다.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-09","grade":"h1"},
{"id":"hist-h-k2-09#m2","kind":"mistake","title":"자주 하는 실수","text":"광주 대단지 사건(1971년, 경기도 광주 — 지금의 성남)과 5·18 민주화 운동(1980년, 전라남도 광주)을 헷갈리는 실수 — 시기도 성격도 다릅니다.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-09","grade":"h1"},
{"id":"hist-h-k2-10","kind":"unit","title":"문화 변동과 일상생활","text":"산업화와 도시화로 사람들이 사는 집, 가족의 모습, 학교 교육, 신문·방송과 대중문화가 어떻게 달라졌는지 생활 속 사례로 살펴봅니다. 도시화에 따른 주거 생활의 변화(아파트, 신도시)를 설명할 수 있다. 가족 구조와 인구 정책의 변화를 시기별로 정리할 수 있다. 교육의 확대와 주요 교육 제도의 변화를 설명할 수 있다. 대중 매체와 대중문화의 성장, 청년 …","keywords":["도시화","신도시","핵가족","가족계획 사업","고교 평준화","대중 매체","대중문화","청년 문화","언론 통폐합","보도 지침"],"ref":{"tab":"concepts","idx":0},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-10","grade":"h1"},
{"id":"hist-h-k2-10#c0","kind":"concept","title":"도시화와 주거 생활의 변화","text":"1960년대 이후 산업화로 일자리가 도시에 몰리자 많은 사람이 농촌을 떠나 도시로 옮겨 갔습니다(이촌향도). 도시 인구가 빠르게 늘어 1990년대에는 국민 대부분이 도시에 살게 되었습니다. 주택 부족: 늘어난 인구를 감당하지 못해 산비탈에 판잣집이 들어섰고, 셋방살이하는 가구도 많았습니","keywords":["도시화","신도시"],"ref":{"tab":"concepts","idx":0},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-10","grade":"h1"},
{"id":"hist-h-k2-10#c1","kind":"concept","title":"가족 구조와 인구 정책의 변화","text":"산업화·도시화로 젊은 세대가 도시로 떠나면서, 여러 세대가 함께 사는 대가족 대신 부부와 미혼 자녀로 이루어진 핵가족이 일반적인 가족 형태가 되었습니다. 인구 정책은 시기에 따라 방향이 크게 바뀌었습니다. 시기 · 정책 방향 · 예 1960~1980년대 · 출산 억제 · 1962년 가족","keywords":["도시화","핵가족","가족계획 사업"],"ref":{"tab":"concepts","idx":1},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-10","grade":"h1"},
{"id":"hist-h-k2-10#c2","kind":"concept","title":"교육의 확대와 교육 제도의 변화","text":"광복 이후 교육 기회가 크게 넓어졌습니다. 1949년 교육법이 제정되었고, 1950년대에 초등 의무 교육이 확대되었습니다. 높은 교육열 속에 진학 경쟁이 심해지자 정부는 입시 제도를 여러 번 바꾸었습니다. 해 · 내용 1968년 · 국민 교육 헌장 선포 — 국가에 대한 충성과 반공을 강","keywords":["고교 평준화"],"ref":{"tab":"concepts","idx":2},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-10","grade":"h1"},
{"id":"hist-h-k2-10#c3","kind":"concept","title":"언론과 대중 매체의 성장","text":"산업화로 소득이 늘고 교육받은 사람이 많아지면서 신문·라디오·텔레비전 같은 대중 매체가 빠르게 퍼졌습니다. 신문: 읽을 수 있는 사람이 늘어나면서 발행 부수가 크게 늘었습니다. 라디오: 1960년대에 값싼 라디오가 널리 보급되어 농촌에서도 뉴스·드라마·음악을 들었습니다. 텔레비전: 19","keywords":["대중 매체"],"ref":{"tab":"concepts","idx":3},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-10","grade":"h1"},
{"id":"hist-h-k2-10#c4","kind":"concept","title":"대중문화의 발달","text":"대중 매체가 퍼지면서 많은 사람이 함께 즐기는 대중문화가 크게 발달했습니다. 영화: 1960년대에는 한국 영화가 많이 만들어져 큰 인기를 누렸습니다. 드라마: 1970년대에는 텔레비전 연속극이 인기를 끌어 온 가족이 함께 보는 문화가 생겼습니다. 대중가요: 트로트에 더해 1970년대에는","keywords":["대중 매체","대중문화"],"ref":{"tab":"concepts","idx":4},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-10","grade":"h1"},
{"id":"hist-h-k2-10#c5","kind":"concept","title":"청년 문화의 등장과 언론·대중문화 통제","text":"1970년대에는 대학생을 중심으로 청바지·통기타·생맥주로 상징되는 청년 문화가 퍼졌습니다. 기성세대와 다른 자유로운 옷차림과 음악으로 개성을 드러낸 것입니다. 독재 정권은 이런 문화와 언론을 통제했습니다. 유신 체제(1970년대): 장발과 미니스커트를 \"풍속을 해친다\"며 단속했고, 19","keywords":["대중문화","청년 문화","언론 통폐합","보도 지침"],"ref":{"tab":"concepts","idx":5},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-10","grade":"h1"},
{"id":"hist-h-k2-10#t0","kind":"term","title":"도시화","text":"도시에 사는 인구의 비율이 높아지고 도시의 생활 방식이 퍼지는 현상입니다.","keywords":["도시화"],"ref":{"tab":"terms","idx":0},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-10","grade":"h1"},
{"id":"hist-h-k2-10#t1","kind":"term","title":"신도시","text":"큰 도시의 인구와 주택 문제를 덜기 위해 계획적으로 새로 만든 도시입니다. 예: 1989년 발표된 분당·일산","keywords":["신도시"],"ref":{"tab":"terms","idx":1},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-10","grade":"h1"},
{"id":"hist-h-k2-10#t2","kind":"term","title":"핵가족","text":"부부와 결혼하지 않은 자녀로 이루어진 가족입니다. 산업화·도시화로 일반적인 가족 형태가 되었습니다.","keywords":["핵가족"],"ref":{"tab":"terms","idx":2},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-10","grade":"h1"},
{"id":"hist-h-k2-10#t3","kind":"term","title":"가족계획 사업","text":"1962년부터 정부가 출산을 줄이기 위해 벌인 사업입니다. \"둘만 낳아 잘 기르자\" 같은 구호를 썼습니다.","keywords":["가족계획 사업"],"ref":{"tab":"terms","idx":3},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-10","grade":"h1"},
{"id":"hist-h-k2-10#t4","kind":"term","title":"고교 평준화","text":"고등학교 입학시험을 없애고 학군별 추첨으로 학생을 배정하는 제도입니다. 1974년 서울·부산부터 실시되었습니다.","keywords":["고교 평준화"],"ref":{"tab":"terms","idx":4},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-10","grade":"h1"},
{"id":"hist-h-k2-10#t5","kind":"term","title":"대중 매체","text":"신문·라디오·텔레비전처럼 많은 사람에게 한꺼번에 정보를 전하는 수단입니다.","keywords":["대중 매체"],"ref":{"tab":"terms","idx":5},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-10","grade":"h1"},
{"id":"hist-h-k2-10#t6","kind":"term","title":"대중문화","text":"대중 매체를 통해 많은 사람이 함께 즐기는 문화입니다. 대중가요, 드라마, 영화, 프로 스포츠 등이 있습니다.","keywords":["대중문화"],"ref":{"tab":"terms","idx":6},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-10","grade":"h1"},
{"id":"hist-h-k2-10#t7","kind":"term","title":"청년 문화","text":"1970년대 대학생을 중심으로 퍼진 통기타·청바지·생맥주로 상징되는 젊은이들의 문화입니다.","keywords":["청년 문화"],"ref":{"tab":"terms","idx":7},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-10","grade":"h1"},
{"id":"hist-h-k2-10#t8","kind":"term","title":"언론 통폐합","text":"1980년 신군부가 언론사를 강제로 합치거나 없앤 조치입니다.","keywords":["언론 통폐합"],"ref":{"tab":"terms","idx":8},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-10","grade":"h1"},
{"id":"hist-h-k2-10#t9","kind":"term","title":"보도 지침","text":"1980년대 정부가 언론사에 어떤 기사를 어떻게 쓸지 지시한 비밀 지침입니다. 1986년 폭로되었습니다.","keywords":["보도 지침"],"ref":{"tab":"terms","idx":9},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-10","grade":"h1"},
{"id":"hist-h-k2-10#f0","kind":"faq","title":"옛날에는 정말 나라에서 아이를 적게 낳으라고 했어요?","text":"네. 1960~1980년대에는 인구가 빠르게 늘어 경제 성장에 부담이 된다고 보았기 때문에, 정부가 가족계획 사업으로 출산을 줄이도록 권했습니다. \"둘만 낳아 잘 기르자\" 같은 구호가 대표적입니다. 출산율이 크게 낮아진 지금은 반대로 출산을 장려하고 있습니다.","keywords":[],"ref":{"tab":"faq","idx":0},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-10","grade":"h1"},
{"id":"hist-h-k2-10#f1","kind":"faq","title":"머리가 길거나 치마가 짧다고 왜 단속했어요?","text":"1970년대 유신 체제의 정부는 장발·미니스커트를 \"사회 풍속을 해친다\"며 경범죄로 단속했습니다. 개인의 옷차림과 머리 모양까지 나라가 통제한 것으로, 당시 권위주의 정치가 일상생활까지 얼마나 깊이 영향을 주었는지 보여 주는 예입니다.","keywords":[],"ref":{"tab":"faq","idx":1},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-10","grade":"h1"},
{"id":"hist-h-k2-10#f2","kind":"faq","title":"왜 우리나라에는 아파트가 이렇게 많아요?","text":"산업화로 도시에 사람이 갑자기 몰렸는데 땅은 좁았기 때문입니다. 좁은 땅에 많은 집을 지을 수 있는 아파트가 해결책이 되었고, 1970년대 강남 개발과 1980년대 말 신도시 건설로 대규모 아파트 단지가 크게 늘었습니다.","keywords":[],"ref":{"tab":"faq","idx":2},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-10","grade":"h1"},
{"id":"hist-h-k2-10#m0","kind":"mistake","title":"자주 하는 실수","text":"중학교 무시험 진학(1969년)과 고교 평준화(1974년)를 헷갈리는 실수 — 앞의 것은 중학교, 뒤의 것은 고등학교 입학시험을 없앴습니다.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-10","grade":"h1"},
{"id":"hist-h-k2-10#m1","kind":"mistake","title":"자주 하는 실수","text":"인구 정책의 방향을 거꾸로 기억하는 실수 — 1960~1980년대는 출산 억제, 2000년대 이후는 출산 장려입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-10","grade":"h1"},
{"id":"hist-h-k2-10#m2","kind":"mistake","title":"자주 하는 실수","text":"1980년대 초의 자율화 조치(통행금지 해제·교복 자율화)를 민주화로 착각하는 실수 — 같은 시기 언론은 통폐합·보도 지침으로 강하게 통제되었습니다.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-10","grade":"h1"},
{"id":"hist-h-k2-11","kind":"unit","title":"민주화의 진전과 외환 위기","text":"6월 민주 항쟁 이후 민주주의가 제도로 뿌리내리고 시민운동이 성장한 과정, 1997년 외환 위기의 발생과 극복, 그 뒤 정보화·세계화 속에서 달라진 우리 사회와 문화를 살펴봅니다. 6월 민주 항쟁 이후 민주주의가 제도화되고 평화적 정권 교체가 정착한 과정을 설명할 수 있다. 시민운동의 성장과 그 성과를 사례를 들어 설명할 수 있다. 외환 위기의 원인과 극…","keywords":["6·29 민주화 선언","대통령 직선제","지방 자치제","평화적 정권 교체","금융 실명제","시민운동","외환 위기","구조 조정","양극화","한류"],"ref":{"tab":"concepts","idx":0},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-11","grade":"h1"},
{"id":"hist-h-k2-11#c0","kind":"concept","title":"6월 민주 항쟁 이후 민주주의의 제도화","text":"1987년 6월 민주 항쟁으로 정부는 6·29 민주화 선언을 발표하고 국민의 요구를 받아들였습니다. 그해 10월 헌법이 개정되어 대통령 직선제(5년 단임)가 마련되었습니다. 이 헌법은 그 뒤 30년 넘게 한 번도 고쳐지지 않고 이어졌습니다. 민주주의를 뒷받침하는 제도들이 차례로 자리 잡","keywords":["6·29 민주화 선언","대통령 직선제","지방 자치제"],"ref":{"tab":"concepts","idx":0},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-11","grade":"h1"},
{"id":"hist-h-k2-11#c1","kind":"concept","title":"평화적 정권 교체의 정착","text":"대통령 직선제 아래에서 선거를 통해 정부가 바뀌는 일이 자리 잡았습니다. 정부 · 주요 내용 노태우 정부(1988~1993) · 국회의 여소야대, 5공 청문회, 1990년 3당 합당, 북방 외교 김영삼 정부(1993~1998) · 32년 만의 민간인 출신 대통령(문민정부), 금융 실명제","keywords":["대통령 직선제","지방 자치제","평화적 정권 교체","금융 실명제","외환 위기"],"ref":{"tab":"concepts","idx":1},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-11","grade":"h1"},
{"id":"hist-h-k2-11#c2","kind":"concept","title":"시민운동의 성장","text":"민주화로 표현과 결사의 자유가 넓어지자, 1980년대 말부터 시민들이 스스로 단체를 만들어 사회 문제를 해결하려는 시민운동이 크게 성장했습니다. 이전의 민주화 운동이 독재에 맞서는 데 집중했다면, 시민운동은 생활 속의 다양한 문제를 다루었습니다. 환경 운동: 개발 사업이 자연에 끼칠 피","keywords":["시민운동"],"ref":{"tab":"concepts","idx":2},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-11","grade":"h1"},
{"id":"hist-h-k2-11#c3","kind":"concept","title":"외환 위기의 발생과 극복","text":"1990년대 우리 경제에는 문제가 쌓이고 있었습니다. 대기업은 빌린 돈으로 무리하게 사업을 넓혔고, 금융 기관은 부실해졌으며, 갚아야 할 기간이 짧은 외국 빚(단기 외채)이 크게 늘었습니다. 1997년 동남아시아에서 외환 위기가 일어나자 외국 자본이 우리나라에서도 빠르게 빠져나갔고, 큰","keywords":["외환 위기","구조 조정"],"ref":{"tab":"concepts","idx":3},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-11","grade":"h1"},
{"id":"hist-h-k2-11#c4","kind":"concept","title":"외환 위기 이후의 사회 변화","text":"외환 위기는 극복되었지만 우리 사회에 깊은 흔적을 남겼습니다. 고용 불안: 구조 조정으로 많은 사람이 일자리를 잃었고, 한 직장에서 오래 일하는 \"평생직장\"이라는 생각이 약해졌습니다. 기간을 정해 일하는 비정규직이 크게 늘었습니다. 양극화: 고소득층과 저소득층의 소득·재산 격차가 벌어지","keywords":["외환 위기","구조 조정","양극화"],"ref":{"tab":"concepts","idx":4},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-11","grade":"h1"},
{"id":"hist-h-k2-11#c5","kind":"concept","title":"정보화·세계화 속 사회와 문화의 변동","text":"1990년대 후반부터 우리 사회는 빠르게 정보화·세계화되었습니다. 정보화: 초고속 인터넷과 휴대 전화가 널리 퍼져 정보를 얻고 소통하는 방식이 크게 바뀌었습니다. 인터넷은 시민이 의견을 나누는 새로운 공간이 되었습니다. 세계화: 1995년 세계 무역 기구(WTO) 출범, 1996년 OE","keywords":[],"ref":{"tab":"concepts","idx":5},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-11","grade":"h1"},
{"id":"hist-h-k2-11#t0","kind":"term","title":"6·29 민주화 선언","text":"1987년 6월 민주 항쟁의 결과, 대통령 직선제 개헌 등 국민의 요구를 받아들이겠다고 발표한 선언입니다.","keywords":["6·29 민주화 선언"],"ref":{"tab":"terms","idx":0},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-11","grade":"h1"},
{"id":"hist-h-k2-11#t1","kind":"term","title":"대통령 직선제","text":"국민이 대통령을 직접 투표로 뽑는 제도입니다. 1987년 헌법 개정으로 5년 단임의 직선제가 마련되었습니다.","keywords":["대통령 직선제"],"ref":{"tab":"terms","idx":1},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-11","grade":"h1"},
{"id":"hist-h-k2-11#t2","kind":"term","title":"지방 자치제","text":"지역 주민이 뽑은 대표가 그 지역의 일을 스스로 처리하는 제도입니다. 1991년 다시 시작되어 1995년 전면 실시되었습니다.","keywords":["지방 자치제"],"ref":{"tab":"terms","idx":2},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-11","grade":"h1"},
{"id":"hist-h-k2-11#t3","kind":"term","title":"평화적 정권 교체","text":"무력이 아니라 선거를 통해 정권이 바뀌는 것입니다. 1997년 선거로 처음 여야 간 정권 교체가 이루어졌습니다.","keywords":["평화적 정권 교체"],"ref":{"tab":"terms","idx":3},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-11","grade":"h1"},
{"id":"hist-h-k2-11#t4","kind":"term","title":"금융 실명제","text":"모든 금융 거래를 실제 이름으로만 하게 한 제도입니다. 1993년 김영삼 정부가 실시했습니다.","keywords":["금융 실명제"],"ref":{"tab":"terms","idx":4},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-11","grade":"h1"},
{"id":"hist-h-k2-11#t5","kind":"term","title":"시민운동","text":"시민들이 스스로 단체를 만들어 환경·여성·인권·소비자 문제 등 사회 문제를 해결하려는 운동입니다.","keywords":["시민운동"],"ref":{"tab":"terms","idx":5},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-11","grade":"h1"},
{"id":"hist-h-k2-11#t6","kind":"term","title":"외환 위기","text":"나라에 외국 돈이 모자라 외국 빚을 갚지 못할 위기에 빠진 것입니다. 우리나라는 1997년 말 IMF에 구제 금융을 요청했습니다.","keywords":["외환 위기"],"ref":{"tab":"terms","idx":6},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-11","grade":"h1"},
{"id":"hist-h-k2-11#t7","kind":"term","title":"구조 조정","text":"부실한 기업·금융 기관을 정리하고 조직과 인력을 줄이는 등 경제 구조를 고치는 일입니다.","keywords":["구조 조정"],"ref":{"tab":"terms","idx":7},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-11","grade":"h1"},
{"id":"hist-h-k2-11#t8","kind":"term","title":"양극화","text":"고소득층과 저소득층의 격차가 커지고 중산층이 줄어드는 현상입니다.","keywords":["양극화"],"ref":{"tab":"terms","idx":8},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-11","grade":"h1"},
{"id":"hist-h-k2-11#t9","kind":"term","title":"한류","text":"한국의 드라마·대중가요·영화 등 대중문화가 다른 나라에서 인기를 끄는 현상입니다. 1990년대 후반에 생긴 말입니다.","keywords":["한류"],"ref":{"tab":"terms","idx":9},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-11","grade":"h1"},
{"id":"hist-h-k2-11#f0","kind":"faq","title":"외환 위기 때 나라가 망한 거예요?","text":"나라가 망한 것은 아니고, 외국 빚을 갚을 외국 돈(외환)이 모자라 갚지 못할 위기에 빠진 것입니다. IMF에서 긴급 자금을 빌리고, 국민의 금 모으기 운동과 기업·금융 구조 조정 등으로 위기를 넘겨 2001년에 빌린 돈을 모두 갚았습니다. 다만 그 과정에서 많은 사람이 일자리를 잃는 등 큰 고통을 겪었습니다.","keywords":["외환 위기"],"ref":{"tab":"faq","idx":0},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-11","grade":"h1"},
{"id":"hist-h-k2-11#f1","kind":"faq","title":"지방 자치제는 왜 중요해요?","text":"지역마다 사정이 다르기 때문에, 그 지역 주민이 뽑은 대표가 지역의 일을 결정하는 것이 더 알맞을 때가 많습니다. 또 주민이 가까운 곳에서 정치에 참여하는 경험을 쌓게 해 주어 \"풀뿌리 민주주의\"라고 부릅니다.","keywords":["지방 자치제"],"ref":{"tab":"faq","idx":1},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-11","grade":"h1"},
{"id":"hist-h-k2-11#f2","kind":"faq","title":"평화적 정권 교체가 왜 그렇게 중요한 일이에요?","text":"이전에는 정변이나 헌법을 고친 장기 집권으로 권력이 유지되거나 바뀌는 일이 많았습니다. 선거 결과에 따라 여당이 야당에 권력을 넘겨주는 일이 자연스러워졌다는 것은, 국민의 투표가 권력을 결정한다는 민주주의 원칙이 실제로 지켜지게 되었다는 뜻입니다.","keywords":["평화적 정권 교체"],"ref":{"tab":"faq","idx":2},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-11","grade":"h1"},
{"id":"hist-h-k2-11#m0","kind":"mistake","title":"자주 하는 실수","text":"금 모으기 운동(1997~1998년 외환 위기)과 국채 보상 운동(1907년 대한 제국)을 헷갈리는 실수 — 시대가 약 90년 차이 납니다.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-11","grade":"h1"},
{"id":"hist-h-k2-11#m1","kind":"mistake","title":"자주 하는 실수","text":"지방 자치제의 연도를 헷갈리는 실수 — 1991년은 지방 의회 선거로 다시 시작, 1995년은 단체장까지 뽑는 전면 실시입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-11","grade":"h1"},
{"id":"hist-h-k2-11#m2","kind":"mistake","title":"자주 하는 실수","text":"고령화 사회(65세 이상 7% 이상)와 고령 사회(14% 이상)를 헷갈리는 실수 — 우리나라는 2000년에 고령화 사회가 되었습니다.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-11","grade":"h1"},
{"id":"hist-h-k2-12","kind":"unit","title":"한반도 평화와 동아시아","text":"북한 사회와 남북 관계의 변화, 북한 핵 문제를 살피고, 독도가 우리 영토인 역사적 근거와 동아시아의 역사 갈등을 알아본 뒤 한반도와 동아시아의 평화를 이루는 방안을 생각해 봅니다. 북한 사회의 변화와 남북 관계의 흐름을 주요 합의를 중심으로 설명할 수 있다. 북한 핵 문제와 한반도 평화를 위한 노력을 설명할 수 있다. 독도가 우리 영토인 역사적 근거를 …","keywords":["경제 특구","7·4 남북 공동 성명","남북 기본 합의서","6·15 남북 공동 선언","6자 회담","칙령 제41호","시마네현 고시 제40호","역사 교과서 왜곡","동북공정"],"ref":{"tab":"concepts","idx":0},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-12","grade":"h1"},
{"id":"hist-h-k2-12#c0","kind":"concept","title":"북한 사회의 변화","text":"1990년대 초 소련과 동유럽의 사회주의 국가들이 무너지면서 북한은 큰 어려움에 빠졌습니다. 지원과 교역이 크게 줄었고, 1994년 김일성이 사망했으며, 홍수·가뭄 같은 자연재해까지 겹쳐 심각한 경제난과 식량난을 겪었습니다. 북한은 이 시기를 \"고난의 행군\"이라고 불렀고, 북한을 떠나는","keywords":["경제 특구"],"ref":{"tab":"concepts","idx":0},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-12","grade":"h1"},
{"id":"hist-h-k2-12#c1","kind":"concept","title":"남북 관계의 변화","text":"분단 이후 남북은 오랫동안 대립했지만, 국제 정세가 바뀔 때마다 대화의 길을 열어 왔습니다. 해 · 내용 1972년 · 7·4 남북 공동 성명 — 자주·평화·민족적 대단결의 통일 3대 원칙에 처음 합의 1985년 · 이산가족 고향 방문단과 예술 공연단이 처음으로 서로 오감 1991년 ·","keywords":["7·4 남북 공동 성명","남북 기본 합의서","6·15 남북 공동 선언"],"ref":{"tab":"concepts","idx":1},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-12","grade":"h1"},
{"id":"hist-h-k2-12#c2","kind":"concept","title":"북한 핵 문제와 한반도 평화를 위한 노력","text":"북한의 핵 개발은 한반도와 동아시아 평화를 위협하는 가장 큰 문제 가운데 하나입니다. 1991년: 남북이 핵무기를 시험·생산·보유하지 않기로 한 한반도 비핵화 공동 선언을 채택했습니다. 1993년: 북한이 핵 확산 금지 조약(NPT)에서 탈퇴하겠다고 선언해 1차 북핵 위기가 일어났고, ","keywords":["6자 회담"],"ref":{"tab":"concepts","idx":2},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-12","grade":"h1"},
{"id":"hist-h-k2-12#c3","kind":"concept","title":"독도가 우리 영토인 역사적 근거","text":"독도는 울릉도에서 동남쪽으로 약 87 km 떨어진 우리 영토입니다. 맑은 날에는 울릉도에서 맨눈으로 보일 만큼 가까워, 예부터 울릉도와 함께 생활권을 이루었습니다. 시기 · 근거 512년 · 신라 이사부가 우산국(울릉도·독도)을 복속(『삼국사기』) 1454년 · 『세종실록』 지리지: 우","keywords":["칙령 제41호"],"ref":{"tab":"concepts","idx":3},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-12","grade":"h1"},
{"id":"hist-h-k2-12#c4","kind":"concept","title":"동아시아의 역사 갈등","text":"동아시아의 여러 나라는 오랫동안 교류해 온 이웃이지만, 지난 역사를 둘러싸고 갈등을 겪고 있습니다. 일본과의 갈등 역사 교과서 왜곡: 1982년 일본 역사 교과서가 침략을 \"진출\"로 고쳐 쓴 문제가 외교 문제로 떠올랐고, 2000년대 이후에도 침략과 식민 지배를 축소하거나 미화하는 교과","keywords":["역사 교과서 왜곡","동북공정"],"ref":{"tab":"concepts","idx":4},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-12","grade":"h1"},
{"id":"hist-h-k2-12#c5","kind":"concept","title":"동아시아 평화를 위한 교류와 협력","text":"역사 갈등을 풀고 평화를 이루기 위해 정부와 시민 사회가 함께 노력하고 있습니다. 정부 차원: 한일 역사 공동 연구 위원회(2002년)처럼 이웃 나라 학자들이 함께 역사를 연구하는 기구를 만들었고, 2006년 동북아역사재단을 세워 역사 왜곡에 체계적으로 대응하고 있습니다. 시민 사회: ","keywords":[],"ref":{"tab":"concepts","idx":5},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-12","grade":"h1"},
{"id":"hist-h-k2-12#t0","kind":"term","title":"경제 특구","text":"외국 기업과 자본을 끌어들이려고 특별한 혜택을 주는 지역입니다. 북한은 1991년 나진·선봉 경제 무역 지대를 처음 지정했습니다.","keywords":["경제 특구"],"ref":{"tab":"terms","idx":0},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-12","grade":"h1"},
{"id":"hist-h-k2-12#t1","kind":"term","title":"7·4 남북 공동 성명","text":"1972년 남북이 자주·평화·민족적 대단결의 통일 3대 원칙에 처음 합의한 성명입니다.","keywords":["7·4 남북 공동 성명"],"ref":{"tab":"terms","idx":1},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-12","grade":"h1"},
{"id":"hist-h-k2-12#t2","kind":"term","title":"남북 기본 합의서","text":"1991년 남북이 서로의 체제를 인정하고 불가침과 교류·협력에 합의한 문서입니다.","keywords":["남북 기본 합의서"],"ref":{"tab":"terms","idx":2},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-12","grade":"h1"},
{"id":"hist-h-k2-12#t3","kind":"term","title":"6·15 남북 공동 선언","text":"2000년 첫 남북 정상 회담의 결과 발표된 선언입니다. 이후 이산가족 상봉, 경제 협력 등이 활발해졌습니다.","keywords":["6·15 남북 공동 선언"],"ref":{"tab":"terms","idx":3},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-12","grade":"h1"},
{"id":"hist-h-k2-12#t4","kind":"term","title":"6자 회담","text":"북한 핵 문제를 풀기 위해 2003년부터 남북한·미국·중국·일본·러시아가 참여한 회담입니다.","keywords":["6자 회담"],"ref":{"tab":"terms","idx":4},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-12","grade":"h1"},
{"id":"hist-h-k2-12#t5","kind":"term","title":"칙령 제41호","text":"1900년 대한 제국이 울릉도를 울도군으로 높이고 석도(독도)를 관할하게 한 법령입니다. 독도가 우리 땅인 근거입니다.","keywords":["칙령 제41호"],"ref":{"tab":"terms","idx":5},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-12","grade":"h1"},
{"id":"hist-h-k2-12#t6","kind":"term","title":"시마네현 고시 제40호","text":"1905년 러일 전쟁 중 일본이 독도를 자기 영토에 편입한다고 알린 고시입니다. 불법적인 조치입니다.","keywords":["시마네현 고시 제40호"],"ref":{"tab":"terms","idx":6},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-12","grade":"h1"},
{"id":"hist-h-k2-12#t7","kind":"term","title":"역사 교과서 왜곡","text":"일본의 일부 역사 교과서가 침략과 식민 지배를 축소하거나 미화해 서술한 문제입니다.","keywords":["역사 교과서 왜곡"],"ref":{"tab":"terms","idx":7},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-12","grade":"h1"},
{"id":"hist-h-k2-12#t8","kind":"term","title":"동북공정","text":"중국이 2002년부터 고조선·고구려·발해의 역사를 중국 지방 정권의 역사로 서술하려 한 국가 연구 사업입니다.","keywords":["동북공정"],"ref":{"tab":"terms","idx":8},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-12","grade":"h1"},
{"id":"hist-h-k2-12#f0","kind":"faq","title":"독도가 우리 땅이라는 걸 어떻게 확신할 수 있어요?","text":"오래된 우리 기록(『세종실록』 지리지 등)이 독도를 우리 땅으로 적고 있고, 1877년 일본 최고 행정 기관(태정관)도 독도가 일본과 관계없다고 했습니다. 1900년 대한 제국은 칙령 제41호로 독도를 다스렸고, 광복 뒤 연합국도 독도를 일본의 통치 범위에서 뺐습니다. 지금도 우리가 실제로 지키고 다스리고 있습니다.","keywords":[],"ref":{"tab":"faq","idx":0},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-12","grade":"h1"},
{"id":"hist-h-k2-12#f1","kind":"faq","title":"동북공정이 왜 문제가 돼요?","text":"동북공정은 고조선·고구려·발해의 역사를 중국 지방 정권의 역사로 서술하려는 사업입니다. 이렇게 되면 우리 고대사의 중요한 부분이 중국사가 되어 버려, 우리 역사의 뿌리와 정체성을 흔들게 됩니다. 그래서 학계와 정부가 연구로 대응하고 있습니다.","keywords":["동북공정"],"ref":{"tab":"faq","idx":1},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-12","grade":"h1"},
{"id":"hist-h-k2-12#f2","kind":"faq","title":"남북 관계는 왜 좋아졌다 나빠졌다 해요?","text":"남북 관계는 남북 정부의 정책뿐 아니라 북한의 핵 개발과 군사 도발, 미국·중국 같은 주변 나라와의 관계 등 여러 요인의 영향을 받습니다. 그래서 정상 회담과 교류로 가까워졌다가도 군사적 긴장으로 다시 멀어지는 일이 되풀이되었습니다. 그럼에도 대화의 끈을 이어 가려는 노력이 평화의 바탕이 됩니다.","keywords":[],"ref":{"tab":"faq","idx":2},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-12","grade":"h1"},
{"id":"hist-h-k2-12#m0","kind":"mistake","title":"자주 하는 실수","text":"남북 합의를 헷갈리는 실수 — 7·4 남북 공동 성명(1972, 통일 3대 원칙), 남북 기본 합의서(1991, 체제 인정·불가침), 6·15 남북 공동 선언(2000, 첫 정상 회담)입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-12","grade":"h1"},
{"id":"hist-h-k2-12#m1","kind":"mistake","title":"자주 하는 실수","text":"독도 관련 번호를 헷갈리는 실수 — 칙령 제41호(1900, 대한 제국, 우리 근거)와 시마네현 고시 제40호(1905, 일본의 불법 편입)는 다릅니다.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-12","grade":"h1"},
{"id":"hist-h-k2-12#m2","kind":"mistake","title":"자주 하는 실수","text":"동북공정(중국)과 역사 교과서 왜곡(일본)을 헷갈리는 실수 — 어느 나라와의 갈등인지 먼저 확인하세요.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-h-k2","unit":"hist-h-k2-12","grade":"h1"},
{"id":"hist-h-world-01","kind":"unit","title":"현생 인류와 문명의 형성","text":"현생 인류가 생태환경에 맞춰 살아간 여러 방식과, 아프로유라시아와 아메리카에서 고대 문명이 생겨난 과정을 탐구합니다. 현생 인류의 등장과 확산을 고고학 자료를 근거로 설명할 수 있다. 수렵·채집, 농경, 목축이 생태환경에 따라 달랐음을 이해하고, 농경과 정착이 가져온 변화를 설명할 수 있다. 아프로유라시아와 아메리카 고대 문명의 특징을 비교할 수 있다. …","keywords":["현생 인류","고고학 자료","신석기 혁명","유목","잉여 생산물","관개 농업","쐐기 문자","지구라트","갑골 문자","계단식 밭"],"ref":{"tab":"concepts","idx":0},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-01","grade":"h2"},
{"id":"hist-h-world-01#c0","kind":"concept","title":"현생 인류의 등장과 확산","text":"오늘날 인류와 같은 종인 현생 인류(호모 사피엔스)는 약 30만~20만 년 전 무렵 아프리카에서 등장한 것으로 봅니다. 이후 수만 년에 걸쳐 아프리카를 떠나 서아시아·유럽·아시아·오스트레일리아로 퍼졌고, 빙하기에 바닷물이 줄어 드러난 베링 육교를 건너 아메리카까지 이동했습니다. 문자가 ","keywords":["현생 인류","고고학 자료"],"ref":{"tab":"concepts","idx":0},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-01","grade":"h2"},
{"id":"hist-h-world-01#c1","kind":"concept","title":"생태환경에 따른 생존 방식 — 수렵·채집, 농경, 목축","text":"오랫동안 인류는 짐승을 사냥하고 열매와 뿌리를 모으는 수렵·채집으로 살았습니다. 먹을거리를 따라 옮겨 다니는 이동 생활이 기본이었습니다. 약 1만 년 전 빙하기가 끝나 기후가 따뜻해지자, 서아시아의 이른바 \"비옥한 초승달 지대\"에서 밀·보리를 기르고 양·염소를 길들이기 시작했습니다. 이","keywords":["신석기 혁명","유목"],"ref":{"tab":"concepts","idx":1},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-01","grade":"h2"},
{"id":"hist-h-world-01#c2","kind":"concept","title":"농경과 정착이 가져온 변화 — 문명으로","text":"농경을 시작한 사람들은 밭 가까이에 움집을 짓고 모여 살며 마을을 이루었습니다. 곡식을 갈거나 땅을 일구는 간석기, 곡식을 저장하고 익혀 먹는 토기를 만들었고, 실을 뽑아 옷감을 짰습니다. 식량이 안정되자 인구가 늘었고, 쓰고 남는 잉여 생산물이 생겼습니다. 잉여 생산물을 더 많이 가진","keywords":["잉여 생산물","관개 농업"],"ref":{"tab":"concepts","idx":2},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-01","grade":"h2"},
{"id":"hist-h-world-01#c3","kind":"concept","title":"메소포타미아 문명과 이집트 문명","text":"메소포타미아 문명은 티그리스강과 유프라테스강 사이에서 기원전 3500년 무렵부터 발달했습니다. 수메르인이 우르·우루크 같은 도시 국가를 세우고, 도시 한가운데에 신전인 지구라트를 지었습니다. 점토판에 쐐기 문자를 새겼고, 60진법과 태음력을 썼습니다. 기원전 18세기 바빌로니아의 함무라","keywords":["쐐기 문자","지구라트"],"ref":{"tab":"concepts","idx":3},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-01","grade":"h2"},
{"id":"hist-h-world-01#c4","kind":"concept","title":"인더스 문명과 황허 문명","text":"인더스 문명은 기원전 2500년 무렵 인더스강 유역에서 번성했습니다. 대표 도시인 하라파와 모헨조다로는 바둑판처럼 반듯한 도로, 벽돌로 쌓은 집, 하수 시설, 큰 목욕탕을 갖춘 계획도시였습니다. 동물과 그림 문자를 새긴 인장이 많이 나왔고, 메소포타미아와 교역한 흔적도 있습니다. 그러나","keywords":["갑골 문자"],"ref":{"tab":"concepts","idx":4},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-01","grade":"h2"},
{"id":"hist-h-world-01#c5","kind":"concept","title":"아메리카의 고대 문명과 생태환경","text":"아메리카에서도 아프로유라시아와 따로 문명이 생겨났습니다. 올메카 문명: 기원전 1200년 무렵 멕시코만 연안에서 발달했습니다. 거대한 돌 두상과 신전을 남겼고, 뒤이은 메소아메리카 문명에 영향을 주었습니다. 마야 문명: 유카탄반도 일대의 열대 밀림에 피라미드 모양 신전을 중심으로 한 도","keywords":["계단식 밭"],"ref":{"tab":"concepts","idx":5},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-01","grade":"h2"},
{"id":"hist-h-world-01#t0","kind":"term","title":"현생 인류","text":"오늘날 인류와 같은 종인 호모 사피엔스를 말합니다. 아프리카에서 등장해 전 세계로 퍼졌습니다.","keywords":["현생 인류"],"ref":{"tab":"terms","idx":0},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-01","grade":"h2"},
{"id":"hist-h-world-01#t1","kind":"term","title":"고고학 자료","text":"유적과 유물처럼 옛사람이 남긴 물질 자료입니다. 문자가 없던 시대의 삶을 알아내는 근거가 됩니다. 예: 동굴 벽화, 무덤, 석기","keywords":["고고학 자료"],"ref":{"tab":"terms","idx":1},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-01","grade":"h2"},
{"id":"hist-h-world-01#t2","kind":"term","title":"신석기 혁명","text":"약 1만 년 전부터 인류가 농경과 목축으로 식량을 스스로 생산하게 된 큰 변화입니다. 농업 혁명이라고도 합니다.","keywords":["신석기 혁명"],"ref":{"tab":"terms","idx":2},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-01","grade":"h2"},
{"id":"hist-h-world-01#t3","kind":"term","title":"유목","text":"비가 적은 초원에서 가축을 기르며 풀과 물을 따라 옮겨 다니는 생활 방식입니다.","keywords":["유목"],"ref":{"tab":"terms","idx":3},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-01","grade":"h2"},
{"id":"hist-h-world-01#t4","kind":"term","title":"잉여 생산물","text":"쓰고 남는 생산물입니다. 농경으로 잉여 생산물이 생기면서 사유 재산과 계층 분화가 나타났습니다.","keywords":["잉여 생산물"],"ref":{"tab":"terms","idx":4},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-01","grade":"h2"},
{"id":"hist-h-world-01#t5","kind":"term","title":"관개 농업","text":"강이나 저수지의 물을 물길로 끌어와 농사짓는 방법입니다. 큰 강 유역 문명의 바탕이 되었습니다.","keywords":["관개 농업"],"ref":{"tab":"terms","idx":5},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-01","grade":"h2"},
{"id":"hist-h-world-01#t6","kind":"term","title":"쐐기 문자","text":"메소포타미아에서 점토판에 갈대 끝을 눌러 새긴 문자입니다. 글자 모양이 쐐기 같아 붙은 이름이며, 설형 문자라고도 합니다.","keywords":["쐐기 문자"],"ref":{"tab":"terms","idx":6},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-01","grade":"h2"},
{"id":"hist-h-world-01#t7","kind":"term","title":"지구라트","text":"메소포타미아 도시 국가의 중심에 벽돌을 층층이 쌓아 세운 신전입니다.","keywords":["지구라트"],"ref":{"tab":"terms","idx":7},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-01","grade":"h2"},
{"id":"hist-h-world-01#t8","kind":"term","title":"갑골 문자","text":"상 왕조에서 거북 껍데기나 짐승 뼈에 점친 내용을 새긴 문자입니다. 한자의 뿌리가 되었습니다.","keywords":["갑골 문자"],"ref":{"tab":"terms","idx":8},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-01","grade":"h2"},
{"id":"hist-h-world-01#t9","kind":"term","title":"계단식 밭","text":"산비탈을 계단처럼 깎아 만든 밭입니다. 안데스 문명이 고원 지대에서 농사짓기 위해 만들었습니다.","keywords":["계단식 밭"],"ref":{"tab":"terms","idx":9},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-01","grade":"h2"},
{"id":"hist-h-world-01#f0","kind":"faq","title":"신석기 혁명이 왜 \"혁명\"이에요? 갑자기 일어난 일도 아니라던데요.","text":"맞습니다. 농경은 수천 년에 걸쳐 천천히 퍼졌습니다. 그래도 \"혁명\"이라고 부르는 까닭은 결과가 그만큼 컸기 때문입니다. 식량을 찾아다니던 삶이 식량을 만드는 삶으로 바뀌면서 정착, 인구 증가, 계층 분화, 국가와 문명까지 이어졌습니다.","keywords":["신석기 혁명"],"ref":{"tab":"faq","idx":0},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-01","grade":"h2"},
{"id":"hist-h-world-01#f1","kind":"faq","title":"이집트 문명과 메소포타미아 문명은 무엇이 가장 달라요?","text":"환경에서 출발해 비교하면 쉽습니다. 이집트는 사막에 둘러싸여 침입이 적고 나일강이 규칙적으로 범람해 통일 왕국이 오래 이어졌고, 내세를 중시했습니다. 메소포타미아는 트인 평야라 침입이 잦아 나라가 자주 바뀌었고, 현세를 중시하는 경향이 있었습니다.","keywords":[],"ref":{"tab":"faq","idx":1},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-01","grade":"h2"},
{"id":"hist-h-world-01#f2","kind":"faq","title":"인더스 문명은 왜 사라졌어요?","text":"확실히 밝혀지지 않았습니다. 기원전 1800년 무렵부터 도시들이 쇠퇴했는데, 강줄기가 바뀌거나 기후가 건조해지는 등 환경 변화가 원인으로 거론됩니다. 문자를 읽지 못해 당시 기록으로 확인할 수 없다는 점도 수수께끼를 키웁니다.","keywords":[],"ref":{"tab":"faq","idx":2},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-01","grade":"h2"},
{"id":"hist-h-world-01#m0","kind":"mistake","title":"자주 하는 실수","text":"쐐기 문자(메소포타미아)와 갑골 문자(상), 이집트 상형 문자를 서로 바꿔 기억하는 실수 — \"점토판에 눌러 새김 = 쐐기 문자, 거북 껍데기·뼈 = 갑골 문자\"로 재료와 함께 묶어 기억합니다.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-01","grade":"h2"},
{"id":"hist-h-world-01#m1","kind":"mistake","title":"자주 하는 실수","text":"농경이 시작되자 모든 사람이 평등해졌다고 생각하는 실수 — 잉여 생산물이 생기면서 오히려 사유 재산과 계층 분화가 나타났습니다.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-01","grade":"h2"},
{"id":"hist-h-world-01#m2","kind":"mistake","title":"자주 하는 실수","text":"아메리카 문명도 철기와 말을 썼다고 생각하는 실수 — 아메리카 고대 문명은 수레를 끄는 큰 가축과 철기 없이 발전했습니다.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-01","grade":"h2"},
{"id":"hist-h-world-02","kind":"unit","title":"동아시아 세계와 인도 세계","text":"유교·불교·한자·율령을 함께한 동아시아 세계와 불교·힌두교의 인도 세계가 형성되고 서로 영향을 주고받은 모습을 살펴봅니다. 아리아인의 이동부터 마우리아·쿠샨·굽타 왕조까지 인도 세계의 형성 과정을 설명할 수 있다. 불교와 힌두교의 성립과 특징을 비교할 수 있다. 주에서 수·당까지 중국 고대 국가의 변화와 유교의 성립을 설명할 수 있다. 동아시아 문화권의 …","keywords":["바르나(카스트)","브라만교","상좌부 불교","대승 불교","간다라 미술","힌두교","제자백가","군현제","율령","구법승"],"ref":{"tab":"concepts","idx":0},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-02","grade":"h2"},
{"id":"hist-h-world-02#c0","kind":"concept","title":"인도 세계의 형성 — 브라만교, 카스트, 불교","text":"기원전 1500년 무렵 아리아인이 인도 서북부로 들어와 원주민을 정복하고, 뒤에 갠지스강 유역으로 퍼져 나갔습니다. 아리아인은 경전 「베다」를 바탕으로 제사를 중시하는 브라만교를 믿었습니다. 정복 과정에서 엄격한 신분 제도인 바르나(흔히 카스트라고 부름)가 생겼습니다. 신분 · 하는 일","keywords":["브라만교"],"ref":{"tab":"concepts","idx":0},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-02","grade":"h2"},
{"id":"hist-h-world-02#c1","kind":"concept","title":"마우리아 왕조와 쿠샨 왕조 — 불교의 발전과 전파","text":"기원전 4세기 말 마우리아 왕조가 북인도를 통일했습니다. 기원전 3세기 아소카왕은 남쪽 끝을 뺀 인도 대부분을 다스리며, 정복 전쟁의 참상을 반성하고 불교를 장려했습니다. 왕의 가르침을 돌기둥과 바위에 새겨 세우고, 불교 경전을 정리하게 했으며, 스리랑카 등지에 불교를 전했습니다. 이 ","keywords":["상좌부 불교","대승 불교"],"ref":{"tab":"concepts","idx":1},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-02","grade":"h2"},
{"id":"hist-h-world-02#c2","kind":"concept","title":"굽타 왕조와 힌두교, 인도 고전 문화","text":"4세기 초 굽타 왕조가 북인도를 다시 통일했습니다. 굽타 왕조는 인도 고유의 전통을 중시했습니다. 이 시기에 힌두교가 자리 잡았습니다. 힌두교는 브라만교에 여러 민간 신앙과 불교의 요소가 더해진 종교로, 비슈누·시바 같은 여러 신을 섬기고, 각자 자기 카스트의 의무를 다하는 것을 중요하","keywords":["브라만교","힌두교"],"ref":{"tab":"concepts","idx":2},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-02","grade":"h2"},
{"id":"hist-h-world-02#c3","kind":"concept","title":"중국 고대 국가의 형성과 유교의 성립","text":"기원전 11세기 무렵 주가 상을 무너뜨리고 봉건제를 실시했습니다. 왕은 수도 주변만 직접 다스리고, 나머지 땅은 왕족과 공신을 제후로 삼아 다스리게 했습니다. 왕과 제후는 혈연과 예법으로 묶여 있었습니다. 기원전 770년 주가 수도를 동쪽으로 옮긴 뒤 왕실의 힘이 약해지고 제후들이 서로","keywords":["제자백가"],"ref":{"tab":"concepts","idx":3},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-02","grade":"h2"},
{"id":"hist-h-world-02#c4","kind":"concept","title":"위진 남북조의 분열과 수·당의 통일","text":"220년 한이 멸망한 뒤 589년 수가 통일할 때까지, 진(서진)이 잠시 통일한 시기를 빼면 중국은 오랫동안 여러 나라로 나뉘어 있었습니다. 이 시기를 위진 남북조 시대라고 합니다. 화북 지방에는 북방 유목 민족이 세운 나라들이 들어섰고(북조), 한족은 강남으로 옮겨 가 나라를 세웠습니","keywords":[],"ref":{"tab":"concepts","idx":4},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-02","grade":"h2"},
{"id":"hist-h-world-02#c5","kind":"concept","title":"동아시아 문화권과 불교를 통한 교류, 동남아시아","text":"당의 제도와 문화는 신라·발해·일본 등 주변 나라로 퍼졌습니다. 이 나라들은 당에 유학생과 승려를 보내고, 당의 제도를 자기 나라에 맞게 받아들였습니다. 그 결과 한자, 유교, 불교, 율령을 함께 나누는 동아시아 문화권이 형성되었습니다. 불교는 인도와 동아시아를 잇는 다리였습니다. 불교","keywords":["간다라 미술","힌두교","율령","구법승"],"ref":{"tab":"concepts","idx":5},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-02","grade":"h2"},
{"id":"hist-h-world-02#t0","kind":"term","title":"바르나(카스트)","text":"아리아인이 인도를 정복하며 만든 신분 제도입니다. 브라만·크샤트리아·바이샤·수드라로 나뉘며, 신분은 태어날 때 정해졌습니다.","keywords":["바르나(카스트)"],"ref":{"tab":"terms","idx":0},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-02","grade":"h2"},
{"id":"hist-h-world-02#t1","kind":"term","title":"브라만교","text":"아리아인이 「베다」를 경전으로 삼아 믿은 종교입니다. 제사를 중시했고 사제인 브라만이 가장 높은 신분이었습니다.","keywords":["브라만교"],"ref":{"tab":"terms","idx":1},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-02","grade":"h2"},
{"id":"hist-h-world-02#t2","kind":"term","title":"상좌부 불교","text":"개인의 수행과 해탈을 중시하는 불교입니다. 스리랑카와 동남아시아로 전해졌습니다.","keywords":["상좌부 불교"],"ref":{"tab":"terms","idx":2},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-02","grade":"h2"},
{"id":"hist-h-world-02#t3","kind":"term","title":"대승 불교","text":"많은 사람의 구제를 강조하는 불교입니다. 쿠샨 왕조 때 발달하여 중앙아시아를 거쳐 중국·한국·일본으로 전해졌습니다.","keywords":["대승 불교"],"ref":{"tab":"terms","idx":3},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-02","grade":"h2"},
{"id":"hist-h-world-02#t4","kind":"term","title":"간다라 미술","text":"쿠샨 왕조의 간다라 지방에서 그리스 조각 양식과 불교가 만나 생긴 불교 미술입니다. 사람 모습의 불상을 만들었습니다.","keywords":["간다라 미술"],"ref":{"tab":"terms","idx":4},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-02","grade":"h2"},
{"id":"hist-h-world-02#t5","kind":"term","title":"힌두교","text":"브라만교에 민간 신앙과 불교의 요소가 더해져 굽타 왕조 때 자리 잡은 종교입니다. 여러 신을 섬기고 카스트에 따른 의무를 중시합니다.","keywords":["힌두교"],"ref":{"tab":"terms","idx":5},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-02","grade":"h2"},
{"id":"hist-h-world-02#t6","kind":"term","title":"제자백가","text":"춘추 전국 시대에 나타난 여러 사상가와 학파입니다. 유가·도가·법가·묵가 등이 있습니다.","keywords":["제자백가"],"ref":{"tab":"terms","idx":6},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-02","grade":"h2"},
{"id":"hist-h-world-02#t7","kind":"term","title":"군현제","text":"전국을 군과 현으로 나누고 중앙에서 관리를 보내 다스리는 제도입니다. 진이 전국에 실시했습니다.","keywords":["군현제"],"ref":{"tab":"terms","idx":7},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-02","grade":"h2"},
{"id":"hist-h-world-02#t8","kind":"term","title":"율령","text":"나라를 다스리는 법 체계입니다. 율은 형벌에 관한 법, 령은 행정에 관한 법입니다. 당의 율령은 동아시아 여러 나라에 영향을 주었습니다.","keywords":["율령"],"ref":{"tab":"terms","idx":8},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-02","grade":"h2"},
{"id":"hist-h-world-02#t9","kind":"term","title":"구법승","text":"불교의 가르침을 구하러 인도로 떠난 승려입니다. 법현, 현장, 신라의 혜초가 대표적입니다.","keywords":["구법승"],"ref":{"tab":"terms","idx":9},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-02","grade":"h2"},
{"id":"hist-h-world-02#f0","kind":"faq","title":"불교는 인도에서 생겼는데 왜 지금 인도에는 불교 신자가 적어요?","text":"굽타 왕조 무렵부터 힌두교가 널리 퍼졌기 때문입니다. 힌두교는 불교의 요소까지 받아들여 많은 사람을 끌어들였고, 왕조의 후원도 받았습니다. 그 뒤 불교는 인도에서 점차 세력을 잃었지만, 스리랑카·동남아시아와 동아시아에서는 크게 발전했습니다.","keywords":[],"ref":{"tab":"faq","idx":0},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-02","grade":"h2"},
{"id":"hist-h-world-02#f1","kind":"faq","title":"봉건제랑 군현제는 뭐가 달라요?","text":"누가 지방을 다스리느냐가 다릅니다. 주의 봉건제는 왕족과 공신을 제후로 삼아 땅을 맡겼기 때문에 제후의 힘이 커질 수 있었습니다. 진의 군현제는 황제가 관리를 직접 보내고 바꿀 수 있어 황제의 힘이 강했습니다.","keywords":["군현제"],"ref":{"tab":"faq","idx":1},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-02","grade":"h2"},
{"id":"hist-h-world-02#f2","kind":"faq","title":"대승 불교와 상좌부 불교는 어떻게 구분해요?","text":"무엇을 강조하고 어디로 퍼졌는지로 구분합니다. 상좌부 불교는 개인의 수행과 해탈을 중시하고 스리랑카·동남아시아로 퍼졌습니다. 대승 불교는 많은 사람의 구제를 강조하며 쿠샨 왕조 때 발달해 중앙아시아를 거쳐 중국·한국·일본으로 전해졌습니다.","keywords":["상좌부 불교","대승 불교"],"ref":{"tab":"faq","idx":2},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-02","grade":"h2"},
{"id":"hist-h-world-02#m0","kind":"mistake","title":"자주 하는 실수","text":"대승 불교와 상좌부 불교가 퍼진 방향을 바꿔 기억하는 실수 — 대승은 북쪽 길(중앙아시아 → 중국·한국·일본), 상좌부는 남쪽 길(스리랑카·동남아시아)입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-02","grade":"h2"},
{"id":"hist-h-world-02#m1","kind":"mistake","title":"자주 하는 실수","text":"간다라 미술을 굽타 왕조의 것으로 착각하는 실수 — 그리스 양식의 간다라 미술은 쿠샨 왕조, 인도 고유 양식의 굽타 양식은 굽타 왕조입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-02","grade":"h2"},
{"id":"hist-h-world-02#m2","kind":"mistake","title":"자주 하는 실수","text":"주의 봉건제와 진의 군현제를 혼동하는 실수 — 땅을 제후에게 \"맡기면\" 봉건제, 관리를 \"보내면\" 군현제입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-02","grade":"h2"},
{"id":"hist-h-world-03","kind":"unit","title":"페르시아와 그리스·로마 세계","text":"페르시아와 그리스·로마의 여러 정치 체제가 발전하며 사람들의 세계관과 종교가 어떻게 바뀌었는지 분석합니다. 페르시아 제국의 통치 방식과 조로아스터교, 파르티아·사산 왕조의 역할을 설명할 수 있다. 아테네 민주정의 구성 원리와 한계를 설명할 수 있다. 헬레니즘 세계의 형성과 세계 시민주의를 이해할 수 있다. 로마의 공화정과 제정, 로마법, 크리스트교의 확산…","keywords":["조로아스터교","왕의 길","폴리스","도편 추방제","직접 민주정","헬레니즘 문화","세계 시민주의","호민관","만민법","밀라노 칙령"],"ref":{"tab":"concepts","idx":0},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-03","grade":"h2"},
{"id":"hist-h-world-03#c0","kind":"concept","title":"페르시아 제국의 통치와 조로아스터교","text":"기원전 6세기 중엽 이란고원에서 일어난 아케메네스 왕조 페르시아는 서아시아를 통일했고, 다리우스 1세 때 이집트에서 인더스강에 이르는 대제국을 이루었습니다. 넓은 제국을 다스린 방법은 다음과 같습니다. 전국을 20여 개의 주로 나누고 총독을 보내 다스렸습니다. \"왕의 눈\", \"왕의 귀\"","keywords":["조로아스터교","왕의 길"],"ref":{"tab":"concepts","idx":0},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-03","grade":"h2"},
{"id":"hist-h-world-03#c1","kind":"concept","title":"파르티아와 사산 왕조 — 동서 교류의 중심","text":"알렉산드로스 제국이 나뉜 뒤, 기원전 3세기 중엽 이란 지역에서 파르티아가 일어났습니다. 파르티아는 동쪽의 한과 서쪽의 로마 사이에 자리 잡고 비단길의 중계 무역으로 번성했으며, 로마와 자주 맞섰습니다. 중국에는 \"안식\"이라는 이름으로 알려졌습니다. 226년 파르티아를 무너뜨린 사산 왕","keywords":["조로아스터교"],"ref":{"tab":"concepts","idx":1},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-03","grade":"h2"},
{"id":"hist-h-world-03#c2","kind":"concept","title":"그리스 폴리스와 아테네 민주정","text":"기원전 8세기 무렵 그리스에는 폴리스라는 작은 도시 국가가 여럿 생겼습니다. 폴리스는 언덕 위의 신전(아크로폴리스)과 시민이 모이는 광장(아고라)을 중심으로 이루어졌고, 같은 언어와 신앙, 올림피아 제전으로 하나의 그리스라는 의식을 나누었습니다. 대표적인 폴리스가 아테네와 스파르타입니다","keywords":["폴리스","도편 추방제"],"ref":{"tab":"concepts","idx":2},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-03","grade":"h2"},
{"id":"hist-h-world-03#c3","kind":"concept","title":"헬레니즘 세계와 세계 시민주의","text":"펠로폰네소스 전쟁(기원전 431~기원전 404년) 뒤 폴리스들은 서로 다투며 약해졌고, 북쪽의 마케도니아가 그리스를 장악했습니다. 기원전 334년 알렉산드로스는 동방 원정에 나서 페르시아를 무너뜨리고, 이집트에서 인도 서북부에 이르는 대제국을 세웠습니다. 그가 죽은 뒤 제국은 여러 나라","keywords":["폴리스","헬레니즘 문화","세계 시민주의"],"ref":{"tab":"concepts","idx":3},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-03","grade":"h2"},
{"id":"hist-h-world-03#c4","kind":"concept","title":"로마의 공화정과 제정, 로마법","text":"로마는 기원전 509년 왕을 몰아내고 공화정을 시작했습니다. 임기 1년의 집정관 2명이 나라를 이끌고, 귀족으로 이루어진 원로원이 큰 권한을 가졌습니다. 전쟁에서 중요한 역할을 한 평민들은 권리를 요구하여 평민을 보호하는 호민관과 평민회를 두었고, 법을 글로 적은 12표법을 얻어 냈습니","keywords":["호민관"],"ref":{"tab":"concepts","idx":4},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-03","grade":"h2"},
{"id":"hist-h-world-03#c5","kind":"concept","title":"크리스트교의 성립과 로마 제국 안에서의 확산","text":"1세기 초 로마의 지배를 받던 팔레스타인에서 예수가 가르침을 폈습니다. 예수는 유대교를 바탕으로 하면서도, 형식적인 율법과 유대인만 구원받는다는 생각(선민사상)을 비판하고 신의 사랑과 이웃 사랑을 가르쳤습니다. 예수가 십자가에 처형된 뒤 제자들은 그가 부활했다고 믿고 그를 구세주(그리스","keywords":[],"ref":{"tab":"concepts","idx":5},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-03","grade":"h2"},
{"id":"hist-h-world-03#t0","kind":"term","title":"조로아스터교","text":"페르시아에서 발달한 종교입니다. 선한 신과 악한 신의 대립, 최후의 심판을 가르쳤고 불을 신성하게 여겨 배화교라고도 합니다.","keywords":["조로아스터교"],"ref":{"tab":"terms","idx":0},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-03","grade":"h2"},
{"id":"hist-h-world-03#t1","kind":"term","title":"왕의 길","text":"아케메네스 왕조 페르시아가 수도 수사에서 소아시아의 사르디스까지 닦은 도로입니다. 역참을 두어 명령과 정보를 빠르게 전했습니다.","keywords":["왕의 길"],"ref":{"tab":"terms","idx":1},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-03","grade":"h2"},
{"id":"hist-h-world-03#t2","kind":"term","title":"폴리스","text":"고대 그리스의 도시 국가입니다. 아크로폴리스(신전)와 아고라(광장)를 중심으로 이루어졌습니다. 예: 아테네, 스파르타","keywords":["폴리스"],"ref":{"tab":"terms","idx":2},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-03","grade":"h2"},
{"id":"hist-h-world-03#t3","kind":"term","title":"도편 추방제","text":"아테네에서 독재자가 될 위험이 있는 사람의 이름을 도자기 조각에 써서 투표하고, 많이 나온 사람을 나라 밖으로 내보낸 제도입니다.","keywords":["도편 추방제"],"ref":{"tab":"terms","idx":3},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-03","grade":"h2"},
{"id":"hist-h-world-03#t4","kind":"term","title":"직접 민주정","text":"시민이 대표를 거치지 않고 직접 모여 나라의 일을 결정하는 정치입니다. 아테네의 민회가 대표적입니다.","keywords":["직접 민주정"],"ref":{"tab":"terms","idx":4},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-03","grade":"h2"},
{"id":"hist-h-world-03#t5","kind":"term","title":"헬레니즘 문화","text":"알렉산드로스의 원정 이후 그리스 문화와 오리엔트 문화가 어우러져 생긴 문화입니다. 세계 시민주의와 자연 과학이 발달했습니다.","keywords":["헬레니즘 문화"],"ref":{"tab":"terms","idx":5},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-03","grade":"h2"},
{"id":"hist-h-world-03#t6","kind":"term","title":"세계 시민주의","text":"폴리스의 테두리를 넘어 자신을 세계의 시민으로 여기는 생각입니다. 헬레니즘 시대에 나타났습니다.","keywords":["세계 시민주의"],"ref":{"tab":"terms","idx":6},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-03","grade":"h2"},
{"id":"hist-h-world-03#t7","kind":"term","title":"호민관","text":"로마 공화정에서 평민의 권리를 지키기 위해 둔 관직입니다.","keywords":["호민관"],"ref":{"tab":"terms","idx":7},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-03","grade":"h2"},
{"id":"hist-h-world-03#t8","kind":"term","title":"만민법","text":"로마 시민뿐 아니라 제국 안의 여러 민족에게 두루 적용된 로마의 법입니다. 시민법에서 발전했습니다.","keywords":["만민법"],"ref":{"tab":"terms","idx":8},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-03","grade":"h2"},
{"id":"hist-h-world-03#t9","kind":"term","title":"밀라노 칙령","text":"313년 로마의 콘스탄티누스 황제가 크리스트교를 공인한 칙령입니다.","keywords":["밀라노 칙령"],"ref":{"tab":"terms","idx":9},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-03","grade":"h2"},
{"id":"hist-h-world-03#f0","kind":"faq","title":"그리스 문화와 헬레니즘 문화는 뭐가 달라요?","text":"그리스 문화는 폴리스 안에서 발달한 문화로, 균형과 조화를 중시하고 시민 공동체를 바탕으로 했습니다. 헬레니즘 문화는 알렉산드로스의 원정 뒤 그리스 문화가 오리엔트 문화와 어우러진 것으로, 세계 시민주의와 개인의 행복을 중시하고 자연 과학이 크게 발달했습니다.","keywords":["헬레니즘 문화"],"ref":{"tab":"faq","idx":0},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-03","grade":"h2"},
{"id":"hist-h-world-03#f1","kind":"faq","title":"로마 공화정의 집정관은 왕이랑 뭐가 달라요?","text":"집정관은 2명이었고 임기가 1년이었습니다. 한 사람이 오래 권력을 쥐지 못하도록 서로 견제하게 한 것입니다. 왕은 한 사람이 평생 다스리고 자리를 물려주는 경우가 많았다는 점에서 다릅니다.","keywords":[],"ref":{"tab":"faq","idx":1},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-03","grade":"h2"},
{"id":"hist-h-world-03#f2","kind":"faq","title":"밀라노 칙령 때 크리스트교가 로마의 국교가 된 거 아니에요?","text":"아닙니다. 313년 밀라노 칙령은 크리스트교를 믿어도 된다고 공식적으로 인정(공인)한 것입니다. 크리스트교가 로마 제국의 국교가 된 것은 4세기 말 테오도시우스 황제 때입니다.","keywords":["밀라노 칙령"],"ref":{"tab":"faq","idx":2},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-03","grade":"h2"},
{"id":"hist-h-world-03#m0","kind":"mistake","title":"자주 하는 실수","text":"아케메네스 왕조와 사산 왕조를 섞어 기억하는 실수 — \"왕의 길·관용 정책·알렉산드로스에게 멸망\"은 아케메네스, \"조로아스터교 국교·페르시아 전통 부흥·이슬람에 멸망\"은 사산입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-03","grade":"h2"},
{"id":"hist-h-world-03#m1","kind":"mistake","title":"자주 하는 실수","text":"아테네 직접 민주정에 모든 주민이 참여했다고 생각하는 실수 — 여성·노예·외국인은 빠졌습니다.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-03","grade":"h2"},
{"id":"hist-h-world-03#m2","kind":"mistake","title":"자주 하는 실수","text":"크리스트교의 공인(313년 밀라노 칙령)과 국교화(4세기 말 테오도시우스 황제)를 같은 일로 보는 실수입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-03","grade":"h2"},
{"id":"hist-h-world-04","kind":"unit","title":"크리스트교 세계와 이슬람 세계","text":"비잔티움 제국과 서유럽, 이슬람 세계가 형성된 과정과 두 세계가 교류하고 부딪치며 만들어 낸 변화를 이해합니다. 비잔티움 제국과 서유럽 크리스트교 세계가 형성된 과정과 특징을 비교할 수 있다. 봉건 사회의 구조와 교황권의 성장을 설명할 수 있다. 이슬람교의 성립과 칼리프 체제, 우마이야·아바스 왕조의 특징을 설명할 수 있다. 십자군 전쟁과 지중해 교류가 …","keywords":["황제 교황주의","그리스 정교","주종 관계","장원","농노","카노사의 굴욕","헤지라","칼리프","십자군 전쟁","인문주의"],"ref":{"tab":"concepts","idx":0},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-04","grade":"h2"},
{"id":"hist-h-world-04#c0","kind":"concept","title":"비잔티움 제국과 그리스 정교 세계","text":"로마 제국이 동서로 나뉜 뒤 동쪽의 로마 제국을 비잔티움 제국이라고 합니다. 수도 콘스탄티노폴리스는 아시아와 유럽을 잇는 길목에 있어 교역의 중심지로 번영했고, 비잔티움 제국은 서로마 제국이 멸망한 뒤에도 1000년 가까이 이어졌습니다. 황제 교황주의: 황제가 정치뿐 아니라 교회의 일까","keywords":["황제 교황주의","그리스 정교"],"ref":{"tab":"concepts","idx":0},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-04","grade":"h2"},
{"id":"hist-h-world-04#c1","kind":"concept","title":"프랑크 왕국과 서유럽 크리스트교 세계의 형성","text":"4세기 후반부터 게르만족이 로마 제국 안으로 대규모로 옮겨 와 여러 나라를 세웠습니다. 476년 서로마 제국이 멸망한 뒤, 게르만족이 세운 나라 가운데 프랑크 왕국이 가장 크게 성장했습니다. 5세기 말 클로비스: 프랑크 왕국을 세우고 로마 가톨릭으로 개종하여 로마 교회와 옛 로마 주민의","keywords":[],"ref":{"tab":"concepts","idx":1},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-04","grade":"h2"},
{"id":"hist-h-world-04#c2","kind":"concept","title":"서유럽 봉건 사회와 교황권","text":"9~10세기 노르만족·마자르족·이슬람 세력이 서유럽을 침입했지만, 왕은 백성을 제대로 지켜 주지 못했습니다. 사람들은 가까운 힘 있는 자에게 보호를 구했고, 그 결과 봉건 제도가 자리 잡았습니다. 주종 관계: 주군은 봉신에게 땅(봉토)을 주고 보호하며, 봉신은 주군에게 충성과 군사 봉사","keywords":["주종 관계","장원","농노"],"ref":{"tab":"concepts","idx":2},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-04","grade":"h2"},
{"id":"hist-h-world-04#c3","kind":"concept","title":"이슬람교의 성립과 이슬람 세계의 형성","text":"7세기 초 아라비아반도의 상업 도시 메카에서 무함마드가 유일신 알라의 가르침을 전하며 이슬람교를 창시했습니다. 이슬람교는 알라 앞에서 모든 신자가 평등하다고 가르쳤고, 우상 숭배를 금지했습니다. 메카 지배층의 박해를 받은 무함마드는 622년 메디나로 옮겼는데, 이를 헤지라(성스러운 이주","keywords":["헤지라","칼리프"],"ref":{"tab":"concepts","idx":3},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-04","grade":"h2"},
{"id":"hist-h-world-04#c4","kind":"concept","title":"십자군 전쟁과 지중해를 통한 교류","text":"11세기 셀주크 튀르크가 크리스트교의 성지 예루살렘을 장악하고 비잔티움 제국을 위협했습니다. 비잔티움 황제가 도움을 청하자 교황 우르바누스 2세는 1095년 클레르몽 공의회에서 성지를 되찾자고 호소했고, 1096년 십자군이 원정에 나섰습니다. 제1차 십자군은 1099년 예루살렘을 점령했","keywords":["십자군 전쟁"],"ref":{"tab":"concepts","idx":4},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-04","grade":"h2"},
{"id":"hist-h-world-04#c5","kind":"concept","title":"중세 서유럽 사회의 동요와 르네상스","text":"14세기 무렵 서유럽의 중세 사회는 크게 흔들렸습니다. 교황권의 약화 14세기 초 프랑스 왕이 교황청을 남프랑스의 아비뇽으로 옮기게 하여, 교황이 프랑스 왕의 영향 아래 놓였습니다(아비뇽 유수, 1309~1377년). 그 뒤 교황이 두 명, 세 명씩 서로 정통을 주장하는 교회의 대분열이","keywords":["농노"],"ref":{"tab":"concepts","idx":5},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-04","grade":"h2"},
{"id":"hist-h-world-04#t0","kind":"term","title":"황제 교황주의","text":"비잔티움 제국에서 황제가 정치뿐 아니라 교회의 일까지 지배한 체제입니다.","keywords":["황제 교황주의"],"ref":{"tab":"terms","idx":0},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-04","grade":"h2"},
{"id":"hist-h-world-04#t1","kind":"term","title":"그리스 정교","text":"1054년 로마 가톨릭과 나뉜 동쪽의 크리스트교입니다. 비잔티움 제국에서 발달해 동유럽·러시아로 퍼졌습니다.","keywords":["그리스 정교"],"ref":{"tab":"terms","idx":1},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-04","grade":"h2"},
{"id":"hist-h-world-04#t2","kind":"term","title":"주종 관계","text":"서유럽 봉건 사회에서 주군이 봉신에게 봉토를 주고, 봉신은 충성과 군사 봉사를 약속한 쌍무적 계약 관계입니다.","keywords":["주종 관계"],"ref":{"tab":"terms","idx":2},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-04","grade":"h2"},
{"id":"hist-h-world-04#t3","kind":"term","title":"장원","text":"중세 서유럽에서 영주가 다스린 농촌의 경제 단위입니다. 농노가 영주의 땅을 경작하고 공납을 바쳤습니다.","keywords":["장원"],"ref":{"tab":"terms","idx":3},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-04","grade":"h2"},
{"id":"hist-h-world-04#t4","kind":"term","title":"농노","text":"장원에 매여 영주에게 부역과 공납을 바친 농민입니다. 이동의 자유는 없었지만 노예와 달리 가족과 재산을 가질 수 있었습니다.","keywords":["농노"],"ref":{"tab":"terms","idx":4},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-04","grade":"h2"},
{"id":"hist-h-world-04#t5","kind":"term","title":"카노사의 굴욕","text":"1077년 성직자 임명권을 두고 교황과 다투던 신성 로마 제국 황제 하인리히 4세가 파문을 풀어 달라고 카노사에서 용서를 빈 사건입니다.","keywords":["카노사의 굴욕"],"ref":{"tab":"terms","idx":5},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-04","grade":"h2"},
{"id":"hist-h-world-04#t6","kind":"term","title":"헤지라","text":"622년 무함마드가 박해를 피해 메카에서 메디나로 옮긴 일입니다. 이슬람력의 원년이 되었습니다.","keywords":["헤지라"],"ref":{"tab":"terms","idx":6},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-04","grade":"h2"},
{"id":"hist-h-world-04#t7","kind":"term","title":"칼리프","text":"무함마드의 후계자라는 뜻으로, 이슬람 공동체의 정치와 종교를 이끈 지도자입니다.","keywords":["칼리프"],"ref":{"tab":"terms","idx":7},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-04","grade":"h2"},
{"id":"hist-h-world-04#t8","kind":"term","title":"십자군 전쟁","text":"11세기 말부터 약 200년 동안 서유럽 크리스트교도들이 성지 예루살렘을 되찾겠다며 벌인 원정입니다.","keywords":["십자군 전쟁"],"ref":{"tab":"terms","idx":8},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-04","grade":"h2"},
{"id":"hist-h-world-04#t9","kind":"term","title":"인문주의","text":"르네상스의 바탕이 된 정신으로, 그리스·로마 고전을 연구하며 인간의 가치와 개성을 중시했습니다.","keywords":["인문주의"],"ref":{"tab":"terms","idx":9},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-04","grade":"h2"},
{"id":"hist-h-world-04#f0","kind":"faq","title":"서유럽의 봉건제랑 중국 주나라의 봉건제는 같은 거예요?","text":"이름은 같지만 성격이 다릅니다. 주의 봉건제는 왕이 혈연관계인 왕족과 공신에게 땅을 나누어 준 혈연 중심 제도입니다. 서유럽 봉건제는 주군과 봉신이 봉토와 충성·군사 봉사를 주고받기로 약속한 계약 중심 제도로, 혈연이 아니어도 맺어졌습니다.","keywords":[],"ref":{"tab":"faq","idx":0},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-04","grade":"h2"},
{"id":"hist-h-world-04#f1","kind":"faq","title":"수니파와 시아파는 왜 나뉘었어요?","text":"무함마드의 뒤를 이을 지도자를 누구로 볼 것인가를 두고 생각이 갈렸기 때문입니다. 시아파는 무함마드의 사촌이자 사위인 알리와 그 자손만이 정당한 지도자라고 보았고, 수니파는 공동체가 인정한 칼리프를 정당한 지도자로 받아들였습니다. 오늘날 이슬람교도 가운데 다수는 수니파입니다.","keywords":[],"ref":{"tab":"faq","idx":1},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-04","grade":"h2"},
{"id":"hist-h-world-04#f2","kind":"faq","title":"카노사의 굴욕이랑 아비뇽 유수가 자꾸 헷갈려요.","text":"누가 고개를 숙였는지 보면 됩니다. 카노사의 굴욕(1077년)은 황제가 교황에게 고개를 숙인 사건이라 교황권이 강해진 것을 보여 줍니다. 아비뇽 유수(14세기)는 교황이 프랑스 왕에게 휘둘린 사건이라 교황권이 약해진 것을 보여 줍니다.","keywords":["카노사의 굴욕"],"ref":{"tab":"faq","idx":2},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-04","grade":"h2"},
{"id":"hist-h-world-04#m0","kind":"mistake","title":"자주 하는 실수","text":"우마이야 왕조와 아바스 왕조를 바꿔 기억하는 실수 — \"다마스쿠스·세습 시작·아랍인 우대\"는 우마이야, \"바그다드·무슬림 평등·학문의 중심\"은 아바스입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-04","grade":"h2"},
{"id":"hist-h-world-04#m1","kind":"mistake","title":"자주 하는 실수","text":"십자군 전쟁으로 교황권이 강해졌다고 생각하는 실수 — 원정이 실패하면서 교황의 권위는 떨어지고 국왕의 권력이 강해졌습니다.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-04","grade":"h2"},
{"id":"hist-h-world-04#m2","kind":"mistake","title":"자주 하는 실수","text":"농노를 노예와 같다고 생각하는 실수 — 농노는 이동의 자유가 없었지만 가족을 이루고 재산을 가질 수 있었습니다.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-04","grade":"h2"},
{"id":"hist-h-world-05","kind":"unit","title":"이슬람 세계와 몽골 제국의 교류","text":"이슬람 세계의 확대와 송의 발전, 몽골 제국의 팽창으로 사람과 물건, 지식이 유라시아를 어떻게 오갔는지 살펴봅니다. 셀주크 튀르크의 성장과 인도·동남아시아의 이슬람화 과정을 설명할 수 있다. 이슬람 상인의 교역망을 따라 종이와 학문·과학이 전파된 과정을 이해할 수 있다. 송의 사대부 사회와 경제 발전, 요·금 같은 북방 민족의 성장을 설명할 수 있다. 몽…","keywords":["술탄","칼리프","사하라 횡단 교역","지혜의 집","사대부","이중 통치 체제","역참","몽골 제일주의","흑사병"],"ref":{"tab":"concepts","idx":0},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-05","grade":"h2"},
{"id":"hist-h-world-05#c0","kind":"concept","title":"이슬람 세계의 확대 — 셀주크 튀르크와 인도·동남아시아의 이슬람화","text":"8세기 중엽에 들어선 아바스 왕조는 10세기 무렵부터 힘이 약해졌습니다. 이때 중앙아시아에서 이슬람교를 받아들인 튀르크인이 서아시아로 진출했습니다. 11세기에 셀주크 튀르크는 1055년 바그다드에 들어가 아바스 왕조의 칼리프로부터 술탄(정치·군사 지배자)이라는 칭호를 받았습니다. 칼리프","keywords":["술탄","칼리프"],"ref":{"tab":"concepts","idx":0},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-05","grade":"h2"},
{"id":"hist-h-world-05#c1","kind":"concept","title":"이슬람 상인의 교역망과 문화의 전파","text":"이슬람 세계는 아시아·아프리카·유럽을 잇는 자리에 있었고, 이슬람교는 상업을 정당한 일로 존중했습니다. 그래서 무슬림 상인이 넓은 교역망을 만들었습니다. 인도양 바닷길: 계절풍(몬순)을 이용해 다우선을 타고 동아프리카·인도·동남아시아를 거쳐 중국의 광저우·취안저우까지 오갔습니다. 사하라","keywords":["사하라 횡단 교역","지혜의 집"],"ref":{"tab":"concepts","idx":1},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-05","grade":"h2"},
{"id":"hist-h-world-05#c2","kind":"concept","title":"송의 발전과 북방 민족의 성장","text":"960년 조광윤(태조)이 송을 세웠습니다. 송은 당 말기 절도사(지방 군사 지휘관)의 반란을 거울삼아 무신을 억누르고 문신을 우대하는 문치주의를 폈습니다. 과거제를 강화하여 황제가 직접 마지막 시험(전시)을 보았고, 과거로 관리가 된 학식 있는 지주층인 사대부가 사회를 이끌었습니다. 남","keywords":["사대부"],"ref":{"tab":"concepts","idx":2},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-05","grade":"h2"},
{"id":"hist-h-world-05#c3","kind":"concept","title":"몽골 제국의 팽창과 원의 통치","text":"1206년 테무친이 몽골 부족들을 통일하고 칭기즈 칸으로 추대되었습니다. 그는 유목민을 천 호 단위로 묶은 천호제로 군사와 행정을 정비하고 서하·금을 공격했으며, 중앙아시아의 호라즘을 정복했습니다. 그 뒤를 이은 칸들도 정복을 이어 갔습니다. 금을 무너뜨리고(1234), 바투는 러시아와","keywords":[],"ref":{"tab":"concepts","idx":3},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-05","grade":"h2"},
{"id":"hist-h-world-05#c4","kind":"concept","title":"몽골 제국 시기 유라시아의 교류","text":"몽골 제국이 유라시아 대부분을 하나로 묶고 역참으로 길을 정비하자, 사람과 물건, 지식이 이전보다 훨씬 자유롭게 오갔습니다. 여행자와 사절 마르코 폴로: 베네치아 출신. 쿠빌라이 칸 때 원에 머물렀고, 그의 이야기를 담은 「동방견문록」은 유럽인의 동방에 대한 관심을 키웠습니다. 이븐 바","keywords":["역참"],"ref":{"tab":"concepts","idx":4},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-05","grade":"h2"},
{"id":"hist-h-world-05#c5","kind":"concept","title":"교류가 가져온 변화와 흑사병의 확산","text":"활발한 교류는 문화를 풍부하게 했지만, 병도 함께 퍼뜨렸습니다. 14세기 중엽 흑사병(페스트)이 중앙아시아에서 교역로를 따라 퍼졌습니다. 흑해 연안을 거쳐 1347년 무렵 지중해의 항구로 들어간 흑사병은 몇 년 사이에 유럽 전역으로 번졌고, 유럽 인구의 약 3분의 1이 목숨을 잃었다고 ","keywords":["흑사병"],"ref":{"tab":"concepts","idx":5},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-05","grade":"h2"},
{"id":"hist-h-world-05#t0","kind":"term","title":"술탄","text":"이슬람 세계에서 정치·군사 권력을 가진 지배자의 칭호입니다. 셀주크 튀르크는 아바스 왕조의 칼리프에게서 이 칭호를 받아 실권을 쥐었습니다.","keywords":["술탄"],"ref":{"tab":"terms","idx":0},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-05","grade":"h2"},
{"id":"hist-h-world-05#t1","kind":"term","title":"칼리프","text":"무함마드의 후계자로서 이슬람 공동체를 이끄는 지도자입니다. 아바스 왕조 후기에는 종교적 권위만 남았습니다.","keywords":["칼리프"],"ref":{"tab":"terms","idx":1},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-05","grade":"h2"},
{"id":"hist-h-world-05#t2","kind":"term","title":"사하라 횡단 교역","text":"낙타를 탄 대상이 사하라 사막을 건너 북아프리카의 소금·직물과 서아프리카의 금을 바꾼 교역입니다.","keywords":["사하라 횡단 교역"],"ref":{"tab":"terms","idx":2},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-05","grade":"h2"},
{"id":"hist-h-world-05#t3","kind":"term","title":"지혜의 집","text":"아바스 왕조 때 바그다드에 세워진 학술 기관으로, 그리스·페르시아·인도의 책을 아랍어로 번역하고 연구했습니다.","keywords":["지혜의 집"],"ref":{"tab":"terms","idx":3},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-05","grade":"h2"},
{"id":"hist-h-world-05#t4","kind":"term","title":"사대부","text":"송에서 과거를 통해 관리가 된 학식 있는 지주층입니다. 성리학을 바탕으로 정치와 사회를 이끌었습니다.","keywords":["사대부"],"ref":{"tab":"terms","idx":4},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-05","grade":"h2"},
{"id":"hist-h-world-05#t5","kind":"term","title":"이중 통치 체제","text":"요(거란)가 유목민은 부족 제도로, 농경민(한족)은 중국식 제도로 따로 다스린 방식입니다.","keywords":["이중 통치 체제"],"ref":{"tab":"terms","idx":5},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-05","grade":"h2"},
{"id":"hist-h-world-05#t6","kind":"term","title":"역참","text":"몽골 제국이 도로를 따라 일정한 거리마다 말과 숙소를 갖추어 둔 교통·통신 시설입니다.","keywords":["역참"],"ref":{"tab":"terms","idx":6},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-05","grade":"h2"},
{"id":"hist-h-world-05#t7","kind":"term","title":"몽골 제일주의","text":"원이 몽골인을 가장 높이 두고 색목인·한인·남인 순으로 차등 대우한 민족 정책입니다.","keywords":["몽골 제일주의"],"ref":{"tab":"terms","idx":7},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-05","grade":"h2"},
{"id":"hist-h-world-05#t8","kind":"term","title":"흑사병","text":"14세기 중엽 유라시아에 퍼진 페스트입니다. 유럽 인구의 약 3분의 1이 목숨을 잃은 것으로 추정되며, 장원제 해체를 앞당겼습니다.","keywords":["흑사병"],"ref":{"tab":"terms","idx":8},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-05","grade":"h2"},
{"id":"hist-h-world-05#f0","kind":"faq","title":"칼리프랑 술탄은 뭐가 달라요?","text":"칼리프는 무함마드의 후계자로서 이슬람 공동체를 이끄는 종교·정치 지도자입니다. 술탄은 실제 정치·군사 권력을 가진 지배자의 칭호입니다. 아바스 왕조 후기에 셀주크 튀르크가 칼리프에게서 술탄 칭호를 받으면서, 칼리프는 종교적 권위를, 술탄은 실권을 나누어 갖게 되었습니다.","keywords":["술탄","칼리프"],"ref":{"tab":"faq","idx":0},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-05","grade":"h2"},
{"id":"hist-h-world-05#f1","kind":"faq","title":"송은 경제가 그렇게 발전했는데 왜 북방 민족에게 밀렸어요?","text":"송은 당 말기 절도사의 반란을 막으려고 무신을 억누르고 문신을 우대했습니다. 그 결과 정치는 안정되었지만 군사력이 약해졌습니다. 그래서 요·서하에게 해마다 비단과 은을 주며 평화를 유지했고, 결국 금에게 화북을 빼앗겼습니다.","keywords":[],"ref":{"tab":"faq","idx":1},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-05","grade":"h2"},
{"id":"hist-h-world-05#f2","kind":"faq","title":"몽골은 정복을 많이 했는데 왜 교류가 활발했다고 해요?","text":"정복 과정에서는 큰 파괴가 있었습니다. 하지만 정복이 끝난 뒤에는 넓은 지역이 한 세력 아래 묶여 길이 이어지고, 역참이 정비되었으며, 여러 민족과 종교에 대체로 너그러운 정책이 시행되었습니다. 그래서 상인·여행자·선교사가 이전보다 쉽게 오갈 수 있었습니다. 두 면을 함께 보아야 합니다.","keywords":[],"ref":{"tab":"faq","idx":2},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-05","grade":"h2"},
{"id":"hist-h-world-05#m0","kind":"mistake","title":"자주 하는 실수","text":"바그다드를 함락한 세력을 헷갈리는 실수 — 셀주크 튀르크는 1055년 바그다드에 \"들어가\" 술탄 칭호를 받았고, 몽골의 훌라구는 1258년 바그다드를 \"함락\"하여 아바스 왕조를 멸망시켰습니다.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-05","grade":"h2"},
{"id":"hist-h-world-05#m1","kind":"mistake","title":"자주 하는 실수","text":"요와 금을 바꿔 기억하는 실수 — 요는 거란, 금은 여진입니다. 금이 요를 무너뜨리고 송을 강남으로 밀어냈습니다.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-05","grade":"h2"},
{"id":"hist-h-world-05#m2","kind":"mistake","title":"자주 하는 실수","text":"몽골 제일주의의 순서를 헷갈리는 실수 — 몽골인 → 색목인 → 한인(화북) → 남인(강남) 순서입니다. 남송 출신인 남인이 가장 아래였습니다.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-05","grade":"h2"},
{"id":"hist-h-world-06","kind":"unit","title":"신항로 개척과 세계 교역","text":"신항로 개척과 재정·군사 국가의 경쟁, 은·설탕·차 같은 상품의 세계적 교역이 각 지역에 가져온 변화를 분석합니다. 신항로 개척의 배경과 전개 과정을 설명할 수 있다. 아메리카 정복과 콜럼버스의 교환이 여러 대륙에 준 영향을 설명할 수 있다. 종교 개혁 이후 유럽 재정·군사 국가의 경쟁과 중상주의를 이해할 수 있다. 은·설탕·차 등 세계적 상품 교역과 대…","keywords":["신항로 개척","콜럼버스의 교환","재정·군사 국가","중상주의","동인도 회사","갈레온 무역","플랜테이션","삼각 무역","가격 혁명"],"ref":{"tab":"concepts","idx":0},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-06","grade":"h2"},
{"id":"hist-h-world-06#c0","kind":"concept","title":"신항로 개척의 배경과 전개","text":"15세기 유럽에서는 음식, 특히 고기 요리의 맛을 내는 향신료(후추 등)의 수요가 컸습니다. 그런데 아시아 물품은 이슬람 상인과 이탈리아 상인을 거쳐 비싼 값에 들어왔고, 오스만 제국이 동지중해를 장악하면서 길이 더 어려워졌습니다. 그래서 유럽인은 아시아로 바로 가는 바닷길을 찾으려 했","keywords":["신항로 개척"],"ref":{"tab":"concepts","idx":0},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-06","grade":"h2"},
{"id":"hist-h-world-06#c1","kind":"concept","title":"아메리카 정복과 콜럼버스의 교환","text":"에스파냐는 아메리카의 문명을 정복했습니다. 코르테스는 아스테카 제국을(1521년), 피사로는 잉카 제국을(1533년) 무너뜨렸습니다. 소수의 에스파냐군이 이길 수 있었던 데에는 총과 말, 원주민 세력 사이의 갈등, 그리고 무엇보다 전염병이 큰 몫을 했습니다. 에스파냐는 식민지를 세우고 ","keywords":["신항로 개척","콜럼버스의 교환"],"ref":{"tab":"concepts","idx":1},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-06","grade":"h2"},
{"id":"hist-h-world-06#c2","kind":"concept","title":"종교 개혁 이후 재정·군사 국가의 경쟁과 중상주의","text":"1517년 루터가 교황청의 면벌부 판매를 비판하면서 종교 개혁이 시작되었습니다. 칼뱅의 개혁과 영국 국교회의 성립이 이어졌고, 유럽은 가톨릭과 프로테스탄트(신교)로 나뉘어 30년 전쟁(1618~1648년) 같은 종교 전쟁을 겪었습니다. 1648년 베스트팔렌 조약으로 여러 나라의 주권이 ","keywords":["재정·군사 국가","중상주의","동인도 회사"],"ref":{"tab":"concepts","idx":2},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-06","grade":"h2"},
{"id":"hist-h-world-06#c3","kind":"concept","title":"아메리카 은의 세계적 유통과 아시아 상품 교역","text":"16세기 중엽 에스파냐는 오늘날 볼리비아의 포토시 등에서 큰 은광을 개발했습니다. 일본에서도 은 생산이 크게 늘었습니다. 이 은이 세계를 돌며 교역을 이었습니다. 대서양 길: 아메리카 은이 에스파냐로 들어가 유럽 곳곳으로 퍼졌습니다. 태평양 길: 에스파냐는 필리핀의 마닐라를 거점으로 삼","keywords":["갈레온 무역"],"ref":{"tab":"concepts","idx":3},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-06","grade":"h2"},
{"id":"hist-h-world-06#c4","kind":"concept","title":"설탕 플랜테이션과 대서양 노예 무역","text":"유럽에서 설탕 수요가 커지자, 포르투갈은 브라질에, 영국·프랑스 등은 카리브해(서인도 제도)의 섬에 사탕수수를 대규모로 재배하는 플랜테이션을 세웠습니다. 플랜테이션은 유럽의 자본과 현지의 땅, 많은 노동력을 결합해 수출용 작물 한 가지를 대규모로 기르는 농장입니다. 원주민 인구가 크게 ","keywords":["플랜테이션","삼각 무역"],"ref":{"tab":"concepts","idx":4},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-06","grade":"h2"},
{"id":"hist-h-world-06#c5","kind":"concept","title":"세계적 상품 교역이 가져온 사회·경제 변화","text":"세계가 바닷길로 이어지면서 여러 지역의 삶이 크게 바뀌었습니다. 가격 혁명: 아메리카 은이 대량으로 들어오고 인구가 늘면서 16세기 유럽의 물가가 크게 올랐습니다. 정해진 지대를 받던 영주는 실질 수입이 줄어 어려워졌고, 상공업자는 이익을 보았습니다. 상업 혁명: 무역의 중심이 지중해에","keywords":["가격 혁명"],"ref":{"tab":"concepts","idx":5},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-06","grade":"h2"},
{"id":"hist-h-world-06#t0","kind":"term","title":"신항로 개척","text":"15~16세기 유럽인이 아시아와 아메리카로 가는 새 바닷길을 연 일입니다. 유럽인의 관점에서 \"대항해 시대\"라고도 합니다.","keywords":["신항로 개척"],"ref":{"tab":"terms","idx":0},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-06","grade":"h2"},
{"id":"hist-h-world-06#t1","kind":"term","title":"콜럼버스의 교환","text":"신항로 개척 이후 아메리카와 다른 대륙 사이에 작물·가축·질병이 오간 일입니다. 감자·옥수수는 아메리카에서, 말·소·천연두는 유럽에서 건너갔습니다.","keywords":["콜럼버스의 교환"],"ref":{"tab":"terms","idx":1},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-06","grade":"h2"},
{"id":"hist-h-world-06#t2","kind":"term","title":"재정·군사 국가","text":"세금과 국채로 큰돈을 모아 상비군과 관료제를 유지하며 다른 나라와 경쟁한 근대 초 유럽 국가를 말합니다.","keywords":["재정·군사 국가"],"ref":{"tab":"terms","idx":2},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-06","grade":"h2"},
{"id":"hist-h-world-06#t3","kind":"term","title":"중상주의","text":"나라의 부를 금·은으로 보고, 수출 장려·수입 억제, 국내 산업 보호, 식민지 확보로 금·은을 쌓으려 한 경제 정책입니다.","keywords":["중상주의"],"ref":{"tab":"terms","idx":3},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-06","grade":"h2"},
{"id":"hist-h-world-06#t4","kind":"term","title":"동인도 회사","text":"아시아 무역을 독점하도록 국가의 특허를 받은 회사입니다. 영국(1600년)과 네덜란드(1602년)가 대표적입니다.","keywords":["동인도 회사"],"ref":{"tab":"terms","idx":4},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-06","grade":"h2"},
{"id":"hist-h-world-06#t5","kind":"term","title":"갈레온 무역","text":"에스파냐가 멕시코 아카풀코와 필리핀 마닐라를 큰 범선으로 오가며 아메리카 은과 중국 물품을 바꾼 무역입니다.","keywords":["갈레온 무역"],"ref":{"tab":"terms","idx":5},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-06","grade":"h2"},
{"id":"hist-h-world-06#t6","kind":"term","title":"플랜테이션","text":"유럽인의 자본과 많은 노동력으로 사탕수수·담배·면화 같은 수출용 작물 한 가지를 대규모로 재배한 농장입니다.","keywords":["플랜테이션"],"ref":{"tab":"terms","idx":6},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-06","grade":"h2"},
{"id":"hist-h-world-06#t7","kind":"term","title":"삼각 무역","text":"유럽(무기·직물) → 아프리카(노예) → 아메리카(설탕·담배·면화) → 유럽으로 이어진 대서양 무역입니다.","keywords":["삼각 무역"],"ref":{"tab":"terms","idx":7},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-06","grade":"h2"},
{"id":"hist-h-world-06#t8","kind":"term","title":"가격 혁명","text":"16세기 아메리카 은의 대량 유입 등으로 유럽의 물가가 크게 오른 현상입니다. 영주는 어려워지고 상공업자는 성장했습니다.","keywords":["가격 혁명"],"ref":{"tab":"terms","idx":8},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-06","grade":"h2"},
{"id":"hist-h-world-06#f0","kind":"faq","title":"콜럼버스가 아메리카를 \"발견\"했다고 하면 안 돼요?","text":"아메리카에는 이미 수천만 명의 원주민이 살며 아스테카·잉카 같은 문명을 이루고 있었습니다. \"발견\"은 유럽인의 눈으로 본 표현이라, 요즘은 \"도착\", \"신항로 개척\" 같은 말을 함께 씁니다. 같은 사건도 누구의 관점에서 보느냐에 따라 의미가 달라진다는 점을 기억하면 좋습니다.","keywords":[],"ref":{"tab":"faq","idx":0},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-06","grade":"h2"},
{"id":"hist-h-world-06#f1","kind":"faq","title":"은이 많아졌는데 왜 오히려 영주는 가난해졌어요?","text":"은(돈)이 갑자기 많아지면 돈의 가치가 떨어져 물가가 오릅니다. 영주는 농민에게서 해마다 정해진 금액의 지대를 받았기 때문에, 물가가 오르자 같은 돈으로 살 수 있는 물건이 줄었습니다. 반대로 물건을 만들어 파는 상공업자는 오른 값에 팔아 이익을 보았습니다.","keywords":[],"ref":{"tab":"faq","idx":1},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-06","grade":"h2"},
{"id":"hist-h-world-06#f2","kind":"faq","title":"중상주의랑 재정·군사 국가는 어떤 관계예요?","text":"재정·군사 국가는 큰 군대를 유지하려고 많은 돈이 필요했습니다. 중상주의는 그 돈(금·은)을 모으는 경제 정책이었습니다. 곧, 나라 사이의 군사 경쟁이 중상주의라는 경제 경쟁과 식민지 쟁탈전으로 이어졌다고 이해하면 됩니다.","keywords":["재정·군사 국가","중상주의"],"ref":{"tab":"faq","idx":2},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-06","grade":"h2"},
{"id":"hist-h-world-06#m0","kind":"mistake","title":"자주 하는 실수","text":"콜럼버스와 바스쿠 다 가마를 바꿔 기억하는 실수 — 에스파냐 후원의 콜럼버스는 서쪽(대서양)으로 가서 아메리카에, 포르투갈의 바스쿠 다 가마는 아프리카를 돌아 인도에 도착했습니다.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-06","grade":"h2"},
{"id":"hist-h-world-06#m1","kind":"mistake","title":"자주 하는 실수","text":"콜럼버스의 교환에서 방향을 헷갈리는 실수 — 감자·옥수수·고추·토마토·담배는 아메리카에서 나왔고, 말·소·밀·사탕수수·천연두는 아메리카로 들어갔습니다.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-06","grade":"h2"},
{"id":"hist-h-world-06#m2","kind":"mistake","title":"자주 하는 실수","text":"가격 혁명을 \"물가가 내린 것\"으로 아는 실수 — 은이 많아져 물가가 크게 오른 현상입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-06","grade":"h2"},
{"id":"hist-h-world-07","kind":"unit","title":"명·청과 무굴·오스만 제국","text":"서구와 다른 방식으로 번영한 명·청, 무굴 제국, 오스만 제국이 여러 민족을 다스린 방법과 경제·문화의 변화를 이해합니다. 명의 통치와 대외 정책(조공·책봉, 해금, 정화의 항해)을 설명할 수 있다. 청의 다민족 통치 방식과 에도 막부 시기 일본의 대외 교류를 설명할 수 있다. 무굴 제국과 오스만 제국이 여러 종교·민족을 통합한 방식을 비교할 수 있다. …","keywords":["조공·책봉","해금","만한 병용제","번부","데지마","조닌","지즈야","밀레트","예니체리"],"ref":{"tab":"concepts","idx":0},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-07","grade":"h2"},
{"id":"hist-h-world-07#c0","kind":"concept","title":"명의 통치와 대외 정책","text":"원 말기의 혼란 속에서 주원장(홍무제)이 1368년 명을 세우고 몽골을 북쪽으로 몰아냈습니다. 홍무제는 재상 제도를 없애고 6부를 황제 직속으로 두어 황제권을 강화했습니다. 농촌은 이갑제로 묶어 세금을 걷고 질서를 지키게 했으며, 유교 윤리를 담은 육유를 반포해 백성을 교화했습니다. 명","keywords":["조공·책봉","해금"],"ref":{"tab":"concepts","idx":0},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-07","grade":"h2"},
{"id":"hist-h-world-07#c1","kind":"concept","title":"청의 다민족 통치와 경제 성장","text":"만주의 여진족은 누르하치가 후금을 세운 뒤 세력을 키웠고, 홍타이지 때 국호를 청으로 바꾸었습니다. 1644년 명이 멸망하자 청은 베이징에 들어가 중국을 지배했습니다. 강희제·옹정제·건륭제의 약 130년 동안 청은 전성기를 맞아 타이완·몽골·티베트·신장까지 아우르는 넓은 영토를 갖추었습","keywords":["만한 병용제","번부"],"ref":{"tab":"concepts","idx":1},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-07","grade":"h2"},
{"id":"hist-h-world-07#c2","kind":"concept","title":"에도 막부의 일본과 동아시아의 교류","text":"16세기 말 도요토미 히데요시가 일본을 통일하고 조선을 침략했으나(임진왜란) 실패했습니다. 그 뒤 도쿠가와 이에야스가 권력을 잡고 1603년 에도 막부를 열었습니다. 에도 막부는 쇼군이 전국의 다이묘(지방 영주)를 통제하는 막번 체제를 갖추었습니다. 다이묘가 정기적으로 에도에 와서 머물","keywords":["데지마"],"ref":{"tab":"concepts","idx":2},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-07","grade":"h2"},
{"id":"hist-h-world-07#c3","kind":"concept","title":"무굴 제국의 종교 정책과 인도·이슬람 문화의 융합","text":"1526년 중앙아시아에서 온 바부르가 북인도에 무굴 제국을 세웠습니다. 무굴 제국의 지배층은 이슬람교도였지만, 백성 대부분은 힌두교도였습니다. 그래서 종교 정책이 제국의 안정을 좌우했습니다. 황제 · 시기 · 종교 정책 · 결과 악바르 · 16세기 후반 · 비이슬람교도에게 걷던 인두세(","keywords":["지즈야"],"ref":{"tab":"concepts","idx":3},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-07","grade":"h2"},
{"id":"hist-h-world-07#c4","kind":"concept","title":"오스만 제국의 통합 방식과 번영","text":"13세기 말 소아시아에서 일어난 오스만 제국은 1453년 메흐메트 2세 때 콘스탄티노폴리스를 함락하여 비잔티움 제국을 멸망시키고, 이곳을 이스탄불로 바꾸어 수도로 삼았습니다. 16세기 초에는 이집트의 맘루크 왕조를 무너뜨리고 이슬람 성지 메카와 메디나를 보호하게 되었습니다. 술레이만 1","keywords":["지즈야","밀레트","예니체리"],"ref":{"tab":"concepts","idx":4},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-07","grade":"h2"},
{"id":"hist-h-world-07#c5","kind":"concept","title":"세 제국의 경제 발달과 세계 교역, 사회의 변화","text":"16~18세기 아시아의 제국들은 유럽에 뒤처진 곳이 아니라 세계 교역의 중심에서 번영했습니다. 명·청 농업: 양쯔강 하류(강남)에서는 목화·뽕나무 같은 상품 작물을 많이 길렀고, 쌀 생산의 중심은 양쯔강 중류(후난·후베이)로 옮겨 갔습니다. 수공업·상업: 징더전의 도자기, 쑤저우의 비단","keywords":[],"ref":{"tab":"concepts","idx":5},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-07","grade":"h2"},
{"id":"hist-h-world-07#t0","kind":"term","title":"조공·책봉","text":"주변 나라 군주가 중국 황제에게 예물을 바치고(조공), 황제가 그를 왕으로 인정한(책봉) 외교 관계입니다. 공식 무역의 통로이기도 했습니다.","keywords":["조공·책봉"],"ref":{"tab":"terms","idx":0},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-07","grade":"h2"},
{"id":"hist-h-world-07#t1","kind":"term","title":"해금","text":"명·청이 민간인의 해상 무역과 바다 출입을 금지하거나 제한한 정책입니다.","keywords":["해금"],"ref":{"tab":"terms","idx":1},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-07","grade":"h2"},
{"id":"hist-h-world-07#t2","kind":"term","title":"만한 병용제","text":"청이 중앙의 주요 관직에 만주족과 한족을 함께 임명한 제도입니다.","keywords":["만한 병용제"],"ref":{"tab":"terms","idx":2},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-07","grade":"h2"},
{"id":"hist-h-world-07#t3","kind":"term","title":"번부","text":"청이 몽골·티베트·신장 등을 이번원을 통해 다스리며, 현지 지배층과 고유 풍습을 인정한 지역입니다.","keywords":["번부"],"ref":{"tab":"terms","idx":3},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-07","grade":"h2"},
{"id":"hist-h-world-07#t4","kind":"term","title":"데지마","text":"에도 막부 시기 나가사키 앞바다의 인공 섬으로, 네덜란드 상인이 이곳에서만 무역할 수 있었습니다.","keywords":["데지마"],"ref":{"tab":"terms","idx":4},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-07","grade":"h2"},
{"id":"hist-h-world-07#t5","kind":"term","title":"조닌","text":"에도 시대 도시의 상인과 수공업자입니다. 경제력을 바탕으로 가부키·우키요에 같은 서민 문화를 키웠습니다.","keywords":["조닌"],"ref":{"tab":"terms","idx":5},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-07","grade":"h2"},
{"id":"hist-h-world-07#t6","kind":"term","title":"지즈야","text":"이슬람 국가가 비이슬람교도에게 걷은 인두세입니다. 무굴 제국의 악바르는 폐지했고 아우랑제브는 부활시켰습니다.","keywords":["지즈야"],"ref":{"tab":"terms","idx":6},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-07","grade":"h2"},
{"id":"hist-h-world-07#t7","kind":"term","title":"밀레트","text":"오스만 제국에서 비이슬람교도가 세금을 내고 자기 종교와 법·관습에 따라 자치를 누린 종교 공동체입니다.","keywords":["밀레트"],"ref":{"tab":"terms","idx":7},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-07","grade":"h2"},
{"id":"hist-h-world-07#t8","kind":"term","title":"예니체리","text":"오스만 제국이 크리스트교도 소년을 뽑아 이슬람교로 개종시키고 길러 낸 술탄의 상비 보병 부대입니다.","keywords":["예니체리"],"ref":{"tab":"terms","idx":8},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-07","grade":"h2"},
{"id":"hist-h-world-07#f0","kind":"faq","title":"정화가 바스쿠 다 가마보다 먼저 먼 바다에 나갔는데, 왜 중국은 유럽처럼 해외로 뻗어 나가지 않았어요?","text":"정화의 항해는 무역 이익이나 식민지가 아니라 명의 위엄을 알리고 조공 관계를 넓히려는 목적이었습니다. 큰 비용이 들었고, 북쪽 몽골의 위협이 더 급했기 때문에 원정은 중단되었습니다. 명은 민간 무역을 막는 해금 정책을 이어 갔습니다. 반면 유럽 나라들은 무역 이익과 나라 사이의 경쟁 때문에 계속 바다로 나갔습니다.","keywords":[],"ref":{"tab":"faq","idx":0},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-07","grade":"h2"},
{"id":"hist-h-world-07#f1","kind":"faq","title":"만주족은 수가 적었는데 어떻게 그렇게 오래 중국을 다스렸어요?","text":"청은 한족을 끌어들이는 회유책(만한 병용제, 과거제, 편찬 사업)과 반발을 누르는 강경책(변발 강요, 문자의 옥)을 함께 썼습니다. 또 몽골·티베트·신장 같은 지역은 번부로 삼아 그곳의 방식대로 다스렸습니다. 이렇게 지역과 민족에 맞춘 통치가 오랜 지배를 가능하게 했습니다.","keywords":[],"ref":{"tab":"faq","idx":1},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-07","grade":"h2"},
{"id":"hist-h-world-07#f2","kind":"faq","title":"밀레트랑 지즈야는 어떤 관계예요?","text":"지즈야는 이슬람 국가가 비이슬람교도에게 걷은 인두세입니다. 오스만 제국에서는 비이슬람교도가 이 세금을 내면 밀레트라는 종교 공동체를 이루어 자기 종교와 법에 따라 살 수 있었습니다. 곧, 세금을 내는 대신 종교의 자유와 자치를 보장받은 셈입니다.","keywords":["지즈야","밀레트"],"ref":{"tab":"faq","idx":2},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-07","grade":"h2"},
{"id":"hist-h-world-07#m0","kind":"mistake","title":"자주 하는 실수","text":"악바르와 아우랑제브의 정책을 바꿔 기억하는 실수 — 악바르는 지즈야 \"폐지\"(관용), 아우랑제브는 지즈야 \"부활\"(엄격한 이슬람 정책)입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-07","grade":"h2"},
{"id":"hist-h-world-07#m1","kind":"mistake","title":"자주 하는 실수","text":"밀레트와 예니체리를 헷갈리는 실수 — 밀레트는 비이슬람교도의 종교 공동체, 예니체리는 크리스트교도 소년을 뽑아 만든 술탄의 보병 부대입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-07","grade":"h2"},
{"id":"hist-h-world-07#m2","kind":"mistake","title":"자주 하는 실수","text":"청의 회유책과 강경책을 섞는 실수 — 만한 병용제·과거제·편찬 사업은 회유, 변발 강요·문자의 옥은 강경입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-07","grade":"h2"},
{"id":"hist-h-world-08","kind":"unit","title":"시민 혁명과 시민 사회","text":"계몽사상과 함께 일어난 미국 혁명과 프랑스 혁명의 성과와 한계, 19세기 시민 사회와 참정권 확대 운동을 살펴봅니다. 과학 혁명과 계몽사상이 인간의 권리에 대한 생각을 어떻게 바꾸었는지 설명할 수 있다. 영국 혁명·미국 혁명·프랑스 혁명의 전개와 성과를 비교할 수 있다. 시민 혁명에서 소외된 사람들과 혁명의 한계를 이해할 수 있다. 19세기 자유주의·민족…","keywords":["계몽사상","자연권","권리 장전","구제도(앙시앵 레짐)","인권 선언","빈 체제","차티스트 운동","국민 국가","크리오요"],"ref":{"tab":"concepts","idx":0},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-08","grade":"h2"},
{"id":"hist-h-world-08#c0","kind":"concept","title":"과학 혁명과 계몽사상 — 인간의 권리에 대한 자각","text":"16~17세기 유럽에서는 관찰과 실험, 수학으로 자연을 설명하려는 과학 혁명이 일어났습니다. 코페르니쿠스는 지구가 태양 둘레를 돈다는 지동설을 주장했고, 갈릴레이는 망원경 관찰로 이를 뒷받침했으며, 뉴턴은 만유인력의 법칙으로 우주의 움직임을 설명했습니다. \"자연에 법칙이 있다면 사회에도","keywords":["계몽사상","자연권"],"ref":{"tab":"concepts","idx":0},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-08","grade":"h2"},
{"id":"hist-h-world-08#c1","kind":"concept","title":"영국 혁명과 미국 혁명","text":"영국 혁명: 17세기 영국에서는 국왕과 의회가 크게 맞섰습니다. 찰스 1세가 의회를 무시하자 청교도 혁명이 일어났고, 크롬웰이 이끄는 의회파가 승리하여 1649년 국왕을 처형하고 공화정을 세웠습니다. 크롬웰의 독재 뒤 왕정이 다시 들어섰지만, 제임스 2세가 전제 정치를 펴자 의회는 16","keywords":["권리 장전"],"ref":{"tab":"concepts","idx":1},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-08","grade":"h2"},
{"id":"hist-h-world-08#c2","kind":"concept","title":"프랑스 혁명의 전개와 인권 선언, 나폴레옹","text":"18세기 프랑스는 구제도(앙시앵 레짐) 아래 있었습니다. 성직자(제1신분)와 귀족(제2신분)은 인구의 2% 정도였지만 많은 토지와 면세 특권을 누렸고, 세금은 평민인 제3신분이 냈습니다. 재정이 파탄 나자 루이 16세는 1789년 삼부회를 소집했습니다. 시기 · 전개 1789년 · 제3","keywords":["구제도(앙시앵 레짐)","인권 선언"],"ref":{"tab":"concepts","idx":2},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-08","grade":"h2"},
{"id":"hist-h-world-08#c3","kind":"concept","title":"혁명에서 소외된 사람들","text":"시민 혁명은 \"모든 사람\"의 권리를 외쳤지만, 실제로 그 권리를 누린 사람은 한정되었습니다. 여성: 프랑스 혁명에서 여성도 시위에 앞장섰지만 정치적 권리를 얻지 못했습니다. 올랭프 드 구주는 1791년 「여성과 여성 시민의 권리 선언」을 발표해 여성도 같은 권리를 가져야 한다고 주장했습","keywords":[],"ref":{"tab":"concepts","idx":3},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-08","grade":"h2"},
{"id":"hist-h-world-08#c4","kind":"concept","title":"19세기 자유주의·민족주의와 참정권 확대 운동","text":"나폴레옹이 몰락한 뒤 유럽 각국 대표는 빈 회의(1814~1815년)를 열었습니다. 오스트리아의 메테르니히가 주도한 이 회의는 프랑스 혁명 이전의 질서로 돌아가려 했습니다. 이렇게 만들어진 빈 체제는 자유주의와 민족주의 운동을 억눌렀습니다. 그러나 혁명의 이념은 사라지지 않았습니다. 그","keywords":["빈 체제","차티스트 운동"],"ref":{"tab":"concepts","idx":4},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-08","grade":"h2"},
{"id":"hist-h-world-08#c5","kind":"concept","title":"국민 국가의 형성","text":"19세기에는 같은 언어·역사·문화를 나눈 사람들이 하나의 나라를 이루려는 민족주의가 커지며 국민 국가가 만들어졌습니다. 이탈리아 통일: 여러 나라로 나뉘어 있던 이탈리아는 사르데냐 왕국이 중심이 되었습니다. 재상 카보우르가 북부를 통합하고, 가리발디가 의용군(붉은 셔츠단)을 이끌고 남부","keywords":["국민 국가"],"ref":{"tab":"concepts","idx":5},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-08","grade":"h2"},
{"id":"hist-h-world-08#t0","kind":"term","title":"계몽사상","text":"18세기 유럽에서 인간의 이성을 믿고 낡은 관습과 특권을 비판한 사상입니다. 시민 혁명의 사상적 바탕이 되었습니다.","keywords":["계몽사상"],"ref":{"tab":"terms","idx":0},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-08","grade":"h2"},
{"id":"hist-h-world-08#t1","kind":"term","title":"자연권","text":"사람이 태어날 때부터 가지는, 누구도 빼앗을 수 없는 권리입니다. 로크는 생명·자유·재산을 들었습니다.","keywords":["자연권"],"ref":{"tab":"terms","idx":1},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-08","grade":"h2"},
{"id":"hist-h-world-08#t2","kind":"term","title":"권리 장전","text":"1689년 명예혁명 뒤 영국 국왕이 승인한 문서로, 의회의 동의 없는 과세와 법률 정지를 금지하여 입헌 군주제의 기틀을 마련했습니다.","keywords":["권리 장전"],"ref":{"tab":"terms","idx":2},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-08","grade":"h2"},
{"id":"hist-h-world-08#t3","kind":"term","title":"구제도(앙시앵 레짐)","text":"프랑스 혁명 이전의 신분제 사회입니다. 성직자·귀족이 특권을 누리고 평민(제3신분)이 세금을 졌습니다.","keywords":["구제도(앙시앵 레짐)"],"ref":{"tab":"terms","idx":3},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-08","grade":"h2"},
{"id":"hist-h-world-08#t4","kind":"term","title":"인권 선언","text":"1789년 프랑스 국민 의회가 발표한 「인간과 시민의 권리 선언」입니다. 자유·평등, 국민 주권, 재산권을 밝혔습니다.","keywords":["인권 선언"],"ref":{"tab":"terms","idx":4},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-08","grade":"h2"},
{"id":"hist-h-world-08#t5","kind":"term","title":"빈 체제","text":"나폴레옹 몰락 뒤 빈 회의(1814~1815년)로 만들어진 유럽 질서입니다. 혁명 이전으로 돌아가려 하며 자유주의·민족주의를 억눌렀습니다.","keywords":["빈 체제"],"ref":{"tab":"terms","idx":5},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-08","grade":"h2"},
{"id":"hist-h-world-08#t6","kind":"term","title":"차티스트 운동","text":"1830년대 말부터 영국 노동자들이 「인민헌장」을 내걸고 성인 남성의 보통 선거, 비밀 투표 등을 요구한 운동입니다.","keywords":["차티스트 운동"],"ref":{"tab":"terms","idx":6},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-08","grade":"h2"},
{"id":"hist-h-world-08#t7","kind":"term","title":"국민 국가","text":"같은 언어·역사·문화를 공유한다고 여기는 국민이 주권을 가지고 하나의 정부 아래 모인 나라입니다.","keywords":["국민 국가"],"ref":{"tab":"terms","idx":7},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-08","grade":"h2"},
{"id":"hist-h-world-08#t8","kind":"term","title":"크리오요","text":"라틴 아메리카에서 태어난 백인입니다. 19세기 초 라틴 아메리카 독립운동을 이끌었습니다.","keywords":["크리오요"],"ref":{"tab":"terms","idx":8},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-08","grade":"h2"},
{"id":"hist-h-world-08#f0","kind":"faq","title":"명예혁명은 왜 \"명예\"혁명이라고 불러요?","text":"1688년 의회가 제임스 2세를 몰아내고 메리와 윌리엄을 왕으로 맞을 때 큰 전투나 피 흘림 없이 정권이 바뀌었기 때문입니다. 그래서 \"피를 흘리지 않은 혁명\"이라는 뜻으로 명예혁명이라고 부릅니다. 그 결과 권리 장전이 승인되어 의회 중심 정치의 기틀이 마련되었습니다.","keywords":[],"ref":{"tab":"faq","idx":0},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-08","grade":"h2"},
{"id":"hist-h-world-08#f1","kind":"faq","title":"프랑스 혁명은 자유를 외쳤는데 왜 공포 정치가 일어났어요?","text":"혁명 정부는 안으로는 왕당파와 반혁명 세력의 반란, 밖으로는 혁명을 막으려는 여러 나라의 군대와 싸워야 했습니다. 이런 위기 속에서 로베스피에르는 혁명을 지킨다는 이유로 반대파를 대거 처형하는 공포 정치를 폈습니다. 혁명의 이상과 실제 정치가 어긋난 사례로, 결국 반발을 불러 로베스피에르는 1794년 몰락했습니다.","keywords":[],"ref":{"tab":"faq","idx":1},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-08","grade":"h2"},
{"id":"hist-h-world-08#f2","kind":"faq","title":"자유주의랑 민족주의는 어떻게 달라요?","text":"자유주의는 개인의 자유와 권리를 보장하고 헌법과 의회로 정치를 하자는 생각입니다. 민족주의는 같은 민족이 하나의 독립된 나라를 이루어야 한다는 생각입니다. 19세기 초에는 둘이 함께 빈 체제에 맞섰습니다. 다만 독일 통일처럼 민족주의가 자유주의보다 국가의 힘을 앞세우는 방향으로 나아가기도 했습니다.","keywords":[],"ref":{"tab":"faq","idx":2},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-08","grade":"h2"},
{"id":"hist-h-world-08#m0","kind":"mistake","title":"자주 하는 실수","text":"권리 장전·독립 선언·인권 선언을 섞는 실수 — 권리 장전은 영국(1689년), 독립 선언은 미국(1776년), 인권 선언은 프랑스(1789년)입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-08","grade":"h2"},
{"id":"hist-h-world-08#m1","kind":"mistake","title":"자주 하는 실수","text":"이탈리아와 독일 통일의 중심을 바꿔 기억하는 실수 — 이탈리아는 사르데냐 왕국(카보우르·가리발디), 독일은 프로이센(비스마르크)입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-08","grade":"h2"},
{"id":"hist-h-world-08#m2","kind":"mistake","title":"자주 하는 실수","text":"남북 전쟁에서 남부와 북부의 주장을 거꾸로 기억하는 실수 — 북부는 보호 무역·노예제 반대, 남부는 자유 무역·노예제 유지입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-08","grade":"h2"},
{"id":"hist-h-world-09","kind":"unit","title":"산업 혁명과 제국주의","text":"제1·2차 산업 혁명이 가져온 경제·사회·생태환경의 변화를 분석하고, 그 흐름이 제국주의와 아시아·아프리카 분할로 이어진 과정을 이해합니다. 제1차 산업 혁명이 영국에서 시작된 배경과 면직물 공업·증기 기관·공장제의 변화를 설명할 수 있다. 제2차 산업 혁명의 특징과 독점 자본의 형성 과정을 설명할 수 있다. 산업 자본주의가 낳은 노동 문제·도시 문제·생…","keywords":["산업 혁명","공장제 기계 공업","인클로저 운동","독점 자본","트러스트","러다이트 운동","사회주의","사회 진화론","제국주의","베를린 회의"],"ref":{"tab":"concepts","idx":0},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-09","grade":"h2"},
{"id":"hist-h-world-09#c0","kind":"concept","title":"제1차 산업 혁명 — 면직물 공업, 증기 기관, 공장제","text":"산업 혁명은 기계와 새로운 동력을 써서 물건을 대량으로 생산하게 되면서 경제와 사회 전체가 크게 바뀐 일을 말합니다. 18세기 후반 영국에서 처음 시작되었습니다. 영국에서 먼저 시작된 까닭 인클로저 운동으로 농촌에서 밀려난 사람들이 도시로 몰려 노동력이 풍부했습니다. 석탄과 철 같은 지","keywords":["산업 혁명","인클로저 운동"],"ref":{"tab":"concepts","idx":0},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-09","grade":"h2"},
{"id":"hist-h-world-09#c1","kind":"concept","title":"제2차 산업 혁명과 독점 자본","text":"19세기 후반에는 산업 혁명이 새로운 단계로 들어섰습니다. 이를 제2차 산업 혁명이라고 합니다. 구분 · 제1차 산업 혁명 · 제2차 산업 혁명 시기 · 18세기 후반~19세기 전반 · 19세기 후반~20세기 초 중심 산업 · 면직물 등 경공업 · 철강·화학·전기 등 중화학 공업 주요 ","keywords":["산업 혁명","독점 자본"],"ref":{"tab":"concepts","idx":1},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-09","grade":"h2"},
{"id":"hist-h-world-09#c2","kind":"concept","title":"산업 자본주의와 노동 문제, 사회주의 사상","text":"산업 혁명으로 공장과 기계를 가진 산업 자본가와, 노동력을 제공하고 임금을 받는 노동자가 사회의 두 주요 계층이 되었습니다. 자본가가 이윤을 얻으려고 상품을 생산하는 이 경제 체제를 산업 자본주의라고 합니다. 자본가들은 정부가 경제에 간섭하지 말아야 한다는 자유방임주의를 지지했습니다. ","keywords":["산업 혁명","러다이트 운동","사회주의"],"ref":{"tab":"concepts","idx":2},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-09","grade":"h2"},
{"id":"hist-h-world-09#c3","kind":"concept","title":"산업화·도시화와 생태환경","text":"공장이 모인 곳으로 사람이 몰리면서 도시화가 빠르게 진행되었습니다. 맨체스터 같은 공업 도시는 수십 년 만에 인구가 몇 배로 늘었습니다. 도시 문제 — 집은 모자랐고, 노동자들은 햇빛이 잘 들지 않는 좁은 집에 모여 살았습니다. 상하수도가 제대로 갖춰지지 않아 오물이 강으로 흘러들었고,","keywords":[],"ref":{"tab":"concepts","idx":3},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-09","grade":"h2"},
{"id":"hist-h-world-09#c4","kind":"concept","title":"제국주의의 등장과 아시아·아프리카 분할","text":"19세기 후반 서양 열강은 다른 지역을 식민지로 삼아 지배하려고 치열하게 경쟁했습니다. 이러한 대외 팽창 정책을 제국주의라고 합니다. 제국주의가 나타난 배경 경제: 독점 자본이 원료 공급지, 상품 시장, 남는 자본의 투자처를 찾았습니다. 사상: 생물의 진화론을 사회에 잘못 적용한 사회 ","keywords":["독점 자본","사회 진화론","제국주의","베를린 회의"],"ref":{"tab":"concepts","idx":4},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-09","grade":"h2"},
{"id":"hist-h-world-09#t0","kind":"term","title":"산업 혁명","text":"기계와 새로운 동력을 써서 물건을 대량 생산하게 되면서 경제와 사회 전체가 크게 바뀐 일입니다. 18세기 후반 영국에서 시작되었습니다.","keywords":["산업 혁명"],"ref":{"tab":"terms","idx":0},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-09","grade":"h2"},
{"id":"hist-h-world-09#t1","kind":"term","title":"공장제 기계 공업","text":"노동자들이 공장에 모여 기계로 물건을 대량 생산하는 방식입니다. 산업 혁명으로 가내 수공업을 대신했습니다.","keywords":["공장제 기계 공업"],"ref":{"tab":"terms","idx":1},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-09","grade":"h2"},
{"id":"hist-h-world-09#t2","kind":"term","title":"인클로저 운동","text":"영국에서 지주들이 공동으로 쓰던 땅이나 농지에 울타리를 쳐서 사유지로 만든 일입니다. 땅을 잃은 농민이 도시로 가서 노동자가 되었습니다.","keywords":["인클로저 운동"],"ref":{"tab":"terms","idx":2},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-09","grade":"h2"},
{"id":"hist-h-world-09#t3","kind":"term","title":"독점 자본","text":"몇몇 대기업이 경쟁 기업을 흡수하거나 협정을 맺어 시장을 지배하게 된 거대한 자본입니다. 카르텔·트러스트·콘체른 같은 형태가 있습니다.","keywords":["독점 자본"],"ref":{"tab":"terms","idx":3},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-09","grade":"h2"},
{"id":"hist-h-world-09#t4","kind":"term","title":"트러스트","text":"같은 업종의 기업들이 하나의 기업으로 합쳐지는 독점 형태입니다.","keywords":["트러스트"],"ref":{"tab":"terms","idx":4},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-09","grade":"h2"},
{"id":"hist-h-world-09#t5","kind":"term","title":"러다이트 운동","text":"19세기 초 영국에서 일자리를 빼앗는다고 여긴 기계를 노동자들이 부순 운동입니다.","keywords":["러다이트 운동"],"ref":{"tab":"terms","idx":5},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-09","grade":"h2"},
{"id":"hist-h-world-09#t6","kind":"term","title":"사회주의","text":"생산 수단을 사회가 함께 소유하여 자본주의의 불평등을 없애려는 사상입니다. 마르크스와 엥겔스의 「공산당 선언」(1848년)이 대표적입니다.","keywords":["사회주의"],"ref":{"tab":"terms","idx":6},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-09","grade":"h2"},
{"id":"hist-h-world-09#t7","kind":"term","title":"사회 진화론","text":"생물의 진화론을 사회에 잘못 적용하여 강한 민족이 약한 민족을 지배하는 것이 자연스럽다고 본 주장입니다. 제국주의 침략을 정당화하는 데 쓰였습니다.","keywords":["사회 진화론"],"ref":{"tab":"terms","idx":7},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-09","grade":"h2"},
{"id":"hist-h-world-09#t8","kind":"term","title":"제국주의","text":"19세기 후반 열강이 다른 지역을 식민지로 삼아 정치·경제적으로 지배하려 한 대외 팽창 정책입니다.","keywords":["제국주의"],"ref":{"tab":"terms","idx":8},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-09","grade":"h2"},
{"id":"hist-h-world-09#t9","kind":"term","title":"베를린 회의","text":"1884~1885년 유럽 열강이 모여 아프리카를 먼저 실제로 점령한 나라가 차지한다는 분할 원칙을 정한 회의입니다.","keywords":["베를린 회의"],"ref":{"tab":"terms","idx":9},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-09","grade":"h2"},
{"id":"hist-h-world-09#f0","kind":"faq","title":"산업 혁명은 왜 영국에서 먼저 일어났어요?","text":"영국은 산업 혁명에 필요한 조건을 고루 갖추고 있었습니다. 인클로저 운동으로 도시에 노동력이 많았고, 석탄과 철이 풍부했으며, 무역과 식민지로 자본과 시장을 확보했습니다. 명예혁명 이후 정치가 안정되어 상공업 활동도 자유로웠습니다.","keywords":["산업 혁명"],"ref":{"tab":"faq","idx":0},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-09","grade":"h2"},
{"id":"hist-h-world-09#f1","kind":"faq","title":"카르텔, 트러스트, 콘체른은 어떻게 구별해요?","text":"합쳐지는 정도와 업종으로 구별합니다. 카르텔은 같은 업종의 기업들이 따로 있으면서 가격·생산량만 약속하는 것, 트러스트는 같은 업종의 기업들이 아예 하나로 합쳐지는 것, 콘체른은 거대 자본이 여러 업종의 기업을 거느리는 기업 집단입니다.","keywords":["트러스트"],"ref":{"tab":"faq","idx":1},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-09","grade":"h2"},
{"id":"hist-h-world-09#f2","kind":"faq","title":"사회 진화론은 다윈의 진화론이랑 같은 거예요?","text":"아닙니다. 다윈의 진화론은 생물이 환경에 적응하며 변해 왔다는 과학 이론입니다. 사회 진화론은 이 생각을 사회와 민족에 함부로 적용하여 \"강한 민족이 약한 민족을 지배하는 것이 자연스럽다\"고 주장한 것으로, 과학적 근거 없이 제국주의 침략과 인종 차별을 정당화하는 데 쓰였습니다.","keywords":["사회 진화론"],"ref":{"tab":"faq","idx":2},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-09","grade":"h2"},
{"id":"hist-h-world-09#m0","kind":"mistake","title":"자주 하는 실수","text":"제1차와 제2차 산업 혁명을 섞어 기억하는 실수 — 제1차는 영국·면직물·증기 기관, 제2차는 미국·독일·중화학 공업·전기와 석유입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-09","grade":"h2"},
{"id":"hist-h-world-09#m1","kind":"mistake","title":"자주 하는 실수","text":"러다이트 운동(기계 파괴)과 차티스트 운동(선거권 요구)을 바꾸어 기억하는 실수입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-09","grade":"h2"},
{"id":"hist-h-world-09#m2","kind":"mistake","title":"자주 하는 실수","text":"카르텔(협정)과 트러스트(합병)를 헷갈리는 실수 — 기업이 하나로 합쳐지면 트러스트입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-09","grade":"h2"},
{"id":"hist-h-world-10","kind":"unit","title":"국민 국가 건설 운동","text":"제국주의에 맞서 동아시아·인도·서아시아·동남아시아·아프리카에서 펼쳐진 개혁과 민족 운동을 살펴보고, 그 주체와 성격의 공통점과 차이점을 비교합니다. 청의 양무운동·변법자강 운동·신해혁명의 목표와 한계를 비교할 수 있다. 일본의 메이지 유신이 근대화와 제국주의화로 이어진 과정을 설명할 수 있다. 인도·오스만 제국·이란·동남아시아·아프리카의 개혁과 민족 운동…","keywords":["중체서용","변법자강 운동","삼민주의","신해혁명","메이지 유신","세포이","스와데시","탄지마트","청년 튀르크당","동유 운동"],"ref":{"tab":"concepts","idx":0},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-10","grade":"h2"},
{"id":"hist-h-world-10#c0","kind":"concept","title":"청의 개혁 — 양무운동과 변법자강 운동","text":"19세기 중엽 청은 서양 열강의 침략과 안팎의 혼란을 겪으며 여러 개혁을 시도했습니다. 아편 전쟁과 개항 — 영국은 청과의 무역 적자를 메우려고 인도산 아편을 청에 몰래 팔았습니다. 청이 아편을 단속하자 영국은 전쟁을 일으켰습니다(아편 전쟁, 1840~1842년). 패한 청은 난징 조약","keywords":["변법자강 운동"],"ref":{"tab":"concepts","idx":0},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-10","grade":"h2"},
{"id":"hist-h-world-10#c1","kind":"concept","title":"의화단 운동과 신해혁명","text":"변법자강 운동이 실패한 뒤 열강의 침략은 더 심해졌습니다. 의화단 운동(1899~1901년) — 산둥 지방에서 일어난 의화단은 \"청을 도와 서양을 몰아내자\"(부청멸양)를 외치며 철도와 교회를 공격하고 베이징의 외국 공사관을 포위했습니다. 8개국 연합군이 베이징을 점령해 진압했고, 청은 ","keywords":["변법자강 운동","삼민주의","신해혁명"],"ref":{"tab":"concepts","idx":1},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-10","grade":"h2"},
{"id":"hist-h-world-10#c2","kind":"concept","title":"일본의 메이지 유신과 제국주의화","text":"1853년 미국의 페리 함대가 와서 개항을 요구하자, 일본의 막부는 이듬해 미일 화친 조약(1854년)을 맺어 문을 열었고, 1858년에는 불평등한 미일 수호 통상 조약을 맺었습니다. 개항 뒤 물가가 오르고 불만이 커지자, 막부를 무너뜨리고 천황 중심의 정부를 세우자는 세력이 힘을 얻었","keywords":["메이지 유신"],"ref":{"tab":"concepts","idx":2},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-10","grade":"h2"},
{"id":"hist-h-world-10#c3","kind":"concept","title":"인도의 민족 운동","text":"영국 동인도 회사는 18세기 중엽부터 인도 지배를 넓혀 갔습니다. 영국산 기계 면직물이 밀려들면서 인도의 전통 면직물 수공업이 무너졌고, 인도는 영국에 면화 같은 원료를 공급하고 영국 상품을 사 주는 시장이 되었습니다. 세포이 항쟁(1857~1859년) — 세포이는 동인도 회사에 고용된","keywords":["세포이"],"ref":{"tab":"concepts","idx":3},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-10","grade":"h2"},
{"id":"hist-h-world-10#c4","kind":"concept","title":"오스만 제국과 서아시아의 개혁·민족 운동","text":"19세기 오스만 제국은 영토 안의 여러 민족이 독립하려 하고 러시아 등 열강이 압박하면서 약해졌습니다. 탄지마트(1839~1876년) — \"은혜 개혁\"이라고도 하는 위로부터의 근대화 개혁입니다. 서양식 군대와 행정·교육·법 제도를 도입하고, 종교와 관계없이 모든 백성이 법 앞에 평등하다","keywords":["탄지마트","청년 튀르크당"],"ref":{"tab":"concepts","idx":4},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-10","grade":"h2"},
{"id":"hist-h-world-10#c5","kind":"concept","title":"동남아시아·아프리카의 저항과 운동의 비교","text":"동남아시아 베트남: 판보이쩌우는 일본에 유학생을 보내 인재를 기르는 동유 운동(1905년~)을 벌였습니다. 일본이 프랑스와 손잡고 유학생을 내쫓자, 그는 신해혁명의 영향을 받아 공화정을 목표로 하는 베트남 광복회(1912년)를 만들었습니다. 필리핀: 호세 리살이 에스파냐 지배의 부당함을","keywords":["신해혁명","동유 운동"],"ref":{"tab":"concepts","idx":5},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-10","grade":"h2"},
{"id":"hist-h-world-10#t0","kind":"term","title":"중체서용","text":"중국의 전통(중체)은 지키고 서양의 기술(서용)만 받아들이자는 생각입니다. 양무운동의 바탕이 되었습니다.","keywords":["중체서용"],"ref":{"tab":"terms","idx":0},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-10","grade":"h2"},
{"id":"hist-h-world-10#t1","kind":"term","title":"변법자강 운동","text":"1898년 캉유웨이·량치차오 등이 메이지 유신을 본보기로 입헌 군주제를 목표로 추진한 청의 개혁입니다. 보수파의 정변으로 100여 일 만에 실패했습니다.","keywords":["변법자강 운동"],"ref":{"tab":"terms","idx":1},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-10","grade":"h2"},
{"id":"hist-h-world-10#t2","kind":"term","title":"삼민주의","text":"쑨원이 내세운 민족주의·민권주의·민생주의의 세 원칙입니다.","keywords":["삼민주의"],"ref":{"tab":"terms","idx":2},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-10","grade":"h2"},
{"id":"hist-h-world-10#t3","kind":"term","title":"신해혁명","text":"1911년 우창 봉기로 시작되어 청을 무너뜨리고 1912년 중화민국을 세운 혁명입니다.","keywords":["신해혁명"],"ref":{"tab":"terms","idx":3},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-10","grade":"h2"},
{"id":"hist-h-world-10#t4","kind":"term","title":"메이지 유신","text":"1868년 막부가 무너진 뒤 일본의 천황 중심 정부가 추진한 서구식 근대화 개혁입니다.","keywords":["메이지 유신"],"ref":{"tab":"terms","idx":4},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-10","grade":"h2"},
{"id":"hist-h-world-10#t5","kind":"term","title":"세포이","text":"영국 동인도 회사에 고용된 인도인 병사입니다. 1857년 세포이 항쟁을 일으켰습니다.","keywords":["세포이"],"ref":{"tab":"terms","idx":5},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-10","grade":"h2"},
{"id":"hist-h-world-10#t6","kind":"term","title":"스와데시","text":"\"국산품 애용\"이라는 뜻으로, 1906년 인도 국민 회의 콜카타 대회의 4대 강령 가운데 하나입니다. 함께 내건 스와라지는 \"자치\"라는 뜻입니다.","keywords":["스와데시"],"ref":{"tab":"terms","idx":6},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-10","grade":"h2"},
{"id":"hist-h-world-10#t7","kind":"term","title":"탄지마트","text":"1839년부터 오스만 제국이 추진한 서양식 근대화 개혁입니다. \"은혜 개혁\"이라고도 합니다.","keywords":["탄지마트"],"ref":{"tab":"terms","idx":7},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-10","grade":"h2"},
{"id":"hist-h-world-10#t8","kind":"term","title":"청년 튀르크당","text":"1908년 혁명을 일으켜 정지되었던 오스만 제국의 헌법을 되살린 젊은 장교·지식인 세력입니다.","keywords":["청년 튀르크당"],"ref":{"tab":"terms","idx":8},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-10","grade":"h2"},
{"id":"hist-h-world-10#t9","kind":"term","title":"동유 운동","text":"베트남의 판보이쩌우가 일본에 유학생을 보내 독립운동 인재를 기르려 한 운동입니다(1905년~).","keywords":["동유 운동"],"ref":{"tab":"terms","idx":9},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-10","grade":"h2"},
{"id":"hist-h-world-10#f0","kind":"faq","title":"양무운동이랑 변법자강 운동은 뭐가 달라요?","text":"바꾸려 한 범위가 다릅니다. 양무운동은 \"중국의 전통은 지키고 서양의 기술만 받아들이자\"는 중체서용을 내세워 무기와 공장을 들여왔습니다. 변법자강 운동은 기술만으로는 안 된다고 보고 메이지 유신을 본받아 헌법과 의회를 갖춘 입헌 군주제로 정치 제도까지 바꾸려 했습니다.","keywords":["변법자강 운동"],"ref":{"tab":"faq","idx":0},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-10","grade":"h2"},
{"id":"hist-h-world-10#f1","kind":"faq","title":"세포이가 뭐예요?","text":"세포이는 영국 동인도 회사에 고용된 인도인 병사를 말합니다. 1857년 새 탄약에 소와 돼지의 기름이 쓰였다는 소문을 계기로 세포이들이 봉기했고, 농민과 옛 지배층이 함께하며 큰 반영 항쟁으로 번졌습니다.","keywords":["세포이"],"ref":{"tab":"faq","idx":1},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-10","grade":"h2"},
{"id":"hist-h-world-10#f2","kind":"faq","title":"메이지 유신은 성공했는데 왜 다른 나라 개혁은 잘 안 됐어요?","text":"나라마다 조건이 달랐습니다. 청과 오스만 제국은 이미 열강에게 많은 이권을 빼앗겼고, 외국 빚과 보수 세력의 반발, 열강의 간섭이 개혁을 가로막았습니다. 일본은 비교적 이른 시기에 강력한 중앙 정부를 세워 개혁을 밀어붙였습니다. 다만 일본의 \"성공\"은 이웃 나라 침략으로 이어졌다는 점을 함께 보아야 합니다.","keywords":["메이지 유신"],"ref":{"tab":"faq","idx":2},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-10","grade":"h2"},
{"id":"hist-h-world-10#m0","kind":"mistake","title":"자주 하는 실수","text":"태평천국 운동과 의화단 운동을 섞는 실수 — 태평천국은 청을 무너뜨리려 한 농민 운동(멸만흥한), 의화단은 청을 도와 서양을 몰아내자고 한 운동(부청멸양)입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-10","grade":"h2"},
{"id":"hist-h-world-10#m1","kind":"mistake","title":"자주 하는 실수","text":"스와데시(국산품 애용)와 스와라지(자치)를 바꾸어 기억하는 실수입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-10","grade":"h2"},
{"id":"hist-h-world-10#m2","kind":"mistake","title":"자주 하는 실수","text":"탄지마트·미드하트 헌법(오스만 제국)과 입헌 혁명(이란)을 같은 나라의 일로 보는 실수입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-10","grade":"h2"},
{"id":"hist-h-world-11","kind":"unit","title":"두 차례의 세계 대전","text":"두 차례 세계 대전이 나라의 모든 힘을 동원한 총력전이었음을 이해하고, 전쟁 속 대량 살상과 인권 침해, 과학 기술의 문제, 평화를 위한 전후의 노력을 살펴봅니다. 제1차 세계 대전의 배경과 전개를 총력전의 특징과 함께 설명할 수 있다. 러시아 혁명, 베르사유 체제, 전후 아시아의 민족 운동을 설명할 수 있다. 대공황과 전체주의의 등장이 제2차 세계 대전…","keywords":["총력전","볼셰비키","민족 자결주의","국제 연맹","5·4 운동","뉴딜 정책","전체주의","홀로코스트","국제 연합","세계 인권 선언"],"ref":{"tab":"concepts","idx":0},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-11","grade":"h2"},
{"id":"hist-h-world-11#c0","kind":"concept","title":"제1차 세계 대전과 총력전","text":"배경 — 19세기 말 유럽 열강은 식민지와 세력권을 두고 두 진영으로 갈라졌습니다. 3국 동맹: 독일·오스트리아-헝가리·이탈리아 3국 협상: 영국·프랑스·러시아 발칸반도에서는 독일·오스트리아가 내세운 범게르만주의와 러시아·세르비아가 내세운 범슬라브주의가 부딪혀 이곳이 \"유럽의 화약고\"라","keywords":["총력전"],"ref":{"tab":"concepts","idx":0},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-11","grade":"h2"},
{"id":"hist-h-world-11#c1","kind":"concept","title":"러시아 혁명","text":"러시아는 전쟁이 길어지면서 식량과 연료가 모자라고 패전이 이어져 민중의 불만이 커졌습니다. 3월 혁명(1917년, 러시아 달력으로는 2월) — 수도 페트로그라드에서 노동자와 병사들이 \"빵과 평화\"를 외치며 봉기했습니다. 황제 니콜라이 2세가 물러나 로마노프 왕조가 무너지고 임시 정부가 ","keywords":["볼셰비키"],"ref":{"tab":"concepts","idx":1},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-11","grade":"h2"},
{"id":"hist-h-world-11#c2","kind":"concept","title":"베르사유 체제와 전후 아시아의 민족 운동","text":"파리 강화 회의(1919년) — 전쟁에서 이긴 나라들은 파리에 모여 전후 처리를 논의했습니다. 미국 대통령 윌슨은 14개조 평화 원칙을 내놓았는데, 그 가운데 각 민족이 자기 운명을 스스로 결정해야 한다는 민족 자결주의가 큰 관심을 모았습니다. 그러나 민족 자결주의는 패전국이 지배하던 ","keywords":["민족 자결주의","국제 연맹"],"ref":{"tab":"concepts","idx":2},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-11","grade":"h2"},
{"id":"hist-h-world-11#c3","kind":"concept","title":"대공황과 전체주의의 등장","text":"대공황 — 1920년대 미국은 큰 호황을 누렸지만 생산이 소비보다 지나치게 많아졌습니다. 1929년 10월 미국 뉴욕 주식 시장의 주가가 크게 떨어지자 기업과 은행이 잇달아 문을 닫고 실업자가 쏟아졌습니다. 미국 자본에 기대던 유럽 경제도 흔들리면서 위기는 전 세계로 퍼졌습니다(대공황)","keywords":["뉴딜 정책","전체주의"],"ref":{"tab":"concepts","idx":3},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-11","grade":"h2"},
{"id":"hist-h-world-11#c4","kind":"concept","title":"제2차 세계 대전과 대량 학살·인권 침해","text":"전쟁의 시작 — 독일은 소련과 불가침 조약을 맺은 뒤 1939년 9월 폴란드를 침공했습니다. 영국과 프랑스가 독일에 선전 포고하면서 제2차 세계 대전이 시작되었습니다. 독일은 1940년 프랑스를 점령했고, 1941년에는 조약을 깨고 소련을 침공했습니다. 태평양 전쟁 — 중일 전쟁을 벌이","keywords":[],"ref":{"tab":"concepts","idx":4},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-11","grade":"h2"},
{"id":"hist-h-world-11#c5","kind":"concept","title":"전쟁과 과학 기술, 그리고 평화를 위한 약속","text":"전쟁과 과학 기술 — 두 세계 대전에서는 과학 기술이 대량 살상에 쓰였습니다. 독가스: 제1차 세계 대전에서 독일이 처음 대규모로 사용한 뒤 여러 나라가 썼습니다. 독일의 독가스 개발을 이끈 화학자 하버는 공기 중의 질소로 암모니아를 합성하는 방법을 개발해 비료 생산에 크게 이바지한 사","keywords":[],"ref":{"tab":"concepts","idx":5},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-11","grade":"h2"},
{"id":"hist-h-world-11#t0","kind":"term","title":"총력전","text":"군대뿐 아니라 나라의 모든 사람과 자원, 산업을 전쟁에 동원하는 전쟁입니다. 두 차례 세계 대전이 대표적입니다.","keywords":["총력전"],"ref":{"tab":"terms","idx":0},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-11","grade":"h2"},
{"id":"hist-h-world-11#t1","kind":"term","title":"볼셰비키","text":"레닌이 이끈 러시아 사회주의 세력입니다. 1917년 11월 혁명으로 소비에트 정부를 세웠습니다.","keywords":["볼셰비키"],"ref":{"tab":"terms","idx":1},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-11","grade":"h2"},
{"id":"hist-h-world-11#t2","kind":"term","title":"민족 자결주의","text":"각 민족이 자기 운명을 스스로 결정해야 한다는 원칙입니다. 1919년 파리 강화 회의에서 윌슨이 내세웠으나 패전국의 식민지에만 적용되었습니다.","keywords":["민족 자결주의"],"ref":{"tab":"terms","idx":2},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-11","grade":"h2"},
{"id":"hist-h-world-11#t3","kind":"term","title":"국제 연맹","text":"1920년 세계 평화를 위해 세운 최초의 국제 평화 기구입니다. 미국이 가입하지 않았고 군사적 제재 수단이 없었습니다.","keywords":["국제 연맹"],"ref":{"tab":"terms","idx":3},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-11","grade":"h2"},
{"id":"hist-h-world-11#t4","kind":"term","title":"5·4 운동","text":"1919년 파리 강화 회의의 결정에 반대하여 베이징 학생들이 시작한 중국의 반제국주의·반봉건 운동입니다.","keywords":["5·4 운동"],"ref":{"tab":"terms","idx":4},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-11","grade":"h2"},
{"id":"hist-h-world-11#t5","kind":"term","title":"뉴딜 정책","text":"대공황을 극복하려고 미국 루스벨트 대통령이 펼친 정책입니다. 정부가 공공사업·사회 보장 등으로 경제에 적극 개입했습니다.","keywords":["뉴딜 정책"],"ref":{"tab":"terms","idx":5},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-11","grade":"h2"},
{"id":"hist-h-world-11#t6","kind":"term","title":"전체주의","text":"개인보다 국가와 민족을 앞세우고 독재로 국민의 자유를 억압하는 체제입니다. 이탈리아의 파시즘, 독일의 나치즘, 일본의 군국주의가 대표적입니다.","keywords":["전체주의"],"ref":{"tab":"terms","idx":6},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-11","grade":"h2"},
{"id":"hist-h-world-11#t7","kind":"term","title":"홀로코스트","text":"제2차 세계 대전 중 나치 독일이 유대인 약 600만 명 등을 조직적으로 학살한 일입니다.","keywords":["홀로코스트"],"ref":{"tab":"terms","idx":7},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-11","grade":"h2"},
{"id":"hist-h-world-11#t8","kind":"term","title":"국제 연합","text":"1945년 세계 평화와 안전을 위해 세운 국제기구(UN)입니다. 안전 보장 이사회가 군사 조치를 결정할 수 있습니다.","keywords":["국제 연합"],"ref":{"tab":"terms","idx":8},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-11","grade":"h2"},
{"id":"hist-h-world-11#t9","kind":"term","title":"세계 인권 선언","text":"1948년 국제 연합 총회에서 채택한 선언으로, 모든 사람이 차별 없이 누려야 할 기본적인 권리를 밝혔습니다.","keywords":["세계 인권 선언"],"ref":{"tab":"terms","idx":9},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-11","grade":"h2"},
{"id":"hist-h-world-11#f0","kind":"faq","title":"러시아의 3월 혁명이랑 2월 혁명은 같은 거예요?","text":"네, 같은 혁명입니다. 당시 러시아가 쓰던 달력(율리우스력)으로는 2월, 오늘날 우리가 쓰는 달력으로는 3월이라서 두 이름이 함께 쓰입니다. 11월 혁명도 러시아 달력으로는 10월이라 \"10월 혁명\"이라고도 부릅니다.","keywords":[],"ref":{"tab":"faq","idx":0},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-11","grade":"h2"},
{"id":"hist-h-world-11#f1","kind":"faq","title":"민족 자결주의가 발표됐는데 왜 한국은 독립하지 못했어요?","text":"민족 자결주의는 전쟁에서 진 나라(독일·오스트리아·오스만 제국 등)가 지배하던 지역에만 적용되었습니다. 일본은 제1차 세계 대전의 승전국이었기 때문에 한국은 적용 대상이 아니었습니다. 그래도 이 원칙은 3·1 운동 등 식민지 민족 운동을 자극했습니다.","keywords":["민족 자결주의"],"ref":{"tab":"faq","idx":1},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-11","grade":"h2"},
{"id":"hist-h-world-11#f2","kind":"faq","title":"국제 연맹이랑 국제 연합은 뭐가 달라요?","text":"국제 연맹(1920년)은 제1차 세계 대전 뒤, 국제 연합(1945년)은 제2차 세계 대전 뒤에 만들어졌습니다. 국제 연맹은 미국이 가입하지 않았고 침략국을 막을 군사 수단이 없었지만, 국제 연합은 강대국이 모두 참여하고 안전 보장 이사회가 경제 제재와 군사 조치를 결정할 수 있습니다.","keywords":["국제 연맹","국제 연합"],"ref":{"tab":"faq","idx":2},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-11","grade":"h2"},
{"id":"hist-h-world-11#m0","kind":"mistake","title":"자주 하는 실수","text":"러시아의 3월 혁명(황제 퇴위, 임시 정부 수립)과 11월 혁명(레닌, 소비에트 정부 수립)을 바꾸어 기억하는 실수입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-11","grade":"h2"},
{"id":"hist-h-world-11#m1","kind":"mistake","title":"자주 하는 실수","text":"민족 자결주의가 모든 식민지에 적용되었다고 생각하는 실수 — 패전국의 식민지에만 적용되었습니다.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-11","grade":"h2"},
{"id":"hist-h-world-11#m2","kind":"mistake","title":"자주 하는 실수","text":"국제 연맹에 미국이 가입했다고 생각하는 실수 — 윌슨이 제안했지만 미국은 가입하지 않았습니다.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-11","grade":"h2"},
{"id":"hist-h-world-12","kind":"unit","title":"냉전과 현대 세계의 과제","text":"냉전의 전개와 대결 속에서 달라진 사회와 문화를 분석하고, 민주주의·평화·불평등·생태환경 같은 오늘날의 과제와 이를 해결하려는 인류의 노력을 탐구합니다. 냉전의 전개 과정과 대표적인 갈등을 설명할 수 있다. 냉전이 각 사회의 정치·문화에 끼친 영향을 분석할 수 있다. 탈식민지화와 제3 세계의 등장, 냉전의 종식 과정을 설명할 수 있다. 민주주의·평화·불평…","keywords":["냉전","트루먼 독트린","마셜 계획","북대서양 조약 기구","데탕트","제3 세계","페레스트로이카","아파르트헤이트","세계화","지속가능한 발전"],"ref":{"tab":"concepts","idx":0},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-12","grade":"h2"},
{"id":"hist-h-world-12#c0","kind":"concept","title":"냉전의 전개와 대표적인 갈등","text":"냉전은 제2차 세계 대전 뒤 미국 중심의 자본주의 진영과 소련 중심의 공산주의 진영이, 서로 전면전은 벌이지 않으면서 정치·경제·군사·이념 등 모든 면에서 대립한 상태를 말합니다. 냉전의 시작 소련이 동유럽에 공산 정권을 세우자, 미국은 공산주의의 확산을 막겠다는 트루먼 독트린(1947","keywords":["냉전","트루먼 독트린","마셜 계획","북대서양 조약 기구"],"ref":{"tab":"concepts","idx":0},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-12","grade":"h2"},
{"id":"hist-h-world-12#c1","kind":"concept","title":"냉전이 바꾼 사회와 문화","text":"냉전은 국제 관계뿐 아니라 각 나라 사람들의 일상과 생각에도 큰 영향을 주었습니다. 반공주의와 사상 통제 — 미국에서는 1950년대 초 공산주의자를 찾아낸다며 많은 사람을 근거 없이 의심하고 몰아세운 매카시즘이 일어났습니다. 소련과 동유럽에서는 공산당이 언론과 사상을 통제하고 정부를 비","keywords":["냉전"],"ref":{"tab":"concepts","idx":1},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-12","grade":"h2"},
{"id":"hist-h-world-12#c2","kind":"concept","title":"탈식민지화와 제3 세계, 냉전의 종식","text":"탈식민지화 — 제2차 세계 대전 뒤 아시아와 아프리카의 식민지들이 잇달아 독립했습니다. 아시아: 필리핀(1946년), 인도와 파키스탄(1947년, 종교 갈등으로 나뉘어 독립), 인도네시아(1945년 독립 선언, 네덜란드와 싸운 끝에 1949년 인정) 등이 독립했습니다. 아프리카: 195","keywords":["냉전","제3 세계"],"ref":{"tab":"concepts","idx":2},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-12","grade":"h2"},
{"id":"hist-h-world-12#c3","kind":"concept","title":"민주주의와 평화를 위한 노력","text":"민주화 운동 — 냉전 시기 여러 나라에서는 반공이나 경제 개발을 앞세운 독재 정권이 들어서기도 했습니다. 사람들은 자유와 인권을 지키려고 민주화 운동을 벌였습니다. 미국: 흑인에 대한 차별에 맞서 마틴 루서 킹 등이 비폭력 민권 운동을 이끌었고, 1964년 민권법으로 인종 차별을 금지했","keywords":["냉전","아파르트헤이트"],"ref":{"tab":"concepts","idx":3},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-12","grade":"h2"},
{"id":"hist-h-world-12#c4","kind":"concept","title":"경제적 불평등과 세계화의 과제","text":"세계화 — 냉전이 끝난 뒤 상품·자본·사람·정보가 국경을 넘어 자유롭게 오가는 세계화가 빠르게 진행되었습니다. 1995년 세계 무역 기구(WTO)가 출범하여 자유 무역을 넓혔습니다. 유럽 연합(EU), 북미 자유 무역 협정(NAFTA), 아시아·태평양 경제 협력체(APEC) 같은 지역 ","keywords":["냉전","세계화"],"ref":{"tab":"concepts","idx":4},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-12","grade":"h2"},
{"id":"hist-h-world-12#c5","kind":"concept","title":"생태환경 위기와 지속가능한 발전","text":"산업화와 인구 증가, 화석 연료 사용이 늘어나면서 지구 전체가 함께 겪는 생태환경 문제가 커졌습니다. 기후 변화(지구 온난화), 오존층 파괴, 사막화, 산성비, 생물 다양성 감소, 해양 오염 등은 한 나라의 힘만으로 해결할 수 없어 국제 협력이 필요합니다. 지속가능한 발전 — 1987년","keywords":["지속가능한 발전"],"ref":{"tab":"concepts","idx":5},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-12","grade":"h2"},
{"id":"hist-h-world-12#t0","kind":"term","title":"냉전","text":"제2차 세계 대전 뒤 미국 중심의 자본주의 진영과 소련 중심의 공산주의 진영이 직접 전면전은 하지 않으면서 모든 면에서 대립한 상태입니다.","keywords":["냉전"],"ref":{"tab":"terms","idx":0},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-12","grade":"h2"},
{"id":"hist-h-world-12#t1","kind":"term","title":"트루먼 독트린","text":"1947년 미국이 공산주의의 확산을 막기 위해 위협받는 나라들을 돕겠다고 한 선언입니다.","keywords":["트루먼 독트린"],"ref":{"tab":"terms","idx":1},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-12","grade":"h2"},
{"id":"hist-h-world-12#t2","kind":"term","title":"마셜 계획","text":"제2차 세계 대전 뒤 미국이 서유럽의 경제 부흥을 돕기 위해 펼친 원조 계획입니다.","keywords":["마셜 계획"],"ref":{"tab":"terms","idx":2},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-12","grade":"h2"},
{"id":"hist-h-world-12#t3","kind":"term","title":"북대서양 조약 기구","text":"1949년 미국과 서유럽 나라들이 만든 군사 동맹(NATO)입니다. 소련과 동유럽은 바르샤바 조약 기구로 맞섰습니다.","keywords":["북대서양 조약 기구"],"ref":{"tab":"terms","idx":3},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-12","grade":"h2"},
{"id":"hist-h-world-12#t4","kind":"term","title":"데탕트","text":"1960년대 말부터 나타난 냉전의 긴장 완화를 말합니다. 닉슨 독트린과 미국 대통령의 중국 방문 등이 대표적입니다.","keywords":["데탕트"],"ref":{"tab":"terms","idx":4},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-12","grade":"h2"},
{"id":"hist-h-world-12#t5","kind":"term","title":"제3 세계","text":"냉전 시기 미국·소련 어느 진영에도 속하지 않으려 한 아시아·아프리카·라틴 아메리카의 나라들입니다.","keywords":["제3 세계"],"ref":{"tab":"terms","idx":5},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-12","grade":"h2"},
{"id":"hist-h-world-12#t6","kind":"term","title":"페레스트로이카","text":"1985년부터 소련의 고르바초프가 추진한 개혁 정책입니다. 개방 정책인 글라스노스트와 함께 추진되었습니다.","keywords":["페레스트로이카"],"ref":{"tab":"terms","idx":6},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-12","grade":"h2"},
{"id":"hist-h-world-12#t7","kind":"term","title":"아파르트헤이트","text":"남아프리카 공화국의 백인 정부가 펼친 인종 차별 정책입니다. 1990년대 초에 폐지되었습니다.","keywords":["아파르트헤이트"],"ref":{"tab":"terms","idx":7},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-12","grade":"h2"},
{"id":"hist-h-world-12#t8","kind":"term","title":"세계화","text":"상품·자본·사람·정보가 국경을 넘어 자유롭게 오가며 세계가 하나로 이어지는 현상입니다.","keywords":["세계화"],"ref":{"tab":"terms","idx":8},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-12","grade":"h2"},
{"id":"hist-h-world-12#t9","kind":"term","title":"지속가능한 발전","text":"미래 세대가 그들의 필요를 충족할 능력을 해치지 않으면서 현재 세대의 필요를 충족하는 발전입니다.","keywords":["지속가능한 발전"],"ref":{"tab":"terms","idx":9},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-12","grade":"h2"},
{"id":"hist-h-world-12#f0","kind":"faq","title":"냉전은 왜 \"차가운 전쟁\"이라고 불러요?","text":"미국과 소련이 서로 직접 총을 쏘는 \"뜨거운 전쟁\"은 벌이지 않았지만, 군사·경제·이념 등 모든 면에서 전쟁처럼 맞섰기 때문입니다. 다만 한반도의 6·25 전쟁이나 베트남 전쟁처럼 냉전 속에서 실제 전쟁이 벌어진 곳도 많았습니다.","keywords":["냉전"],"ref":{"tab":"faq","idx":0},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-12","grade":"h2"},
{"id":"hist-h-world-12#f1","kind":"faq","title":"제3 세계는 가난한 나라라는 뜻이에요?","text":"원래는 미국 중심의 제1 세계, 소련 중심의 제2 세계 어느 쪽에도 속하지 않으려 한 나라들을 가리키는 말이었습니다. 이 나라들 가운데 개발 도상국이 많아서 나중에는 개발 도상국을 가리키는 말로도 쓰이게 되었습니다.","keywords":["제3 세계"],"ref":{"tab":"faq","idx":1},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-12","grade":"h2"},
{"id":"hist-h-world-12#f2","kind":"faq","title":"교토 의정서랑 파리 협정은 뭐가 달라요?","text":"교토 의정서(1997년)는 선진국에만 온실가스 감축 의무를 주었습니다. 파리 협정(2015년)은 선진국과 개발 도상국이 모두 참여해 각 나라가 스스로 감축 목표를 정하도록 했다는 점이 다릅니다.","keywords":[],"ref":{"tab":"faq","idx":2},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-12","grade":"h2"},
{"id":"hist-h-world-12#m0","kind":"mistake","title":"자주 하는 실수","text":"트루먼 독트린(공산주의 확산을 막겠다는 선언)과 마셜 계획(서유럽 경제 원조)을 바꾸어 기억하는 실수입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-12","grade":"h2"},
{"id":"hist-h-world-12#m1","kind":"mistake","title":"자주 하는 실수","text":"페레스트로이카(개혁)와 글라스노스트(개방)를 바꾸어 기억하는 실수입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-12","grade":"h2"},
{"id":"hist-h-world-12#m2","kind":"mistake","title":"자주 하는 실수","text":"세계화 시대의 \"남북문제\"(선진국과 개발 도상국의 격차)를 한반도의 남북 분단 문제로 착각하는 실수입니다.","keywords":[],"ref":{"tab":"faq"},"subject":"hist","course":"hist-h-world","unit":"hist-h-world-12","grade":"h2"}
]);
